export default "n    router.forced_category = \\\"Neutral\\\"  # select the middle route\\n\\n    sink1, sink2, sink3 = (RecordingSink(_id=\\\"sink1\\\"), RecordingSink(_id=\\\"sink2\\\"), RecordingSink(_id=\\\"sink3\\\"))\\n    merge = MergeSink(_id=\\\"merge\\\")\\n\\n    graph = Graph()\\n    for comp, cid in ((router, \\\"router\\\"), (sink1, \\\"sink1\\\"), (sink2, \\\"sink2\\\"), (sink3, \\\"sink3\\\"), (merge, \\\"merge\\\")):\\n        graph.add_component(comp, cid)\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_1_result\\\", \\\"input_value\\\"), \\\"sink1\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_2_result\\\", \\\"input_value\\\"), \\\"sink2\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_3_result\\\", \\\"input_value\\\"), \\\"sink3\\\")\\n    graph.add_component_edge(\\\"sink1\\\", (\\\"out\\\", \\\"in1\\\"), \\\"merge\\\")\\n    graph.add_component_edge(\\\"sink2\\\", (\\\"out\\\", \\\"in2\\\"), \\\"merge\\\")\\n    graph.add_component_edge(\\\"sink3\\\", (\\\"out\\\", \\\"in3\\\"), \\\"merge\\\")\\n\\n    await _run(graph)\\n\\n    assert sink2.did_run is True, \\\"Matched (middle) branch should run\\\"\\n    assert sink1.did_run is False, \\\"Unselected branch 1 should not run\\\"\\n    assert sink3.did_run is False, \\\"Unselected branch 3 should not run\\\"\\n\\n\\nasync def test_else_branch_does_not_run_when_a_route_matches():\\n    \\\"\\\"\\\"With ``enable_else_output=True`` and a matched route, the Else branch must not run.\\n\\n    The ``default_result`` (Else) output feeds its own leaf. On a match the router excludes\\n    that branch: ``process_case`` appends ``default_result`` to its deactivation list and\\n    ``default_response`` also calls ``_deactivate_branches([\\\"default_result\\\"])``. Both paths\\n    run, so this guards the *aggregate* Else-exclusion behavior (the two paths are redundant,\\n    so it does not isolate either one). The Else leaf must stay unrun while the matched leaf\\n    and the merge node fed by the selected branch still run.\\n    \\\"\\\"\\\"\\n    router = _make_router(_ElseSmartRouter, _TWO_ROUTES, enable_else_output=True)\\n    router.forced_category = \\\"Positive\\\"  # matches route 1 -> Else must be excluded\\n\\n    selected, unselected = RecordingSink(_id=\\\"selected\\\"), RecordingSink(_id=\\\"unselected\\\")\\n    else_leaf = RecordingSink(_id=\\\"else_leaf\\\")\\n    merge = MergeSink(_id=\\\"merge\\\")\\n\\n    graph = Graph()\\n    for comp, cid in (\\n        (router, \\\"router\\\"),\\n        (selected, \\\"selected\\\"),\\n        (unselected, \\\"unselected\\\"),\\n        (else_leaf, \\\"else_leaf\\\"),\\n        (merge, \\\"merge\\\"),\\n    ):\\n        graph.add_component(comp, cid)\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_1_result\\\", \\\"input_value\\\"), \\\"selected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_2_result\\\", \\\"input_value\\\"), \\\"unselected\\\")\\n    # The Else output feeds its own (dead-end) leaf.\\n    graph.add_component_edge(\\\"router\\\", (\\\"default_result\\\", \\\"input_value\\\"), \\\"else_leaf\\\")\\n    # The selected branch reconverges with the (excluded) unselected branch on the merge node.\\n    graph.add_component_edge(\\\"selected\\\", (\\\"out\\\", \\\"in1\\\"), \\\"merge\\\")\\n    graph.add_component_edge(\\\"unselected\\\", (\\\"out\\\", \\\"in2\\\"), \\\"merge\\\")\\n\\n    yielded = await _run(graph)\\n\\n    assert selected.did_run is True\\n    assert unselected.did_run is False, \\\"Unselected route branch executed despite the match\\\"\\n    assert else_leaf.did_run is False, \\\"Else branch executed despite a matched route\\\"\\n    assert merge.did_run is True, \\\"Merge node should execute from the selected branch\\\"\\n    assert \\\"else_leaf\\\" not in yielded\\n    assert \\\"merge\\\" in yielded\\n\\n\\nasync def test_else_branch_runs_when_no_route_matches():\\n    \\\"\\\"\\\"With ``enable_else_output=True`` and no matched route, only the Else branch runs.\\n\\n    Complements the match case: ``default_response`` takes its no-match path (returns the\\n    input as default) so the Else leaf runs, while every ``category_{i}_result`` branch is\\n    deactivated by ``process_case`` and stays unrun.\\n    \\\"\\\"\\\"\\n    router = _make_router(_ElseSmartRouter, _TWO_ROUTES, enable_else_output=True)\\n    router.forced_category = \\\"NONE\\\"  # no route matches -> Else is the only live branch\\n\\n    selected, unselected = RecordingSink(_id=\\\"selected\\\"), RecordingSink(_id=\\\"unselected\\\")\\n    else_leaf = RecordingSink(_id=\\\"else_leaf\\\")\\n\\n    graph = Graph()\\n    for comp, cid in (\\n        (router, \\\"router\\\"),\\n        (selected, \\\"selected\\\"),\\n        (unselected, \\\"unselected\\\"),\\n        (else_leaf, \\\"else_leaf\\\"),\\n    ):\\n        graph.add_component(comp, cid)\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_1_result\\\", \\\"input_value\\\"), \\\"selected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"category_2_result\\\", \\\"input_value\\\"), \\\"unselected\\\")\\n    graph.add_component_edge(\\\"router\\\", (\\\"default_result\\\", \\\"input_value\\\"), \\\"else_leaf\\\")\\n\\n    yielded = await _run(graph)\\n\\n    assert else_leaf.did_run is True, \\\"Else branch should run when no route matches\\\"\\n    assert selected.did_run is False, \\\"Route branch 1 should not run when no route matches\\\"\\n    assert unselected.did_run is False, \\\"Route branch 2 should not run when no route matches\\\"\\n    assert \\\"else_leaf\\\" in yielded\\n\\n\\ndef test_update_outputs_names_match_routing_contract():\\n    \\\"\\\"\\\"Guard the output-name contract the routing logic relies on (category_{i}_result).\\\"\\\"\\\"\\n    component = SmartRouterComponent()\\n    frontend_node = component.update_outputs({\\\"outputs\\\": []}, \\\"routes\\\", _TWO_ROUTES)\\n    names = [o.name for o in frontend_node[\\\"outputs\\\"]]\\n    assert names == [\\\"category_1_result\\\", \\\"category_2_result\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/test_cache_restoration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9a62683dcb6a48e98ffb23895f724ed0de942c25e49ea9d378ec1e2c6111d715\",\"content\":\"\\\"\\\"\\\"Tests for cache restoration behavior in build_vertex.\\n\\nThis module tests the fix for the issue where cache restoration failure\\nwould leave vertex.built = True, causing subsequent build() calls to\\nreturn early without setting vertex.result.\\n\\nBug scenario (before fix):\\n1. Frozen vertex, cache hit -> vertex.built = True restored from cache\\n2. finalize_build() throws exception -> should_build = True\\n3. build() is called, but sees frozen AND built -> returns early\\n4. finalize_build() never called again -> vertex.result is None\\n5. Error: \\\"no result found for vertex\\\"\\n\\nFix:\\nReset vertex.built = False when cache restoration fails, so build()\\nruns fully and sets vertex.result correctly.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import AsyncMock, Mock\\n\\nimport pytest\\n\\n\\nclass TestCacheRestorationBuiltFlagReset:\\n    \\\"\\\"\\\"Tests for vertex.built flag reset when cache restoration fails.\\n\\n    These tests verify that when finalize_build() fails during cache\\n    restoration, vertex.built is reset to False so that subsequent\\n    build() calls work correctly.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def mock_vertex(self):\\n        \\\"\\\"\\\"Create a mock vertex for testing cache restoration.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.id = \\\"test-vertex-id\\\"\\n        vertex.frozen = True\\n        vertex.built = False\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"TestComponent\\\"\\n        vertex.result = None\\n        vertex.artifacts = {}\\n        vertex.built_object = {}\\n        vertex.built_result = {}\\n        vertex.full_data = {}\\n        vertex.results = {}\\n        vertex.build = AsyncMock()\\n        vertex.finalize_build = Mock()\\n        vertex.built_object_repr = Mock(return_value=\\\"test\\\")\\n        return vertex\\n\\n    @pytest.fixture\\n    def cached_vertex_dict(self):\\n        \\\"\\\"\\\"Create a cached vertex dictionary.\\\"\\\"\\\"\\n        return {\\n            \\\"built\\\": True,\\n            \\\"artifacts\\\": {\\\"test\\\": \\\"artifact\\\"},\\n            \\\"built_object\\\": {\\\"test\\\": \\\"object\\\"},\\n            \\\"built_result\\\": {\\\"test\\\": \\\"result\\\"},\\n            \\\"full_data\\\": {\\\"test\\\": \\\"data\\\"},\\n            \\\"results\\\": {\\\"test\\\": \\\"results\\\"},\\n        }\\n\\n    def test_should_reset_built_flag_when_finalize_build_fails(self, mock_vertex, cached_vertex_dict):\\n        \\\"\\\"\\\"Test that vertex.built is reset to False when finalize_build raises exception.\\n\\n        Given: A frozen vertex with cached state restored (built=True)\\n        When: finalize_build() throws an exception\\n        Then: vertex.built should be reset to False\\n        \\\"\\\"\\\"\\n        # Arrange\\n        mock_vertex.built = cached_vertex_dict[\\\"built\\\"]  # True from cache\\n        mock_vertex.finalize_build.side_effect = ValueError(\\\"Test error\\\")\\n\\n        # Act - simulate the cache restoration logic\\n        should_build = False\\n        try:\\n            mock_vertex.finalize_build()\\n            if mock_vertex.result is not None:\\n                mock_vertex.result.used_frozen_result = True\\n        except Exception:\\n            mock_vertex.built = False  # This is the fix\\n            should_build = True\\n\\n        # Assert\\n        assert mock_vertex.built is False, \\\"vertex.built should be reset to False after finalize_build failure\\\"\\n        assert should_build is True, \\\"should_build should be True to trigger rebuild\\\"\\n\\n    def test_should_reset_built_flag_when_key_error_on_cache_access(self, mock_vertex):\\n        \\\"\\\"\\\"Test that vertex.built is reset to False when KeyError occurs during cache access.\\n\\n        Given: A frozen vertex with partial cached state\\n        When: KeyError occurs when accessing cache dict\\n        Then: vertex.built should be reset to False\\n        \\\"\\\"\\\"\\n        # Arrange\\n        mock_vertex.built = True  # Assume it was set somehow\\n\\n        # Simulate incomplete cache dict (missing key)\\n        cached_result = {\\\"result\\\": {}}  # Missing required keys\\n\\n        # Act - simulate the cache restoration logic\\n        should_build = False\\n        try:\\n            cached_vertex_dict = cached_result[\\\"result\\\"]\\n            _ = cached_vertex_dict[\\\"built\\\"]  # This would raise KeyError\\n        except KeyError:\\n            mock_vertex.built = False  # This is the fix\\n            should_build = True\\n\\n        # Assert\\n        assert mock_vertex.built is False, \\\"vertex.built should be reset to False after KeyError\\\"\\n        assert should_build is True, \\\"should_build should be True to trigger rebuild\\\"\\n\\n    def test_build_returns_early_when_built_flag_not_reset(self, mock_vertex):\\n        \\\"\\\"\\\"Test the bug scenario: build() returns early when built=True is not reset.\\n\\n        This test demonstrates the bug that occurs WITHOUT the fix:\\n        When frozen=True and built=True, build() returns early without\\n        calling finalize_build(), leaving result=None.\\n        \\\"\\\"\\\"\\n        # Arrange - simulate the broken state (before fix)\\n        mock_vertex.frozen = True\\n        mock_vertex.built = True  # Not reset after failed cache restoration\\n        mock_vertex.result = None\\n        is_loop_component = mock_vertex.display_name == \\\"Loop\\\" or mock_vertex.is_loop\\n\\n        # Act - simulate build() decision\\n        should_return_early = mock_vertex.frozen and mock_vertex.built and not is_loop_component\\n\\n        # Assert - this is the problematic behavior\\n        assert should_return_early is True, \\\"build() would return early with unreset built flag\\\"\\n        assert mock_vertex.result is None, \\\"result remains None because finalize_build was never called\\\"\\n\\n    def test_build_continues_when_built_flag_is_reset(self, mock_vertex):\\n        \\\"\\\"\\\"Test the fix: build() continues when built=False after reset.\\n\\n        This test demonstrates the correct behavior WITH the fix:\\n        When built=False (reset after failed cache restoration), build()\\n        continues normally and calls finalize_build().\\n        \\\"\\\"\\\"\\n        # Arrange - simulate the fixed state (after fix)\\n        mock_vertex.frozen = True\\n        mock_vertex.built = False  # Reset after failed cache restoration\\n        is_loop_component = mock_vertex.display_name == \\\"Loop\\\" or mock_vertex.is_loop\\n\\n        # Act - simulate build() decision\\n        should_return_early = mock_vertex.frozen and mock_vertex.built and not is_loop_component\\n\\n        # Assert - build() should NOT return early\\n        assert should_return_early is False, \\\"build() should continue with reset built flag\\\"\\n\\n\\nclass TestCacheRestorationSuccessCase:\\n    \\\"\\\"\\\"Tests for successful cache restoration.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def mock_vertex_with_result(self):\\n        \\\"\\\"\\\"Create a mock vertex that successfully restores from cache.\\\"\\\"\\\"\\n        vertex = Mock()\\n        vertex.id = \\\"test-vertex-id\\\"\\n        vertex.frozen = True\\n        vertex.built = True\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"TestComponent\\\"\\n        vertex.result = Mock()  # Has a result\\n        vertex.artifacts = {\\\"test\\\": \\\"artifact\\\"}\\n        return vertex\\n\\n    def test_should_not_modify_built_flag_on_successful_restoration(self, mock_vertex_with_result):\\n        \\\"\\\"\\\"Test that vertex.built remains True when cache restoration succeeds.\\n\\n        Given: A frozen vertex with valid cached state\\n        When: finalize_build() succeeds\\n        Then: vertex.built should remain True and should_build should be False\\n        \\\"\\\"\\\"\\n        # Arrange\\n        mock_vertex_with_result.finalize_build = Mock()  # No exception\\n\\n        # Act - simulate successful cache restoration\\n        should_build = False\\n        try:\\n            mock_vertex_with_result.finalize_build()\\n            if mock_vertex_with_result.result is not None:\\n                mock_vertex_with_result.result.used_frozen_result = True\\n        except Exception:\\n            mock_vertex_with_result.built = False\\n            should_build = True\\n\\n        # Assert\\n        assert mock_vertex_with_result.built is True, \\\"vertex.built should remain True on success\\\"\\n        assert should_build is False, \\\"should_build should be False on success\\\"\\n        assert mock_vertex_with_result.result.used_frozen_result is True\\n\\n\\nclass TestCacheRestorationEdgeCases:\\n    \\\"\\\"\\\"Edge case tests for cache restoration.\\\"\\\"\\\"\\n\\n    def test_non_frozen_vertex_should_always_build(self):\\n        \\\"\\\"\\\"Test that non-frozen vertex always builds regardless of built flag.\\n\\n        Given: A non-frozen vertex\\n        When: Checking if should build\\n        Then: should_build should be True regardless of other flags\\n        \\\"\\\"\\\"\\n        # Arrange\\n        vertex = Mock()\\n        vertex.frozen = False\\n        vertex.built = True\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"TestComponent\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        # Act - simulate build_vertex decision\\n        should_build = not vertex.frozen or is_loop_component\\n\\n        # Assert\\n        assert should_build is True, \\\"Non-frozen vertex should always build\\\"\\n\\n    def test_cache_miss_should_trigger_build(self):\\n        \\\"\\\"\\\"Test that cache miss triggers build.\\n\\n        Given: A frozen vertex with cache miss\\n        When: Checking if should build\\n        Then: should_build should be True\\n        \\\"\\\"\\\"\\n\\n        # Arrange\\n        class CacheMiss:\\n            pass\\n\\n        cached_result = CacheMiss()\\n\\n        # Act - simulate cache miss check\\n        should_build = isinstance(cached_result, CacheMiss)\\n\\n        # Assert\\n        assert should_build is True, \\\"Cache miss should trigger build\\\"\\n\\n    def test_loop_component_should_always_build_even_when_frozen(self):\\n        \\\"\\\"\\\"Test that Loop component always builds even when frozen and built.\\n\\n        Given: A frozen Loop component with built=True\\n        When: Checking if should build\\n        Then: should_build should be True (loops need to iterate)\\n        \\\"\\\"\\\"\\n        # Arrange\\n        vertex = Mock()\\n        vertex.frozen = True\\n        vertex.built = True\\n        vertex.is_loop = True\\n        vertex.display_name = \\\"Loop\\\"\\n\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        # Act - simulate build_vertex decision\\n        should_build = not vertex.frozen or is_loop_component\\n\\n        # Assert\\n        assert should_build is True, \\\"Loop component should always build\\\"\\n\\n    def test_multiple_finalize_build_failures_all_reset_built_flag(self):\\n        \\\"\\\"\\\"Test that multiple types of exceptions all reset built flag.\\n\\n        Given: Various exceptions that could occur in finalize_build\\n        When: Each exception is raised\\n        Then: vertex.built should be reset to False in all cases\\n        \\\"\\\"\\\"\\n        exceptions_to_test = [\\n            ValueError(\\\"Test value error\\\"),\\n            TypeError(\\\"Test type error\\\"),\\n            KeyError(\\\"Test key error\\\"),\\n            AttributeError(\\\"Test attribute error\\\"),\\n            RuntimeError(\\\"Test runtime error\\\"),\\n        ]\\n\\n        for exception in exceptions_to_test:\\n            # Arrange\\n            vertex = Mock()\\n            vertex.built = True\\n            vertex.finalize_build = Mock(side_effect=exception)\\n\\n            # Act\\n            should_build = False\\n            try:\\n                vertex.finalize_build()\\n            except Exception:\\n                vertex.built = False\\n                should_build = True\\n\\n            # Assert\\n            assert vertex.built is False, f\\\"vertex.built should be reset for {type(exception).__name__}\\\"\\n            assert should_build is True, f\\\"should_build should be True for {type(exception).__name__}\\\"\\n\\n\\nclass TestCacheRestorationIntegration:\\n    \\\"\\\"\\\"Integration-style tests simulating full cache restoration flow.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def mock_graph(self):\\n        \\\"\\\"\\\"Create a mock graph for testing.\\\"\\\"\\\"\\n        graph = Mock()\\n        graph.get_vertex = Mock()\\n        graph.run_manager = Mock()\\n        graph.run_manager.add_to_vertices_being_run = Mock()\\n        return graph\\n\\n    def test_full_flow_with_finalize_build_failure(self):\\n        \\\"\\\"\\\"Test the complete flow when finalize_build fails during cache restoration.\\n\\n        This simulates the exact scenario that was causing the bug:\\n        1. Frozen vertex, cache hit\\n        2. Restore state from cache (built=True)\\n        3. finalize_build() fails\\n        4. built flag should be reset\\n        5. build() should run fully\\n        \\\"\\\"\\\"\\n        # Arrange\\n        vertex = Mock()\\n        vertex.id = \\\"ChatInput-abc123\\\"\\n        vertex.frozen = True\\n        vertex.built = False\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"Chat Input\\\"\\n        vertex.result = None\\n\\n        cached_vertex_dict = {\\n            \\\"built\\\": True,\\n            \\\"artifacts\\\": {},\\n            \\\"built_object\\\": {\\\"message\\\": Mock()},\\n            \\\"built_result\\\": {\\\"message\\\": Mock()},\\n            \\\"full_data\\\": {},\\n            \\\"results\\\": {\\\"message\\\": Mock()},\\n        }\\n\\n        # Simulate finalize_build failure\\n        def finalize_build_that_fails():\\n            msg = \\\"Simulated finalize_build failure\\\"\\n            raise ValueError(msg)\\n\\n        vertex.finalize_build = finalize_build_that_fails\\n\\n        # Act - simulate build_vertex logic\\n        should_build = False\\n        is_loop_component = vertex.display_name == \\\"Loop\\\" or vertex.is_loop\\n\\n        if not vertex.frozen or is_loop_component:\\n            should_build = True\\n        else:\\n            # Simulate cache hit - restore state\\n            vertex.built = cached_vertex_dict[\\\"built\\\"]\\n            vertex.artifacts = cached_vertex_dict[\\\"artifacts\\\"]\\n            vertex.built_object = cached_vertex_dict[\\\"built_object\\\"]\\n            vertex.built_result = cached_vertex_dict[\\\"built_result\\\"]\\n            vertex.full_data = cached_vertex_dict[\\\"full_data\\\"]\\n            vertex.results = cached_vertex_dict[\\\"results\\\"]\\n\\n            try:\\n                vertex.finalize_build()\\n            except Exception:\\n                vertex.built = False  # THE FIX\\n                should_build = True\\n\\n        # Assert\\n        assert should_build is True, \\\"should_build should be True after finalize_build failure\\\"\\n        assert vertex.built is False, \\\"vertex.built should be reset to False\\\"\\n\\n        # Verify that build() will NOT return early\\n        should_return_early = vertex.frozen and vertex.built and not is_loop_component\\n        assert should_return_early is False, \\\"build() should NOT return early with reset built flag\\\"\\n\\n    def test_second_run_scenario_with_fix(self):\\n        \\\"\\\"\\\"Test the exact scenario reported: first run works, second run fails.\\n\\n        This test simulates:\\n        1. First run: vertex builds normally\\n        2. Second run: cache restoration fails, but fix ensures rebuild works\\n        \\\"\\\"\\\"\\n        # First run - simulates successful initial build\\n        vertex = Mock()\\n        vertex.id = \\\"ChatInput-ybc2G\\\"\\n        vertex.frozen = True\\n        vertex.built = False\\n        vertex.is_loop = False\\n        vertex.display_name = \\\"Chat Input\\\"\\n        vertex.result = None\\n\\n        # Simulate first run: should_build = True (not frozen initially or no cache)\\n        # After first run: vertex.built = True, vertex.result = Mock()\\n        vertex.built = True\\n        vertex.result = Mock()  # First run sets result\\n\\n        # Second run - cache hit but finalize_build fails\\n        # This simulates a new vertex instance with same ID\\n        vertex_run2 = Mock()\\n        vertex_run2.id = \\\"ChatInput-ybc2G\\\"\\n        vertex_run2.frozen = True\\n        vertex_run2.built = False  # New instance starts with built=False\\n        vertex_run2.is_loop = False\\n        vertex_run2.display_name = \\\"Chat Input\\\"\\n        vertex_run2.result = None  # New instance starts with result=None\\n\\n        cached_vertex_dict = {\\n            \\\"built\\\": True,  # From first run\\n            \\\"artifacts\\\": {},\\n            \\\"built_object\\\": {\\\"message\\\": Mock()},\\n            \\\"built_result\\\": {\\\"message\\\": Mock()},\\n            \\\"full_data\\\": {},\\n            \\\"results\\\": {\\\"message\\\": Mock()},\\n        }\\n\\n        # Simulate cache restoration failure\\n        vertex_run2.finalize_build = Mock(side_effect=ValueError(\\\"Simulated failure\\\"))\\n\\n        # Act - simulate build_vertex for second run\\n        should_build = False\\n        is_loop_component = vertex_run2.display_name == \\\"Loop\\\" or vertex_run2.is_loop\\n\\n        if not vertex_run2.frozen or is_loop_component:\\n            should_build = True\\n        else:\\n            # Cache hit - restore state\\n            vertex_run2.built = cached_vertex_dict[\\\"built\\\"]  # Set to True\\n            try:\\n                vertex_run2.finalize_build()\\n            except Exception:\\n                vertex_run2.built = False  # THE FIX - reset to False\\n                should_build = True\\n\\n        # Assert - with the fix, the vertex should rebuild correctly\\n        assert vertex_run2.built is False, \\\"vertex.built should be reset after cache restoration failure\\\"\\n        assert should_build is True, \\\"should_build should trigger rebuild\\\"\\n\\n        # Verify build() won't return early\\n        should_return_early = vertex_run2.frozen and vertex_run2.built and not is_loop_component\\n        assert should_return_early is False, \\\"build() should continue with reset built flag\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/test_execution_path_equivalence.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"abee963c5f2abd3d627d138614a709b0c6b5118125ae9cf2132f0f2e0d170816\",\"content\":\"\\\"\\\"\\\"Test suite for validating execution path equivalence between async_start and arun.\\n\\nThis module tests that both execution paths (async_start/astep and arun/process) produce\\nidentical results, run the same components in compatible orders, and handle loops correctly.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass, field\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n    from lfx.graph.schema import RunOutputs\\n    from lfx.schema.schema import InputValueRequest\\n\\n\\n@dataclass\\nclass ExecutionTrace:\\n    \\\"\\\"\\\"Records the execution trace of a graph run.\\\"\\\"\\\"\\n\\n    path_name: str\\n    vertices_executed: list[str] = field(default_factory=list)\\n    execution_order: list[tuple[str, int]] = field(default_factory=list)  # (vertex_id, run_count)\\n    final_outputs: list[RunOutputs] | None = None\\n    vertex_results: dict[str, Any] = field(default_factory=dict)\\n    context_snapshots: list[dict[str, Any]] = field(default_factory=list)\\n    run_manager_snapshots: list[dict[str, Any]] = field(default_factory=list)\\n    run_queue_snapshots: list[list[str]] = field(default_factory=list)\\n    error: Exception | None = None\\n    # New: State deltas and loop tracking\\n    state_deltas: list[dict[str, Any]] = field(default_factory=list)\\n    loop_iterations: dict[str, list[dict[str, Any]]] = field(default_factory=dict)  # loop_id -> iterations\\n\\n    def record_vertex_execution(self, vertex_id: str) -> None:\\n        \\\"\\\"\\\"Record that a vertex was executed.\\\"\\\"\\\"\\n        self.vertices_executed.append(vertex_id)\\n        run_count = self.vertices_executed.count(vertex_id)\\n        self.execution_order.append((vertex_id, run_count))\\n\\n    def record_context_snapshot(self, context: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Record a snapshot of the graph context.\\\"\\\"\\\"\\n        self.context_snapshots.append(context.copy())\\n\\n    def record_run_manager_snapshot(self, run_manager_state: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Record a snapshot of the run_manager state.\\\"\\\"\\\"\\n        self.run_manager_snapshots.append(run_manager_state.copy())\\n\\n    def record_run_queue_snapshot(self, run_queue: list[str]) -> None:\\n        \\\"\\\"\\\"Record a snapshot of the run queue.\\\"\\\"\\\"\\n        self.run_queue_snapshots.append(run_queue.copy())\\n\\n    def record_state_delta(self, vertex_id: str, delta: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Record a state delta (what changed) for a vertex build.\\n\\n        Args:\\n            vertex_id: The vertex that was just built\\n            delta: Dictionary describing what changed\\n        \\\"\\\"\\\"\\n        delta[\\\"vertex_id\\\"] = vertex_id\\n        delta[\\\"step\\\"] = len(self.vertices_executed)\\n        self.state_deltas.append(delta)\\n\\n    def record_loop_iteration(self, loop_id: str, iteration_data: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Record a loop component iteration.\\n\\n        Args:\\n            loop_id: The loop component ID\\n            iteration_data: Data about this iteration (index, data, aggregated count, etc)\\n        \\\"\\\"\\\"\\n        if loop_id not in self.loop_iterations:\\n            self.loop_iterations[loop_id] = []\\n        self.loop_iterations[loop_id].append(iteration_data)\\n\\n    def get_vertex_run_count(self, vertex_id: str) -> int:\\n        \\\"\\\"\\\"Get how many times a vertex was executed.\\\"\\\"\\\"\\n        return self.vertices_executed.count(vertex_id)\\n\\n    def get_run_manager_evolution(self) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Get the evolution of run_manager state over time.\\n\\n        Returns:\\n            List of dicts showing how run_predecessors and run_map changed\\n        \\\"\\\"\\\"\\n        evolution = []\\n        for i, snapshot in enumerate(self.run_manager_snapshots):\\n            evolution.append(\\n                {\\n                    \\\"step\\\": i,\\n                    \\\"run_predecessors\\\": snapshot.get(\\\"run_predecessors\\\", {}),\\n                    \\\"run_map\\\": snapshot.get(\\\"run_map\\\", {}),\\n                    \\\"vertices_to_run\\\": snapshot.get(\\\"vertices_to_run\\\", set()),\\n                    \\\"vertices_being_run\\\": snapshot.get(\\\"vertices_being_run\\\", set()),\\n                }\\n            )\\n        return evolution\\n\\n    def get_queue_evolution(self) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Get the evolution of run_queue over time.\\n\\n        Returns:\\n            List of dicts showing how the queue changed at each step\\n        \\\"\\\"\\\"\\n        evolution = []\\n        for i, queue_snapshot in enumerate(self.run_queue_snapshots):\\n            vertex_id = self.vertices_executed[i // 2] if i // 2 < len(self.vertices_executed) else None\\n            evolution.append(\\n                {\\n                    \\\"step\\\": i,\\n                    \\\"vertex_being_built\\\": vertex_id,\\n                    \\\"queue\\\": queue_snapshot,\\n                    \\\"queue_size\\\": len(queue_snapshot),\\n                }\\n            )\\n        return evolution\\n\\n    def get_state_deltas(self) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Get state deltas showing only what changed at each step.\\n\\n        Returns:\\n            List of deltas with added/removed items\\n        \\\"\\\"\\\"\\n        return self.state_deltas\\n\\n    def get_loop_iterations_summary(self) -> dict[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Get summary of all loop iterations.\\n\\n        Returns:\\n            Dictionary mapping loop_id to iteration summary\\n        \\\"\\\"\\\"\\n        summary = {}\\n        for loop_id, iterations in self.loop_iterations.items():\\n            summary[loop_id] = {\\n                \\\"total_iterations\\\": len(iterations),\\n                \\\"max_index_reached\\\": max((it.get(\\\"index\\\", 0) or 0 for it in iterations), default=0),\\n                \\\"data_length\\\": iterations[0].get(\\\"data_length\\\", 0) if iterations else 0,\\n                \\\"iterations\\\": iterations,\\n            }\\n        return summary\\n\\n    def format_state_deltas(self) -> str:\\n        \\\"\\\"\\\"Format state deltas as human-readable text.\\n\\n        Returns:\\n            Formatted string showing what changed at each step\\n        \\\"\\\"\\\"\\n        lines = [\\\"\\\\n=== STATE DELTAS ===\\\\n\\\"]\\n\\n        for delta in self.state_deltas:\\n            vertex_id = delta.get(\\\"vertex_id\\\", \\\"Unknown\\\")\\n            step = delta.get(\\\"step\\\", \\\"?\\\")\\n\\n            lines.append(f\\\"Step {step}: {vertex_id}\\\")\\n\\n            # Show run_manager changes\\n            if \\\"run_manager\\\" in delta:\\n                rm_delta = delta[\\\"run_manager\\\"]\\n\\n                if \\\"run_predecessors\\\" in rm_delta:\\n                    lines.append(\\\"  run_predecessors:\\\")\\n                    for vid, change in rm_delta[\\\"run_predecessors\\\"].items():\\n                        if change[\\\"added\\\"]:\\n                            lines.append(f\\\"    {vid} += {change['added']}\\\")\\n                        if change[\\\"removed\\\"]:\\n                            lines.append(f\\\"    {vid} -= {change['removed']}\\\")\\n\\n                if \\\"run_map\\\" in rm_delta:\\n                    lines.append(\\\"  run_map:\\\")\\n                    for vid, change in rm_delta[\\\"run_map\\\"].items():\\n                        if change[\\\"added\\\"]:\\n                            lines.append(f\\\"    {vid} += {change['added']}\\\")\\n                        if change[\\\"removed\\\"]:\\n                            lines.append(f\\\"    {vid} -= {change['removed']}\\\")\\n\\n            # Show queue changes\\n            if \\\"queue\\\" in delta:\\n                q_delta = delta[\\\"queue\\\"]\\n                if q_delta[\\\"added\\\"]:\\n                    lines.append(f\\\"  queue += {q_delta['added']}\\\")\\n                if q_delta[\\\"removed\\\"]:\\n                    lines.append(f\\\"  queue -= {q_delta['removed']}\\\")\\n                lines.append(f\\\"  queue size: {q_delta['before_size']} \u2192 {q_delta['after_size']}\\\")\\n\\n            lines.append(\\\"\\\")\\n\\n        return \\\"\\\\n\\\".join(lines)\\n\\n    def format_loop_iterations(self) -> str:\\n        \\\"\\\"\\\"Format loop iterations as human-readable text.\\n\\n        Returns:\\n            Formatted string showing loop progression\\n        \\\"\\\"\\\"\\n        lines = [\\\"\\\\n=== LOOP ITERATIONS ===\\\\n\\\"]\\n\\n        for loop_id, iterations in self.loop_iterations.items():\\n            lines.append(f\\\"Loop: {loop_id}\\\")\\n            lines.append(f\\\"  Total iterations: {len(iterations)}\\\")\\n\\n            for i, iteration in enumerate(iterations):\\n                index = iteration.get(\\\"index\\\", \\\"?\\\")\\n                data_len = iteration.get(\\\"data_length\\\", \\\"?\\\")\\n                agg_count = iteration.get(\\\"aggregated_count\\\", \\\"?\\\")\\n                lines.append(f\\\"  Iteration {i}: index={index}/{data_len}, aggregated={agg_count}\\\")\\n\\n            lines.append(\\\"\\\")\\n\\n        return \\\"\\\\n\\\".join(lines)\\n\\n\\nclass ExecutionTracer:\\n    \\\"\\\"\\\"Traces graph execution to capture detailed runtime behavior.\\\"\\\"\\\"\\n\\n    def __init__(self, graph: Graph, trace: ExecutionTrace) -> None:\\n        self.graph = graph\\n        self.trace = trace\\n        self.original_build_vertex = graph.build_vertex\\n        self._last_run_manager_state: dict[str, Any] | None = None\\n        self._last_queue_state: list[str] | None = None\\n\\n    def _compute_run_manager_delta(self, before: dict[str, Any], after: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Compute what changed in run_manager state.\\n\\n        Returns:\\n            Dictionary with only the changes\\n        \\\"\\\"\\\"\\n        delta = {}\\n\\n        # Check run_predecessors changes\\n        before_pred = before.get(\\\"run_predecessors\\\", {})\\n        after_pred = after.get(\\\"run_predecessors\\\", {})\\n        pred_changes = {}\\n        for vertex_id in set(list(before_pred.keys()) + list(after_pred.keys())):\\n            before_deps = set(before_pred.get(vertex_id, []))\\n            after_deps = set(after_pred.get(vertex_id, []))\\n            if before_deps != after_deps:\\n                pred_changes[vertex_id] = {\\n                    \\\"added\\\": list(after_deps - before_deps),\\n                    \\\"removed\\\": list(before_deps - after_deps),\\n                }\\n        if pred_changes:\\n            delta[\\\"run_predecessors\\\"] = pred_changes\\n\\n        # Check run_map changes\\n        before_map = before.get(\\\"run_map\\\", {})\\n        after_map = after.get(\\\"run_map\\\", {})\\n        map_changes = {}\\n        for vertex_id in set(list(before_map.keys()) + list(after_map.keys())):\\n            before_deps = set(before_map.get(vertex_id, []))\\n            after_deps = set(after_map.get(vertex_id, []))\\n            if before_deps != after_deps:\\n                map_changes[vertex_id] = {\\n                    \\\"added\\\": list(after_deps - before_deps),\\n                    \\\"removed\\\": list(before_deps - after_deps),\\n                }\\n        if map_changes:\\n            delta[\\\"run_map\\\"] = map_changes\\n\\n        # Check vertices_to_run changes\\n        before_to_run = set(before.get(\\\"vertices_to_run\\\", set()))\\n        after_to_run = set(after.get(\\\"vertices_to_run\\\", set()))\\n        if before_to_run != after_to_run:\\n            delta[\\\"vertices_to_run\\\"] = {\\n                \\\"added\\\": list(after_to_run - before_to_run),\\n                \\\"removed\\\": list(before_to_run - after_to_run),\\n            }\\n\\n        # Check vertices_being_run changes\\n        before_being_run = set(before.get(\\\"vertices_being_run\\\", set()))\\n        after_being_run = set(after.get(\\\"vertices_being_run\\\", set()))\\n        if before_being_run != after_being_run:\\n            delta[\\\"vertices_being_run\\\"] = {\\n                \\\"added\\\": list(after_being_run - before_being_run),\\n                \\\"removed\\\": list(before_being_run - after_being_run),\\n            }\\n\\n        return delta\\n\\n    def _compute_queue_delta(self, before: list[str], after: list[str]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Compute what changed in the queue.\\n\\n        Returns:\\n            Dictionary with queue changes\\n        \\\"\\\"\\\"\\n        before_set = set(before)\\n        after_set = set(after)\\n\\n        return {\\n            \\\"added\\\": list(after_set - before_set),\\n            \\\"removed\\\": list(before_set - after_set),\\n            \\\"before_size\\\": len(before),\\n            \\\"after_size\\\": len(after),\\n        }\\n\\n    def _capture_loop_state(self, vertex_id: str, vertex: Any) -> None:\\n        \\\"\\\"\\\"Capture loop component state if this is a loop.\\n\\n        Args:\\n            vertex_id: The vertex ID\\n            vertex: The vertex object\\n        \\\"\\\"\\\"\\n        # Check if this is a loop component\\n        if not hasattr(vertex, \\\"custom_component\\\"):\\n            return\\n\\n        component = vertex.custom_component\\n        if not hasattr(component, \\\"__class__\\\"):\\n            return\\n\\n        class_name = component.__class__.__name__\\n        if \\\"Loop\\\" not in class_name:\\n            return\\n\\n        # This is a loop! Capture its state\\n        loop_id = component._id if hasattr(component, \\\"_id\\\") else vertex_id\\n\\n        iteration_data = {\\n            \\\"step\\\": len(self.trace.vertices_executed),\\n            \\\"vertex_id\\\": vertex_id,\\n        }\\n\\n        # Capture loop context state\\n        if hasattr(component, \\\"ctx\\\"):\\n            iteration_data[\\\"index\\\"] = component.ctx.get(f\\\"{loop_id}_index\\\", None)\\n            iteration_data[\\\"data_length\\\"] = len(component.ctx.get(f\\\"{loop_id}_data\\\", []))\\n            iteration_data[\\\"aggregated_count\\\"] = len(component.ctx.get(f\\\"{loop_id}_aggregated\\\", []))\\n            iteration_data[\\\"initialized\\\"] = component.ctx.get(f\\\"{loop_id}_initialized\\\", False)\\n\\n        self.trace.record_loop_iteration(loop_id, iteration_data)\\n\\n    async def traced_build_vertex(self, vertex_id: str, *args, **kwargs):\\n        \\\"\\\"\\\"Wrapped build_vertex that records execution.\\\"\\\"\\\"\\n        self.trace.record_vertex_execution(vertex_id)\\n\\n        # Capture state BEFORE building\\n        before_run_manager = None\\n        before_queue = None\\n\\n        if hasattr(self.graph, \\\"run_manager\\\"):\\n            before_run_manager = self.graph.run_manager.to_dict()\\n            self.trace.record_run_manager_snapshot(before_run_manager)\\n\\n        if hasattr(self.graph, \\\"_run_queue\\\"):\\n            before_queue = list(self.graph._run_queue)\\n            self.trace.record_run_queue_snapshot(before_queue)\\n\\n        # Call original method\\n        result = await self.original_build_vertex(vertex_id, *args, **kwargs)\\n\\n        # Record vertex result\\n        if result and hasattr(result, \\\"result\\\"):\\n            self.trace.vertex_results[vertex_id] = result.result\\n\\n        # Capture loop state if this is a loop\\n        if result and hasattr(result, \\\"vertex\\\"):\\n            self._capture_loop_state(vertex_id, result.vertex)\\n\\n        # Capture state AFTER building and compute deltas\\n        delta = {\\\"vertex_id\\\": vertex_id}\\n\\n        if hasattr(self.graph, \\\"run_manager\\\"):\\n            after_run_manager = self.graph.run_manager.to_dict()\\n            self.trace.record_run_manager_snapshot(after_run_manager)\\n\\n            if before_run_manager:\\n                run_manager_delta = self._compute_run_manager_delta(before_run_manager, after_run_manager)\\n                if run_manager_delta:\\n                    delta[\\\"run_manager\\\"] = run_manager_delta\\n\\n        if hasattr(self.graph, \\\"_run_queue\\\"):\\n            after_queue = list(self.graph._run_queue)\\n            self.trace.record_run_queue_snapshot(after_queue)\\n\\n            if before_queue is not None:\\n                queue_delta = self._compute_queue_delta(before_queue, after_queue)\\n                if queue_delta[\\\"added\\\"] or queue_delta[\\\"removed\\\"]:\\n                    delta[\\\"queue\\\"] = queue_delta\\n\\n        # Record delta if anything changed\\n        if len(delta) > 2:  # More than just vertex_id and step\\n            self.trace.record_state_delta(vertex_id, delta)\\n\\n        return result\\n\\n    def install(self) -> None:\\n        \\\"\\\"\\\"Install the tracer into the graph.\\\"\\\"\\\"\\n        self.graph.build_vertex = self.traced_build_vertex\\n\\n    def uninstall(self) -> None:\\n        \\\"\\\"\\\"Restore the original build_vertex method.\\\"\\\"\\\"\\n        self.graph.build_vertex = self.original_build_vertex\\n\\n\\nasync def run_via_async_start(\\n    graph: Graph,\\n    inputs: list[InputValueRequest] | None = None,\\n    _outputs: list[str] | None = None,\\n) -> ExecutionTrace:\\n    \\\"\\\"\\\"Run graph using async_start path and capture trace.\\n\\n    This mimics how the CLI `lfx run` command executes graphs.\\n    \\\"\\\"\\\"\\n    trace = ExecutionTrace(path_name=\\\"async_start\\\")\\n    tracer = ExecutionTracer(graph, trace)\\n\\n    try:\\n        tracer.install()\\n        graph.prepare()\\n\\n        results = []\\n        input_dict = None\\n        if inputs:\\n            input_dict = inputs[0]\\n\\n        async for result in graph.async_start(inputs=input_dict):\\n            if hasattr(result, \\\"vertex\\\"):\\n                results.append(result)  # noqa: PERF401\\n\\n        trace.final_outputs = results\\n\\n    except Exception as e:\\n        trace.error = e\\n    finally:\\n        tracer.uninstall()\\n\\n    return trace\\n\\n\\nasync def run_via_arun(\\n    graph: Graph,\\n    inputs: list[InputValueRequest] | None = None,\\n    outputs: list[str] | None = None,\\n) -> ExecutionTrace:\\n    \\\"\\\"\\\"Run graph using arun path and capture trace.\\n\\n    This mimics how the /api/v1/run endpoint executes graphs.\\n    \\\"\\\"\\\"\\n    trace = ExecutionTrace(path_name=\\\"arun\\\")\\n    tracer = ExecutionTracer(graph, trace)\\n\\n    try:\\n        tracer.install()\\n        graph.prepare()\\n\\n        # Convert inputs to the format expected by arun\\n        inputs_list = []\\n        inputs_components = []\\n        types = []\\n\\n        if inputs:\\n            for input_request in inputs:\\n                inputs_list.append({\\\"message\\\": input_request.input_value})\\n                inputs_components.append(input_request.components or [])\\n                types.append(input_request.type or \\\"chat\\\")\\n\\n        results = await graph.arun(\\n            inputs=inputs_list,\\n            inputs_components=inputs_components,\\n            types=types,\\n            outputs=outputs or [],\\n            session_id=graph.session_id or \\\"test-session\\\",\\n        )\\n\\n        trace.final_outputs = results\\n\\n    except Exception as e:\\n        trace.error = e\\n    finally:\\n        tracer.uninstall()\\n\\n    return trace\\n\\n\\ndef assert_execution_equivalence(\\n    trace1: ExecutionTrace,\\n    trace2: ExecutionTrace,\\n    *,\\n    allow_parallel_reordering: bool = True,\\n) -> None:\\n    \\\"\\\"\\\"Assert that two execution traces are equivalent.\\n\\n    Args:\\n        trace1: First execution trace\\n        trace2: Second execution trace\\n        allow_parallel_reordering: If True, allows vertices in the same layer\\n                                  to execute in different orders (since they run\\n                                  in parallel in the arun path)\\n    \\\"\\\"\\\"\\n    # Both should succeed or both should fail\\n    if trace1.error or trace2.error:\\n        assert (trace1.error is None) == (trace2.error is None), (\\n            f\\\"{trace1.path_name} error: {trace1.error}, {trace2.path_name} error: {trace2.error}\\\"\\n        )\\n\\n    # Should execute the same set of vertices\\n    vertices1 = set(trace1.vertices_executed)\\n    vertices2 = set(trace2.vertices_executed)\\n\\n    assert vertices1 == vertices2, (\\n        f\\\"Different vertices executed:\\\\n\\\"\\n        f\\\"{trace1.path_name}: {vertices1}\\\\n\\\"\\n        f\\\"{trace2.path_name}: {vertices2}\\\\n\\\"\\n        f\\\"Only in {trace1.path_name}: {vertices1 - vertices2}\\\\n\\\"\\n        f\\\"Only in {trace2.path_name}: {vertices2 - vertices1}\\\"\\n    )\\n\\n    # Should execute each vertex the same number of times\\n    for vertex_id in vertices1:\\n        count1 = trace1.get_vertex_run_count(vertex_id)\\n        count2 = trace2.get_vertex_run_count(vertex_id)\\n\\n        assert count1 == count2, (\\n            f\\\"Vertex {vertex_id} executed different number of times:\\\\n\\\"\\n            f\\\"{trace1.path_name}: {count1} times\\\\n\\\"\\n            f\\\"{trace2.path_name}: {count2} times\\\"\\n        )\\n\\n    # If not allowing reordering, execution order should be identical\\n    if not allow_parallel_reordering:\\n        assert trace1.execution_order == trace2.execution_order, (\\n            f\\\"Execution order differs:\\\\n\\\"\\n            f\\\"{trace1.path_name}: {trace1.execution_order}\\\\n\\\"\\n            f\\\"{trace2.path_name}: {trace2.execution_order}\\\"\\n        )\\n\\n\\ndef compare_run_manager_evolution(trace1: ExecutionTrace, trace2: ExecutionTrace) -> dict[str, Any]:\\n    \\\"\\\"\\\"Compare how run_manager state evolved in both traces.\\n\\n    Returns:\\n        Dictionary with comparison results highlighting differences\\n    \\\"\\\"\\\"\\n    evo1 = trace1.get_run_manager_evolution()\\n    evo2 = trace2.get_run_manager_evolution()\\n\\n    differences = []\\n\\n    max_steps = max(len(evo1), len(evo2))\\n    for step in range(max_steps):\\n        step_diff = {\\\"step\\\": step}\\n\\n        if step < len(evo1) and step < len(evo2):\\n            # Compare run_predecessors\\n            pred1 = evo1[step][\\\"run_predecessors\\\"]\\n            pred2 = evo2[step][\\\"run_predecessors\\\"]\\n            if pred1 != pred2:\\n                step_diff[\\\"run_predecessors_diff\\\"] = {\\n                    \\\"trace1\\\": pred1,\\n                    \\\"trace2\\\": pred2,\\n                }\\n\\n            # Compare run_map\\n            map1 = evo1[step][\\\"run_map\\\"]\\n            map2 = evo2[step][\\\"run_map\\\"]\\n            if map1 != map2:\\n                step_diff[\\\"run_map_diff\\\"] = {\\n                    \\\"trace1\\\": map1,\\n                    \\\"trace2\\\": map2,\\n                }\\n\\n            if len(step_diff) > 1:  # Has differences beyond 'step'\\n                differences.append(step_diff)\\n\\n    return {\\n        \\\"has_differences\\\": len(differences) > 0,\\n        \\\"differences\\\": differences,\\n        \\\"trace1_steps\\\": len(evo1),\\n        \\\"trace2_steps\\\": len(evo2),\\n    }\\n\\n\\ndef format_execution_comparison(trace1: ExecutionTrace, trace2: ExecutionTrace) -> str:\\n    \\\"\\\"\\\"Format a detailed comparison of two execution traces for debugging.\\n\\n    Returns:\\n        Human-readable string showing execution differences\\n    \\\"\\\"\\\"\\n    lines = []\\n    lines.append(f\\\"\\\\n{'=' * 80}\\\")\\n    lines.append(f\\\"EXECUTION COMPARISON: {trace1.path_name} vs {trace2.path_name}\\\")\\n    lines.append(f\\\"{'=' * 80}\\\\n\\\")\\n\\n    # Execution order comparison\\n    lines.append(\\\"Execution Order:\\\")\\n    lines.append(f\\\"  {trace1.path_name}: {trace1.execution_order[:10]}...\\\")\\n    lines.append(f\\\"  {trace2.path_name}: {trace2.execution_order[:10]}...\\\\n\\\")\\n\\n    # Vertex count comparison\\n    for vid in set(trace1.vertices_executed + trace2.vertices_executed):\\n        count1 = trace1.get_vertex_run_count(vid)\\n        count2 = trace2.get_vertex_run_count(vid)\\n        if count1 != count2:\\n            lines.append(f\\\"  {vid}: {trace1.path_name}={count1}, {trace2.path_name}={count2}\\\")\\n\\n    # Run manager differences\\n    rm_comparison = compare_run_manager_evolution(trace1, trace2)\\n    if rm_comparison[\\\"has_differences\\\"]:\\n        lines.append(f\\\"\\\\nRun Manager Differences Found: {len(rm_comparison['differences'])} steps\\\")\\n        lines.extend(f\\\"  Step {diff['step']}: {list(diff.keys())}\\\" for diff in rm_comparison[\\\"differences\\\"][:5])\\n\\n    # Queue evolution\\n    lines.append(\\\"\\\\nQueue Snapshots:\\\")\\n    lines.append(f\\\"  {trace1.path_name}: {len(trace1.run_queue_snapshots)} snapshots\\\")\\n    lines.append(f\\\"  {trace2.path_name}: {len(trace2.run_queue_snapshots)} snapshots\\\")\\n\\n    return \\\"\\\\n\\\".join(lines)\\n\\n\\ndef assert_output_equivalence(trace1: ExecutionTrace, trace2: ExecutionTrace) -> None:\\n    \\\"\\\"\\\"Assert that two execution traces produced equivalent outputs.\\\"\\\"\\\"\\n    # Compare final outputs\\n    if trace1.final_outputs and trace2.final_outputs:\\n        # Both should have outputs\\n        assert len(trace1.final_outputs) == len(trace2.final_outputs), (\\n            f\\\"Different number of outputs:\\\\n\\\"\\n            f\\\"{trace1.path_name}: {len(trace1.final_outputs)}\\\\n\\\"\\n            f\\\"{trace2.path_name}: {len(trace2.final_outputs)}\\\"\\n        )\\n\\n        # Compare output results (Note: exact comparison may need to be relaxed\\n        # depending on non-deterministic components like LLMs)\\n        for i, (out1, out2) in enumerate(zip(trace1.final_outputs, trace2.final_outputs, strict=True)):\\n            # Basic structural comparison\\n            if hasattr(out1, \\\"outputs\\\") and hasattr(out2, \\\"outputs\\\"):\\n                assert len(out1.outputs) == len(out2.outputs), (\\n                    f\\\"Output {i} has different number of results:\\\\n\\\"\\n                    f\\\"{trace1.path_name}: {len(out1.outputs)}\\\\n\\\"\\n                    f\\\"{trace2.path_name}: {len(out2.outputs)}\\\"\\n                )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_simple_graph_equivalence():\\n    \\\"\\\"\\\"Test that a simple graph executes identically via both paths.\\\"\\\"\\\"\\n    # TODO: Create a simple graph with 3-4 components (no loops)\\n    # and verify both paths produce identical results\\n    pytest.skip(\\\"Awaiting simple test graph implementation\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_loop_graph_equivalence():\\n    \\\"\\\"\\\"Test that a graph with LoopComponent executes identically via both paths.\\n\\n    This is the critical test for the loop context isolation issue.\\n    \\\"\\\"\\\"\\n    # TODO: Create a graph with LoopComponent and verify both paths\\n    # execute the loop the same number of times and produce identical results\\n    pytest.skip(\\\"Awaiting loop test graph implementation\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_loop_context_isolation():\\n    \\\"\\\"\\\"Test that loop context is properly isolated between iterations.\\n\\n    This test specifically checks that the loop's internal state\\n    (index, aggregated results) resets correctly for each new input.\\n    \\\"\\\"\\\"\\n    # TODO: Run a loop graph multiple times with different inputs\\n    # and verify that context state doesn't leak between runs\\n    pytest.skip(\\\"Awaiting context isolation test implementation\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_execution_trace_capture():\\n    \\\"\\\"\\\"Test that ExecutionTracer correctly captures execution details.\\\"\\\"\\\"\\n    # TODO: Verify the tracing infrastructure works correctly\\n    pytest.skip(\\\"Awaiting trace infrastructure test\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/test_execution_path_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e786768529e4c821360ed03675933600dd604af58850d24c0a4b900007aa3000\",\"content\":\"\\\"\\\"\\\"Execution path validation using test data flows.\\n\\nThis test validates that both execution paths produce identical results\\nusing the test flows in src/backend/tests/data/ which don't require API keys.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport shutil\\nfrom copy import deepcopy\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Generator\\n\\n    from lfx.graph.graph.base import Graph\\n\\nfrom .test_execution_path_equivalence import ExecutionTrace, ExecutionTracer, assert_execution_equivalence\\n\\nTEST_DATA_DIR = Path(__file__).resolve().parent.parent.parent / \\\"data\\\"\\n\\n# Test flows that should work without external dependencies\\nTEST_FLOWS = [\\n    \\\"LoopTest.json\\\",  # Simple loop with feedback\\n    \\\"loop_csv_test.json\\\",  # Real-world failing case from issue\\n    \\\"MemoryChatbotNoLLM.json\\\",\\n]\\n\\n\\n@pytest.fixture\\ndef loop_csv_path() -> Generator[Path, None, None]:\\n    \\\"\\\"\\\"Copy loop_test.csv to current working directory so File component can find it.\\n\\n    The File component resolves relative paths relative to the current working directory,\\n    so we need to place the file there rather than in the cache directory.\\n    \\\"\\\"\\\"\\n    # Copy to current working directory\\n    file_path = Path.cwd() / \\\"loop_test.csv\\\"\\n    shutil.copy(TEST_DATA_DIR / \\\"loop_test.csv\\\", file_path.as_posix())\\n    yield file_path\\n    # Remove the file\\n    if file_path.exists():\\n        file_path.unlink()\\n\\n\\nasync def run_via_async_start_traced(graph: Graph) -> ExecutionTrace:\\n    \\\"\\\"\\\"Run graph using async_start path with full tracing.\\\"\\\"\\\"\\n    from lfx.graph.graph.constants import Finish\\n\\n    trace = ExecutionTrace(path_name=\\\"async_start\\\")\\n    tracer = ExecutionTracer(graph, trace)\\n\\n    try:\\n        tracer.install()\\n        graph.prepare()\\n\\n        results = []\\n        async for result in graph.async_start():\\n            if isinstance(result, Finish):\\n                break\\n            if hasattr(result, \\\"vertex\\\"):\\n                results.append(result)\\n\\n        trace.final_outputs = results\\n\\n    except Exception as e:\\n        trace.error = e\\n    finally:\\n        tracer.uninstall()\\n\\n    return trace\\n\\n\\nasync def run_via_arun_traced(graph: Graph) -> ExecutionTrace:\\n    \\\"\\\"\\\"Run graph using arun path with full tracing.\\\"\\\"\\\"\\n    from uuid import uuid4\\n\\n    from langflow.schema.schema import INPUT_FIELD_NAME\\n    from lfx.schema.schema import InputValueRequest\\n\\n    trace = ExecutionTrace(path_name=\\\"arun\\\")\\n    tracer = ExecutionTracer(graph, trace)\\n\\n    try:\\n        tracer.install()\\n\\n        # Mimic run_graph_internal logic\\n        inputs = [InputValueRequest(components=[], input_value=\\\"\\\", type=\\\"chat\\\")]\\n        effective_session_id = str(uuid4())\\n        components = []\\n        inputs_list = []\\n        types = []\\n\\n        for input_value_request in inputs:\\n            components.append(input_value_request.components or [])\\n            inputs_list.append({INPUT_FIELD_NAME: input_value_request.input_value or \\\"\\\"})\\n            types.append(input_value_request.type)\\n\\n        graph.session_id = effective_session_id\\n\\n        results = await graph.arun(\\n            inputs=inputs_list,\\n            inputs_components=components,\\n            types=types,\\n            outputs=[],  # Empty = run all vertices\\n            stream=False,\\n            session_id=effective_session_id,\\n            fallback_to_env_vars=False,\\n        )\\n\\n        trace.final_outputs = results\\n\\n    except Exception as e:\\n        trace.error = e\\n    finally:\\n        tracer.uninstall()\\n\\n    return trace\\n\\n\\n@pytest.mark.parametrize(\\\"flow_name\\\", TEST_FLOWS)\\n@pytest.mark.asyncio\\n@pytest.mark.usefixtures(\\\"loop_csv_path\\\", \\\"client\\\")\\nasync def test_flow_execution_equivalence(flow_name: str):\\n    \\\"\\\"\\\"Test that a flow produces identical results via both execution paths.\\\"\\\"\\\"\\n    from uuid import uuid4\\n\\n    from lfx.graph.graph.base import Graph\\n\\n    flow_path = TEST_DATA_DIR / flow_name\\n\\n    if not flow_path.exists():\\n        pytest.skip(f\\\"Flow not found: {flow_path}\\\")\\n\\n    # Load the flow\\n    with flow_path.open() as f:\\n        flow_data = json.load(f)\\n\\n    graph_data = flow_data.get(\\\"data\\\", flow_data)\\n\\n    # Create two independent copies with valid UUIDs for persisted identifiers.\\n    graph_for_async_start = Graph.from_payload(\\n        deepcopy(graph_data),\\n        flow_id=str(uuid4()),\\n        flow_name=flow_name,\\n        user_id=str(uuid4()),\\n    )\\n\\n    graph_for_arun = Graph.from_payload(\\n        deepcopy(graph_data),\\n        flow_id=str(uuid4()),\\n        flow_name=flow_name,\\n        user_id=str(uuid4()),\\n    )\\n\\n    # Run both paths with tracing\\n    trace_async_start = await run_via_async_start_traced(graph_for_async_start)\\n    trace_arun = await run_via_arun_traced(graph_for_arun)\\n\\n    # Check for errors first\\n    if trace_async_start.error:\\n        pytest.fail(f\\\"async_start path failed: {trace_async_start.error}\\\")\\n    if trace_arun.error:\\n        pytest.fail(f\\\"arun path failed: {trace_arun.error}\\\")\\n\\n    # Assert execution equivalence (same vertices, same counts)\\n    # Note: We only validate execution, not output format since:\\n    # - async_start yields VertexBuildResults incrementally\\n    # - arun returns grouped RunOutputs\\n    # The output structures are intentionally different\\n    try:\\n        assert_execution_equivalence(trace_async_start, trace_arun, allow_parallel_reordering=True)\\n    except AssertionError as e:\\n        # Provide detailed diagnostics\\n        msg = f\\\"\\\\n{'=' * 80}\\\\nEXECUTION MISMATCH: {flow_name}\\\\n{'=' * 80}\\\\n\\\"\\n        msg += f\\\"\\\\nAsync_start: {len(trace_async_start.vertices_executed)} vertices\\\\n\\\"\\n        msg += f\\\"  {trace_async_start.execution_order}\\\\n\\\"\\n        msg += f\\\"\\\\nArun: {len(trace_arun.vertices_executed)} vertices\\\\n\\\"\\n        msg += f\\\"  {trace_arun.execution_order}\\\\n\\\"\\n        only_async = set(trace_async_start.vertices_executed) - set(trace_arun.vertices_executed)\\n        only_arun = set(trace_arun.vertices_executed) - set(trace_async_start.vertices_executed)\\n        msg += f\\\"\\\\nOnly in async_start: {only_async}\\\\n\\\"\\n        msg += f\\\"Only in arun: {only_arun}\\\\n\\\"\\n\\n        # Show run_manager state differences\\n        if trace_async_start.run_manager_snapshots and trace_arun.run_manager_snapshots:\\n            async_snapshots = len(trace_async_start.run_manager_snapshots)\\n            arun_snapshots = len(trace_arun.run_manager_snapshots)\\n            msg += f\\\"\\\\nRun_manager snapshots: async={async_snapshots}, arun={arun_snapshots}\\\\n\\\"\\n\\n        raise AssertionError(msg) from e\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    pytest.main([__file__, \\\"-v\\\", \\\"-s\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/graph/vertex/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"138ab9fc2cdfcf2f6edbe1d264e3138bf7825521741782a91d51ee10dea0cd13\",\"content\":\"\\\"\\\"\\\"Tests for vertex-related functionality.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/groq/test_groq_discovery_edge_cases.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"423beac793d368ebe4c528446961aed9fc381d7d153a923301ede84278c3c97b\",\"content\":\"\\\"\\\"\\\"Tests for edge cases in Groq model discovery.\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock, Mock, patch\\n\\nfrom lfx.base.models.groq_model_discovery import GroqModelDiscovery\\n\\n\\nclass TestGroqModelDiscoveryEdgeCases:\\n    \\\"\\\"\\\"Test edge cases in model discovery.\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    def test_empty_model_list_from_api(self, mock_get, mock_api_key, temp_cache_dir):\\n        \\\"\\\"\\\"Test handling of empty model list from API.\\\"\\\"\\\"\\n        # Mock empty response\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"data\\\": []}\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Should return empty dict (or potentially fallback)\\n        assert isinstance(models, dict)\\n\\n    def test_cache_file_not_exists(self, mock_api_key, temp_cache_dir):\\n        \\\"\\\"\\\"Test loading cache when file doesn't exist.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"nonexistent.json\\\"\\n\\n        loaded = discovery._load_cache()\\n\\n        assert loaded is None\\n\\n    def test_cache_directory_created_on_save(self, mock_api_key, temp_cache_dir, sample_models_metadata):\\n        \\\"\\\"\\\"Test that cache directory is created if it doesn't exist.\\\"\\\"\\\"\\n        cache_file = temp_cache_dir / \\\"new_dir\\\" / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = cache_file\\n\\n        # Directory shouldn't exist yet\\n        assert not cache_file.parent.exists()\\n\\n        # Save cache\\n        discovery._save_cache(sample_models_metadata)\\n\\n        # Directory should be created\\n        assert cache_file.parent.exists()\\n        assert cache_file.exists()\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_preview_model_detection(\\n        self,\\n        mock_groq,\\n        mock_get,\\n        mock_api_key,\\n        mock_groq_client_tool_calling_success,\\n        temp_cache_dir,\\n    ):\\n        \\\"\\\"\\\"Test detection of preview models.\\\"\\\"\\\"\\n        # Mock API with preview models\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\n            \\\"data\\\": [\\n                {\\\"id\\\": \\\"llama-3.2-1b-preview\\\", \\\"object\\\": \\\"model\\\"},\\n                {\\\"id\\\": \\\"meta-llama/llama-3.2-90b-preview\\\", \\\"object\\\": \\\"model\\\"},\\n            ]\\n        }\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        mock_groq.return_value = mock_groq_client_tool_calling_success()\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # Models with \\\"preview\\\" in name should be marked as preview\\n        assert models[\\\"llama-3.2-1b-preview\\\"][\\\"preview\\\"] is True\\n\\n        # Models with \\\"/\\\" should be marked as preview\\n        assert models[\\\"meta-llama/llama-3.2-90b-preview\\\"][\\\"preview\\\"] is True\\n\\n    @patch(\\\"lfx.base.models.groq_model_discovery.requests.get\\\")\\n    @patch(\\\"groq.Groq\\\")\\n    def test_mixed_tool_calling_support(\\n        self,\\n        mock_groq,\\n        mock_get,\\n        mock_api_key,\\n        temp_cache_dir,\\n    ):\\n        \\\"\\\"\\\"Test models with mixed tool calling support.\\\"\\\"\\\"\\n        # Mock API\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\n            \\\"data\\\": [\\n                {\\\"id\\\": \\\"llama-3.1-8b-instant\\\", \\\"object\\\": \\\"model\\\"},\\n                {\\\"id\\\": \\\"gemma-7b-it\\\", \\\"object\\\": \\\"model\\\"},\\n            ]\\n        }\\n        mock_response.raise_for_status = Mock()\\n        mock_get.return_value = mock_response\\n\\n        # Mock tool calling - each model goes through chat test then tool test\\n        # Call order: chat(llama), tool(llama), chat(gemma), tool(gemma)\\n        call_count = [0]\\n\\n        def create_mock_client(*_args, **_kwargs):\\n            mock_client = MagicMock()\\n            if call_count[0] <= 2:\\n                # Calls 0-2: chat test for llama (success), tool test for llama (success),\\n                # chat test for gemma (success)\\n                mock_client.chat.completions.create.return_value = MagicMock()\\n            else:\\n                # Call 3: tool test for gemma (fails)\\n                mock_client.chat.completions.create.side_effect = ValueError(\\\"tool calling not supported\\\")\\n            call_count[0] += 1\\n            return mock_client\\n\\n        mock_groq.side_effect = create_mock_client\\n\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        discovery.CACHE_FILE = temp_cache_dir / \\\".cache\\\" / \\\"test_cache.json\\\"\\n\\n        models = discovery.get_models(force_refresh=True)\\n\\n        # First model should support tools\\n        assert models[\\\"llama-3.1-8b-instant\\\"][\\\"tool_calling\\\"] is True\\n\\n        # Second model should not support tools\\n        assert models[\\\"gemma-7b-it\\\"][\\\"tool_calling\\\"] is False\\n\\n    def test_fallback_models_structure(self, mock_api_key):\\n        \\\"\\\"\\\"Test that fallback models have the correct structure.\\\"\\\"\\\"\\n        discovery = GroqModelDiscovery(api_key=mock_api_key)\\n        fallback = discovery._get_fallback_models()\\n\\n        assert isinstance(fallback, dict)\\n        assert len(fallback) == 2\\n\\n        for metadata in fallback.values():\\n            assert \\\"name\\\" in metadata\\n            assert \\\"provider\\\" in metadata\\n            assert \\\"tool_calling\\\" in metadata\\n            assert \\\"preview\\\" in metadata\\n            assert metadata[\\\"tool_calling\\\"] is True  # Fallback models should support tools\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/test_flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a433625048ff2c790f7b085bcb56f260adaecc7fa865531c7b511e2af89724c6\",\"content\":\"\\\"\\\"\\\"Unit tests for the langflow.helpers.flow module.\\\"\\\"\\\"\\n\\nimport inspect\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock\\n\\nimport pytest\\nfrom lfx.utils.langflow_utils import has_langflow_memory\\n\\n# Globals\\n\\n_LANGFLOW_HELPER_MODULE_FLOW = \\\"langflow.helpers.flow\\\"\\n\\n# Helper Functions\\n\\n\\ndef is_helper_module(module, module_name):\\n    return module.__module__ == module_name\\n\\n\\n# Test Scenarios\\n\\n\\nclass TestDynamicImport:\\n    \\\"\\\"\\\"Test dynamic imports of the langflow implementation.\\\"\\\"\\\"\\n\\n    def test_langflow_available(self):\\n        \\\"\\\"\\\"Test whether the langflow implementation is available.\\\"\\\"\\\"\\n        # Langflow implementation should be available\\n        if not has_langflow_memory():\\n            pytest.fail(\\\"Langflow implementation is not available\\\")\\n\\n    def test_helpers_import_build_schema_from_inputs(self):\\n        \\\"\\\"\\\"Test the lfx.helpers.build_schema_from_inputs import.\\\"\\\"\\\"\\n        try:\\n            from lfx.helpers import build_schema_from_inputs\\n        except (ImportError, ModuleNotFoundError) as e:\\n            pytest.fail(f\\\"Failed to dynamically import lfx.helpers.build_schema_from_inputs: {e}\\\")\\n\\n        # Helper module should be the langflow implementation\\n        assert is_helper_module(build_schema_from_inputs, _LANGFLOW_HELPER_MODULE_FLOW)\\n\\n    def test_helpers_import_get_arg_names(self):\\n        \\\"\\\"\\\"Test the lfx.helpers.get_arg_names import.\\\"\\\"\\\"\\n        try:\\n            from lfx.helpers import get_arg_names\\n        except (ImportError, ModuleNotFoundError) as e:\\n            pytest.fail(f\\\"Failed to dynamically import lfx.helpers.get_arg_names: {e}\\\")\\n\\n        # Helper module should be the langflow implementation\\n        assert is_helper_module(get_arg_names, _LANGFLOW_HELPER_MODULE_FLOW)\\n\\n    def test_helpers_import_get_flow_inputs(self):\\n        \\\"\\\"\\\"Test the lfx.helpers.get_flow_inputs import.\\\"\\\"\\\"\\n        try:\\n            from lfx.helpers import get_flow_inputs\\n        except (ImportError, ModuleNotFoundError) as e:\\n            pytest.fail(f\\\"Failed to dynamically import lfx.helpers.get_flow_inputs: {e}\\\")\\n\\n        # Helper module should be the langflow implementation\\n        assert is_helper_module(get_flow_inputs, _LANGFLOW_HELPER_MODULE_FLOW)\\n\\n    def test_helpers_import_list_flows(self):\\n        \\\"\\\"\\\"Test the lfx.helpers.list_flows import.\\\"\\\"\\\"\\n        try:\\n            from lfx.helpers import list_flows\\n        except (ImportError, ModuleNotFoundError) as e:\\n            pytest.fail(f\\\"Failed to dynamically import lfx.helpers.list_flows: {e}\\\")\\n\\n        # Helper module should be the langflow implementation\\n        assert is_helper_module(list_flows, _LANGFLOW_HELPER_MODULE_FLOW)\\n\\n    def test_helpers_import_load_flow(self):\\n        \\\"\\\"\\\"Test the lfx.helpers.load_flow import.\\\"\\\"\\\"\\n        try:\\n            from lfx.helpers import load_flow\\n        except (ImportError, ModuleNotFoundError) as e:\\n            pytest.fail(f\\\"Failed to dynamically import lfx.helpers.load_flow: {e}\\\")\\n\\n        # Helper module should be the langflow implementation\\n        assert is_helper_module(load_flow, _LANGFLOW_HELPER_MODULE_FLOW)\\n\\n    def test_helpers_import_run_flow(self):\\n        \\\"\\\"\\\"Test the lfx.helpers.run_flow import.\\\"\\\"\\\"\\n        try:\\n            from lfx.helpers import run_flow\\n        except (ImportError, ModuleNotFoundError) as e:\\n            pytest.fail(f\\\"Failed to dynamically import lfx.helpers.run_flow: {e}\\\")\\n\\n        # Helper module should be the langflow implementation\\n        assert is_helper_module(run_flow, _LANGFLOW_HELPER_MODULE_FLOW)\\n\\n\\nasync def test_generate_function_for_flow_sanitizes_and_preserves_distinct_inputs(monkeypatch):\\n    from langflow.helpers import flow as flow_helpers\\n\\n    inputs = [\\n        SimpleNamespace(\\n            id=\\\"malicious-input\\\",\\n            display_name='value\\\"; __import__(\\\"os\\\").system(\\\"id\\\"); #',\\n            base_name=\\\"ChatInput\\\",\\n            description=\\\"malicious\\\",\\n        ),\\n        SimpleNamespace(id=\\\"keyword-input\\\", display_name=\\\"class\\\", base_name=\\\"TextInput\\\", description=\\\"keyword\\\"),\\n        SimpleNamespace(id=\\\"debug-input\\\", display_name=\\\"__debug__\\\", base_name=\\\"TextInput\\\", description=\\\"debug\\\"),\\n        SimpleNamespace(id=\\\"json-input\\\", display_name=\\\"value\\\", base_name=\\\"JSONInput\\\", description=\\\"json\\\"),\\n        SimpleNamespace(id=\\\"chat-input\\\", display_name=\\\"value\\\", base_name=\\\"ChatInput\\\", description=\\\"chat\\\"),\\n    ]\\n    flow_id = \\\"flow-'quoted\\\\nidentifier\\\"\\n    user_id = \\\"user-'quoted\\\\nidentifier\\\"\\n    run_flow = AsyncMock(return_value=[])\\n    monkeypatch.setattr(flow_helpers, \\\"run_flow\\\", run_flow)\\n\\n    function = flow_helpers.generate_function_for_flow(inputs, flow_id, user_id=user_id)\\n    parameter_names = list(inspect.signature(function).parameters)\\n\\n    assert len(parameter_names) == len(inputs)\\n    assert len(set(parameter_names)) == len(inputs)\\n    assert all(name.isidentifier() for name in parameter_names)\\n    assert \\\"class\\\" not in parameter_names\\n    assert \\\"__debug__\\\" not in parameter_names\\n\\n    values = [\\\"malicious-value\\\", \\\"keyword-value\\\", \\\"debug-value\\\", '{\\\"json\\\": true}', \\\"chat-value\\\"]\\n    await function(*values)\\n\\n    assert run_flow.await_args.kwargs == {\\n        \\\"tweaks\\\": {input_.id: {\\\"input_value\\\": value} for input_, value in zip(inputs, values, strict=True)},\\n        \\\"flow_id\\\": flow_id,\\n        \\\"user_id\\\": user_id,\\n    }\\n\\n    schema = flow_helpers.build_schema_from_inputs(\\\"FlowInputs\\\", inputs)\\n    assert list(schema.schema()[\\\"properties\\\"]) == parameter_names\\n    assert flow_helpers.get_arg_names(inputs) == [\\n        {\\\"component_name\\\": input_.id, \\\"arg_name\\\": arg_name}\\n        for input_, arg_name in zip(inputs, parameter_names, strict=True)\\n    ]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/test_flow_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f2ae6102da67bc457b0dadbb628ec8f32f02390e2b0ec32f894cba04e6ee0b80\",\"content\":\"from unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.helpers.flow import (\\n    get_flow_by_id_or_endpoint_name,\\n    get_flow_by_id_or_name,\\n    list_flows,\\n    list_flows_by_flow_folder,\\n    list_flows_by_folder_id,\\n)\\nfrom langflow.schema.data import Data\\nfrom langflow.services.database.models.flow.model import Flow\\n\\n\\nclass TestListFlows:\\n    \\\"\\\"\\\"Test list_flows function in backend.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_raises_error_without_user_id(self):\\n        \\\"\\\"\\\"Test that list_flows raises ValueError without user_id.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Session is invalid\\\"):\\n            await list_flows(user_id=None)\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_queries_database(self):\\n        \\\"\\\"\\\"Test that list_flows queries database correctly.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n\\n        mock_flow1 = MagicMock(spec=Flow)\\n        mock_flow1.to_data = MagicMock(return_value=Data(data={\\\"name\\\": \\\"Flow 1\\\"}))\\n\\n        mock_flow2 = MagicMock(spec=Flow)\\n        mock_flow2.to_data = MagicMock(return_value=Data(data={\\\"name\\\": \\\"Flow 2\\\"}))\\n\\n        with patch(\\\"langflow.helpers.flow.session_scope\\\") as mock_session_scope:\\n            mock_session = MagicMock()\\n            mock_result = MagicMock()\\n            mock_result.all = MagicMock(return_value=[mock_flow1, mock_flow2])\\n            mock_session.exec = AsyncMock(return_value=mock_result)\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n            mock_session_scope.return_value.__aexit__ = AsyncMock()\\n\\n            result = await list_flows(user_id=user_id)\\n\\n            assert len(result) == 2\\n            assert result[0].data[\\\"name\\\"] == \\\"Flow 1\\\"\\n            assert result[1].data[\\\"name\\\"] == \\\"Flow 2\\\"\\n\\n\\nclass TestListFlowsByFlowFolder:\\n    \\\"\\\"\\\"Test list_flows_by_flow_folder function in backend.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_by_flow_folder_raises_error_without_user_id(self):\\n        \\\"\\\"\\\"Test that function raises ValueError without user_id.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Session is invalid\\\"):\\n            await list_flows_by_flow_folder(user_id=None, flow_id=str(uuid4()))\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_by_flow_folder_raises_error_without_flow_id(self):\\n        \\\"\\\"\\\"Test that function raises ValueError without flow_id.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Flow ID is required\\\"):\\n            await list_flows_by_flow_folder(user_id=str(uuid4()), flow_id=None)\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_by_flow_folder_queries_same_folder(self):\\n        \\\"\\\"\\\"Test that function queries flows in same folder.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        flow_id = str(uuid4())\\n\\n        # Mock database results\\n        mock_row1 = MagicMock()\\n        mock_row1._mapping = {\\\"id\\\": str(uuid4()), \\\"name\\\": \\\"Flow 1\\\", \\\"updated_at\\\": \\\"2024-01-01\\\"}\\n\\n        mock_row2 = MagicMock()\\n        mock_row2._mapping = {\\\"id\\\": str(uuid4()), \\\"name\\\": \\\"Flow 2\\\", \\\"updated_at\\\": \\\"2024-01-02\\\"}\\n\\n        with patch(\\\"langflow.helpers.flow.session_scope\\\") as mock_session_scope:\\n            mock_session = MagicMock()\\n            mock_result = MagicMock()\\n            mock_result.all = MagicMock(return_value=[mock_row1, mock_row2])\\n            mock_session.exec = AsyncMock(return_value=mock_result)\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n            mock_session_scope.return_value.__aexit__ = AsyncMock()\\n\\n            result = await list_flows_by_flow_folder(user_id=user_id, flow_id=flow_id)\\n\\n            assert len(result) == 2\\n            assert isinstance(result[0], Data)\\n            assert result[0].data[\\\"name\\\"] == \\\"Flow 1\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_by_flow_folder_respects_order_params(self):\\n        \\\"\\\"\\\"Test that function respects ordering parameters.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        flow_id = str(uuid4())\\n        order_params = {\\\"column\\\": \\\"name\\\", \\\"direction\\\": \\\"asc\\\"}\\n\\n        with patch(\\\"langflow.helpers.flow.session_scope\\\") as mock_session_scope:\\n            mock_session = MagicMock()\\n            mock_result = MagicMock()\\n            mock_result.all = MagicMock(return_value=[])\\n            mock_session.exec = AsyncMock(return_value=mock_result)\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n            mock_session_scope.return_value.__aexit__ = AsyncMock()\\n\\n            result = await list_flows_by_flow_folder(user_id=user_id, flow_id=flow_id, order_params=order_params)\\n\\n            # Verify query was executed (result should be empty list from mock)\\n            assert result == []\\n\\n\\nclass TestListFlowsByFolderId:\\n    \\\"\\\"\\\"Test list_flows_by_folder_id function in backend.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_by_folder_id_raises_error_without_user_id(self):\\n        \\\"\\\"\\\"Test that function raises ValueError without user_id.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Session is invalid\\\"):\\n            await list_flows_by_folder_id(user_id=None, folder_id=str(uuid4()))\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_by_folder_id_raises_error_without_folder_id(self):\\n        \\\"\\\"\\\"Test that function raises ValueError without folder_id.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Folder ID is required\\\"):\\n            await list_flows_by_folder_id(user_id=str(uuid4()), folder_id=None)\\n\\n    @pytest.mark.asyncio\\n    async def test_list_flows_by_folder_id_queries_database(self):\\n        \\\"\\\"\\\"Test that function queries database for flows in folder.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        folder_id = str(uuid4())\\n\\n        mock_row1 = MagicMock()\\n        mock_row1._mapping = {\\\"id\\\": str(uuid4()), \\\"name\\\": \\\"Flow 1\\\"}\\n\\n        with patch(\\\"langflow.helpers.flow.session_scope\\\") as mock_session_scope:\\n            mock_session = MagicMock()\\n            mock_result = MagicMock()\\n            mock_result.all = MagicMock(return_value=[mock_row1])\\n            mock_session.exec = AsyncMock(return_value=mock_result)\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n            mock_session_scope.return_value.__aexit__ = AsyncMock()\\n\\n            result = await list_flows_by_folder_id(user_id=user_id, folder_id=folder_id)\\n\\n            assert len(result) == 1\\n            assert isinstance(result[0], Data)\\n\\n\\nclass TestGetFlowByIdOrName:\\n    \\\"\\\"\\\"Test get_flow_by_id_or_name function in backend.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_by_id_or_name_raises_error_without_user_id(self):\\n        \\\"\\\"\\\"Test that function raises ValueError without user_id.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Session is invalid\\\"):\\n            await get_flow_by_id_or_name(user_id=\\\"\\\", flow_id=str(uuid4()))\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_by_id_or_name_raises_error_without_id_or_name(self):\\n        \\\"\\\"\\\"Test that function raises ValueError without flow_id or flow_name.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Flow ID or Flow Name is required\\\"):\\n            await get_flow_by_id_or_name(user_id=str(uuid4()))\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_by_id_or_name_queries_by_id(self):\\n        \\\"\\\"\\\"Test that function queries database by flow ID.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        flow_id = str(uuid4())\\n\\n        mock_flow = MagicMock(spec=Flow)\\n        mock_flow.to_data = MagicMock(return_value=Data(data={\\\"name\\\": \\\"Test Flow\\\"}))\\n\\n        with patch(\\\"langflow.helpers.flow.session_scope\\\") as mock_session_scope:\\n            mock_session = MagicMock()\\n            mock_result = MagicMock()\\n            mock_result.first = MagicMock(return_value=mock_flow)\\n            mock_session.exec = AsyncMock(return_value=mock_result)\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n            mock_session_scope.return_value.__aexit__ = AsyncMock()\\n\\n            result = await get_flow_by_id_or_name(user_id=user_id, flow_id=flow_id)\\n\\n            assert isinstance(result, Data)\\n            assert result.data[\\\"name\\\"] == \\\"Test Flow\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_by_id_or_name_queries_by_name(self):\\n        \\\"\\\"\\\"Test that function queries database by flow name.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n\\n        mock_flow = MagicMock(spec=Flow)\\n        mock_flow.to_data = MagicMock(return_value=Data(data={\\\"name\\\": flow_name}))\\n\\n        with patch(\\\"langflow.helpers.flow.session_scope\\\") as mock_session_scope:\\n            mock_session = MagicMock()\\n            mock_result = MagicMock()\\n            mock_result.first = MagicMock(return_value=mock_flow)\\n            mock_session.exec = AsyncMock(return_value=mock_result)\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n            mock_session_scope.return_value.__aexit__ = AsyncMock()\\n\\n            result = await get_flow_by_id_or_name(user_id=user_id, flow_name=flow_name)\\n\\n            assert isinstance(result, Data)\\n            assert result.data[\\\"name\\\"] == flow_name\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_by_id_or_name_prefers_id_over_name(self):\\n        \\\"\\\"\\\"Test that function prefers flow_id when both are provided.\\\"\\\"\\\"\\n        user_id = str(uuid4())\\n        flow_id = str(uuid4())\\n        flow_name = \\\"Test Flow\\\"\\n\\n        mock_flow = MagicMock(spec=Flow)\\n        mock_flow.to_data = MagicMock(return_value=Data(data={\\\"id\\\": flow_id, \\\"name\\\": flow_name}))\\n\\n        with patch(\\\"langflow.helpers.flow.session_scope\\\") as mock_session_scope:\\n            mock_session = MagicMock()\\n            mock_result = MagicMock()\\n            mock_result.first = MagicMock(return_value=mock_flow)\\n            mock_session.exec = AsyncMock(return_value=mock_result)\\n            mock_session_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n            mock_session_scope.return_value.__aexit__ = AsyncMock()\\n\\n            result = await get_flow_by_id_or_name(user_id=user_id, flow_id=flow_id, flow_name=flow_name)\\n\\n            assert isinstance(result, Data)\\n            # The query should have been made with flow_id (checking it was called)\\n            mock_session.exec.assert_called_once()\\n\\n\\nclass TestGetFlowByIdOrEndpointName:\\n    \\\"\\\"\\\"Regression tests for the IDOR fix in get_flow_by_id_or_endpoint_name.\\n\\n    The UUID branch previously called ``session.get(Flow, flow_id)`` without\\n    applying any ownership check, so any authenticated caller could resolve\\n    another user's flow by UUID.  The endpoint_name branch had the matching\\n    issue when ``user_id`` was not supplied (the FastAPI ``Depends`` pattern\\n    provided no user_id by default).  These tests lock in the fix.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _patch_session(mock_session):\\n        \\\"\\\"\\\"Patch session_scope to yield the provided mock session.\\\"\\\"\\\"\\n        patcher = patch(\\\"langflow.helpers.flow.session_scope\\\")\\n        mock_scope = patcher.start()\\n        mock_scope.return_value.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_scope.return_value.__aexit__ = AsyncMock(return_value=False)\\n        return patcher\\n\\n    @pytest.mark.asyncio\\n    async def test_uuid_branch_returns_flow_for_owner(self):\\n        \\\"\\\"\\\"Same-user UUID lookup returns the flow (happy path).\\\"\\\"\\\"\\n        owner_id = uuid4()\\n        flow_id = uuid4()\\n        flow = MagicMock(spec=Flow)\\n        flow.id = flow_id\\n        flow.user_id = owner_id\\n        flow.name = \\\"test_flow\\\"\\n        flow.endpoint_name = None\\n        flow.data = {}\\n        flow.description = None\\n        flow.is_component = False\\n        flow.updated_at = None\\n        flow.folder_id = None\\n        flow.user_id = owner_id\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=flow)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with patch(\\\"langflow.helpers.flow.FlowRead\\\") as mock_flow_read:\\n                mock_flow_read.model_validate = MagicMock(return_value=\\\"validated_flow\\\")\\n                result = await get_flow_by_id_or_endpoint_name(str(flow_id), str(owner_id))\\n                assert result == \\\"validated_flow\\\"\\n                mock_session.get.assert_awaited_once_with(Flow, flow_id)\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_uuid_branch_rejects_cross_user_access(self):\\n        \\\"\\\"\\\"Cross-user UUID lookup raises 404 (the core IDOR fix).\\\"\\\"\\\"\\n        attacker_id = uuid4()\\n        victim_id = uuid4()\\n        flow_id = uuid4()\\n        victim_flow = MagicMock(spec=Flow)\\n        victim_flow.id = flow_id\\n        victim_flow.user_id = victim_id\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=victim_flow)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with pytest.raises(HTTPException) as exc_info:\\n                await get_flow_by_id_or_endpoint_name(str(flow_id), str(attacker_id))\\n            assert exc_info.value.status_code == 404\\n            # Must NOT 403 -- returning 403 would confirm the flow exists to\\n            # an attacker enumerating UUIDs.  404 hides existence.\\n            assert \\\"not found\\\" in exc_info.value.detail.lower()\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_uuid_branch_accepts_uuid_instance_for_user_id(self):\\n        \\\"\\\"\\\"Callers passing a UUID object (not str) are handled correctly.\\\"\\\"\\\"\\n        attacker_id = uuid4()\\n        victim_id = uuid4()\\n        flow_id = uuid4()\\n        victim_flow = MagicMock(spec=Flow)\\n        victim_flow.id = flow_id\\n        victim_flow.user_id = victim_id\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=victim_flow)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with pytest.raises(HTTPException) as exc_info:\\n                # Pass UUID, not str -- matches workflow.py:151 call style.\\n                await get_flow_by_id_or_endpoint_name(str(flow_id), attacker_id)\\n            assert exc_info.value.status_code == 404\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_uuid_branch_without_user_id_returns_flow(self):\\n        \\\"\\\"\\\"No user_id = no scoping (preserves webhook/internal caller behavior).\\\"\\\"\\\"\\n        flow_id = uuid4()\\n        flow = MagicMock(spec=Flow)\\n        flow.id = flow_id\\n        flow.user_id = uuid4()\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=flow)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with patch(\\\"langflow.helpers.flow.FlowRead\\\") as mock_flow_read:\\n                mock_flow_read.model_validate = MagicMock(return_value=\\\"validated_flow\\\")\\n                # user_id=None: any flow is returned.\\n                result = await get_flow_by_id_or_endpoint_name(str(flow_id), user_id=None)\\n                assert result == \\\"validated_flow\\\"\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_uuid_branch_missing_flow_raises_404(self):\\n        \\\"\\\"\\\"Non-existent UUID returns 404 regardless of user_id.\\\"\\\"\\\"\\n        owner_id = uuid4()\\n        flow_id = uuid4()\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=None)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with pytest.raises(HTTPException) as exc_info:\\n                await get_flow_by_id_or_endpoint_name(str(flow_id), str(owner_id))\\n            assert exc_info.value.status_code == 404\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_endpoint_name_branch_scopes_by_user(self):\\n        \\\"\\\"\\\"endpoint_name lookup filters by user_id when supplied.\\\"\\\"\\\"\\n        owner_id = uuid4()\\n\\n        mock_session = MagicMock()\\n        mock_result = MagicMock()\\n        mock_result.first = MagicMock(return_value=None)\\n        mock_session.exec = AsyncMock(return_value=mock_result)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with pytest.raises(HTTPException) as exc_info:\\n                await get_flow_by_id_or_endpoint_name(\\\"my-webhook\\\", str(owner_id))\\n            assert exc_info.value.status_code == 404\\n            # The select statement should have been filtered by user_id --\\n            # verified indirectly by the exec call count (1 call, scoped).\\n            mock_session.exec.assert_awaited_once()\\n            stmt = mock_session.exec.await_args.args[0]\\n            # Compile the where clauses and confirm the user_id filter is present.\\n            where_sql = str(stmt.whereclause)\\n            assert \\\"user_id\\\" in where_sql\\n\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_endpoint_name_branch_without_user_id_not_scoped(self):\\n        \\\"\\\"\\\"No user_id on endpoint_name branch = no user scoping (webhook behavior).\\\"\\\"\\\"\\n        flow = MagicMock(spec=Flow)\\n        flow.id = uuid4()\\n        flow.user_id = uuid4()\\n\\n        mock_session = MagicMock()\\n        mock_result = MagicMock()\\n        mock_result.first = MagicMock(return_value=flow)\\n        mock_session.exec = AsyncMock(return_value=mock_result)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with patch(\\\"langflow.helpers.flow.FlowRead\\\") as mock_flow_read:\\n                mock_flow_read.model_validate = MagicMock(return_value=\\\"validated_flow\\\")\\n                result = await get_flow_by_id_or_endpoint_name(\\\"webhook-ep\\\", user_id=None)\\n                assert result == \\\"validated_flow\\\"\\n                stmt = mock_session.exec.await_args.args[0]\\n                where_sql = str(stmt.whereclause) if stmt.whereclause is not None else \\\"\\\"\\n                # With no user_id, the only filter should be endpoint_name.\\n                assert \\\"user_id\\\" not in where_sql\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_accepts_uuid_instance_for_user_id_parameter(self):\\n        \\\"\\\"\\\"user_id can be a UUID object (matches workflow.py call sites).\\\"\\\"\\\"\\n        owner_id = UUID(str(uuid4()))\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=None)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with pytest.raises(HTTPException):\\n                await get_flow_by_id_or_endpoint_name(str(uuid4()), owner_id)\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_widening_is_opt_in_even_when_authz_active(self):\\n        \\\"\\\"\\\"Cross-user UUID lookup stays 404 unless caller explicitly opts in.\\n\\n        Regression: the share-aware widening must never fire from the helper's\\n        default arguments \u2014 agentic MCP tools call the helper without\\n        ``widen_for_shares=True`` and then read ``flow.data`` directly, so an\\n        always-on widen would leak another user's graph metadata before any\\n        policy decision runs.\\n        \\\"\\\"\\\"\\n        attacker_id = uuid4()\\n        victim_id = uuid4()\\n        flow_id = uuid4()\\n        victim_flow = MagicMock(spec=Flow)\\n        victim_flow.id = flow_id\\n        victim_flow.user_id = victim_id\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=victim_flow)\\n\\n        # Stub authz so cross-user fetch + AUTHZ_ENABLED are both ON, which\\n        # under the old contract would have widened the lookup. With the new\\n        # opt-in flag default-false, widening must NOT happen.\\n        stub_authz = MagicMock()\\n        stub_authz.supports_cross_user_fetch = AsyncMock(return_value=True)\\n        stub_authz.is_enabled = AsyncMock(return_value=True)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=stub_authz):  # noqa: SIM117\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_flow_by_id_or_endpoint_name(str(flow_id), str(attacker_id))\\n            assert exc_info.value.status_code == 404\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.asyncio\\n    async def test_widening_allows_cross_user_when_opt_in_and_authz_active(self):\\n        \\\"\\\"\\\"When the caller opts in AND authz is active, share-aware lookup widens.\\n\\n        This is the path used by API routes that immediately call\\n        ``ensure_flow_permission`` afterward \u2014 widening is safe there because\\n        a permission check follows the fetch.\\n        \\\"\\\"\\\"\\n        attacker_id = uuid4()\\n        victim_id = uuid4()\\n        flow_id = uuid4()\\n        victim_flow = MagicMock(spec=Flow)\\n        victim_flow.id = flow_id\\n        victim_flow.user_id = victim_id\\n\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=victim_flow)\\n\\n        stub_authz = MagicMock()\\n        stub_authz.supports_cross_user_fetch = AsyncMock(return_value=True)\\n        stub_authz.is_enabled = AsyncMock(return_value=True)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with patch(\\\"langflow.services.deps.get_authorization_service\\\", return_value=stub_authz):  # noqa: SIM117\\n                with patch(\\\"langflow.helpers.flow.FlowRead\\\") as mock_flow_read:\\n                    mock_flow_read.model_validate = MagicMock(return_value=\\\"validated_flow\\\")\\n                    result = await get_flow_by_id_or_endpoint_name(\\n                        str(flow_id),\\n                        str(attacker_id),\\n                        widen_for_shares=True,\\n                    )\\n                    assert result == \\\"validated_flow\\\"\\n        finally:\\n            patcher.stop()\\n\\n    @pytest.mark.parametrize(\\\"bad_user_id\\\", [\\\"not-a-uuid\\\", \\\"\\\", \\\"12345-not-a-real-uuid\\\"])\\n    @pytest.mark.asyncio\\n    async def test_malformed_user_id_raises_404_not_500(self, bad_user_id):\\n        \\\"\\\"\\\"Malformed user_id (e.g. ``?user_id=foo``) must fail closed with 404.\\n\\n        Previously the eager ``UUID(user_id)`` normalization raised a raw\\n        ``ValueError`` that surfaced as a 500 to the client.  The helper now\\n        converts that into the same 404 we'd return for \\\"flow not found\\\" so\\n        that a malformed caller identity can never be used to enumerate or\\n        exfiltrate flows, and doesn't give attackers a new error signal.\\n        \\\"\\\"\\\"\\n        mock_session = MagicMock()\\n        mock_session.get = AsyncMock(return_value=None)\\n\\n        patcher = self._patch_session(mock_session)\\n        try:\\n            with pytest.raises(HTTPException) as exc_info:\\n                await get_flow_by_id_or_endpoint_name(str(uuid4()), bad_user_id)\\n            assert exc_info.value.status_code == 404\\n            # Session lookup should never happen if user_id couldn't be parsed.\\n            mock_session.get.assert_not_awaited()\\n        finally:\\n            patcher.stop()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/helpers/test_suggest_flow_type.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"88fcabb409103c10990815b41ef559f3f9309d19dc4298e3617722ed47209cbf\",\"content\":\"\\\"\\\"\\\"Tests for helpers.flow.suggest_flow_type (F1 agent auto-detect).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport langflow\\nimport pytest\\nfrom langflow.helpers.flow import suggest_flow_type\\nfrom langflow.services.database.models.flow.model import FlowType\\n\\n_STARTERS = Path(langflow.__file__).parent / \\\"initial_setup\\\" / \\\"starter_projects\\\"\\n\\n\\ndef _load_agent_starter() -> dict:\\n    \\\"\\\"\\\"Return the graph data of a real starter project that contains an Agent node.\\\"\\\"\\\"\\n    for path in sorted(_STARTERS.glob(\\\"*.json\\\")):\\n        data = json.loads(path.read_text(encoding=\\\"utf-8\\\")).get(\\\"data\\\") or {}\\n        if any((node.get(\\\"data\\\") or {}).get(\\\"type\\\") == \\\"Agent\\\" for node in data.get(\\\"nodes\\\") or []):\\n            return data\\n    pytest.skip(\\\"No starter project with an Agent node found\\\")\\n    return {}\\n\\n\\ndef _first_non_agent_node(graph_data: dict) -> dict:\\n    for node in graph_data.get(\\\"nodes\\\") or []:\\n        node_data = node.get(\\\"data\\\") or {}\\n        if node_data.get(\\\"type\\\") != \\\"Agent\\\" and node_data.get(\\\"node\\\", {}).get(\\\"template\\\", {}).get(\\\"code\\\", {}).get(\\n            \\\"value\\\"\\n        ):\\n            return node\\n    pytest.skip(\\\"No non-agent node with code found in starter\\\")\\n    return {}\\n\\n\\ndef test_suggest_agent_for_flow_with_agent_component():\\n    agent_graph = _load_agent_starter()\\n    assert suggest_flow_type(agent_graph) == FlowType.AGENT\\n\\n\\ndef test_suggest_workflow_for_flow_without_agent_component():\\n    agent_graph = _load_agent_starter()\\n    workflow_graph = {\\\"nodes\\\": [_first_non_agent_node(agent_graph)], \\\"edges\\\": []}\\n    assert suggest_flow_type(workflow_graph) == FlowType.WORKFLOW\\n\\n\\ndef test_suggest_workflow_for_empty_or_missing_data():\\n    assert suggest_flow_type({\\\"nodes\\\": [], \\\"edges\\\": []}) == FlowType.WORKFLOW\\n    assert suggest_flow_type(None) == FlowType.WORKFLOW\\n\\n\\ndef test_suggest_never_raises_on_malformed_nodes():\\n    bad = {\\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"code\\\": {\\\"value\\\": \\\"this is not python (\\\"}}}}}]}\\n    assert suggest_flow_type(bad) == FlowType.WORKFLOW\\n\\n\\ndef test_suggest_agent_for_pre_split_flow_whose_code_no_longer_evaluates():\\n    \\\"\\\"\\\"A pre-split flow's agent code no longer evaluates; the stable component name still classifies it.\\\"\\\"\\\"\\n    agent_graph = _load_agent_starter()\\n    for node in agent_graph.get(\\\"nodes\\\") or []:\\n        node_data = node.get(\\\"data\\\") or {}\\n        if node_data.get(\\\"type\\\") == \\\"Agent\\\":\\n            # Break the stored code the way a pre-lfx-split flow would: imports to a module gone today.\\n            node_data[\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = \\\"from langflow_gone.agents import Agent\\\\n\\\"\\n            break\\n    assert suggest_flow_type(agent_graph) == FlowType.AGENT\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/initial_setup/test_upsert_flow_from_file.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"469ad4923ca69e03aaf625b111168b73fd003509277f8b2160611deba3f8749d\",\"content\":\"\\\"\\\"\\\"Regression tests for find_existing_flow / upsert_flow_from_file.\\n\\nCovers the CI/CD upgrade scenario where a flow file's id differs from the DB\\nrow's id but the flow name is the same. Before the fix the loader hit the\\n``unique_flow_name`` UniqueConstraint on INSERT and Langflow failed to start.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextlib import contextmanager\\nfrom uuid import uuid4\\n\\nimport orjson\\nimport pytest\\nfrom langflow.initial_setup.setup import (\\n    find_existing_flow,\\n    get_or_create_default_folder,\\n    session_scope,\\n    upsert_flow_from_file,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.user.model import User\\nfrom lfx.services.deps import get_settings_service\\nfrom sqlmodel import select\\n\\n\\n@contextmanager\\ndef _overwrite_on_name_match(*, enabled: bool):\\n    \\\"\\\"\\\"Temporarily override the load_flows_overwrite_on_name_match setting.\\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n    original = settings.load_flows_overwrite_on_name_match\\n    settings.load_flows_overwrite_on_name_match = enabled\\n    try:\\n        yield\\n    finally:\\n        settings.load_flows_overwrite_on_name_match = original\\n\\n\\n@contextmanager\\ndef _preserve_variable_bindings(*, enabled: bool):\\n    \\\"\\\"\\\"Temporarily override the load_flows_preserve_variable_bindings setting.\\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n    original = settings.load_flows_preserve_variable_bindings\\n    settings.load_flows_preserve_variable_bindings = enabled\\n    try:\\n        yield\\n    finally:\\n        settings.load_flows_preserve_variable_bindings = original\\n\\n\\ndef _node_with_field(node_id: str, *, value: str, load_from_db: bool) -> dict:\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"data\\\": {\\n            \\\"node\\\": {\\n                \\\"template\\\": {\\n                    \\\"api_key\\\": {\\n                        \\\"value\\\": value,\\n                        \\\"load_from_db\\\": load_from_db,\\n                    }\\n                }\\n            }\\n        },\\n    }\\n\\n\\ndef _group_node(node_id: str, *nodes: dict) -> dict:\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"data\\\": {\\n            \\\"node\\\": {\\n                \\\"template\\\": {},\\n                \\\"flow\\\": {\\\"data\\\": {\\\"nodes\\\": list(nodes), \\\"edges\\\": []}},\\n            }\\n        },\\n    }\\n\\n\\nasync def _create_flow(\\n    *,\\n    name: str,\\n    user_id,\\n    flow_id=None,\\n    endpoint_name=None,\\n    data=None,\\n) -> Flow:\\n    \\\"\\\"\\\"Insert a minimal Flow row and return it.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        folder = await get_or_create_default_folder(session, user_id)\\n        flow = Flow(\\n            id=flow_id or uuid4(),\\n            name=name,\\n            description=\\\"initial\\\",\\n            data=data or {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            user_id=user_id,\\n            folder_id=folder.id,\\n            endpoint_name=endpoint_name,\\n        )\\n        session.add(flow)\\n        await session.flush()\\n        await session.refresh(flow)\\n        return flow\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_find_existing_flow_by_name_when_id_differs() -> None:\\n    \\\"\\\"\\\"Match by (user_id, name) when the file's id doesn't exist in the DB.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(name=\\\"MyFlow\\\", user_id=user_id)\\n\\n    async with session_scope() as session:\\n        result = await find_existing_flow(\\n            session,\\n            flow_id=uuid4(),  # different from the one in the DB\\n            flow_endpoint_name=None,\\n            user_id=user_id,\\n            name=\\\"MyFlow\\\",\\n        )\\n        assert result is not None\\n        assert result.id == original.id\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_find_existing_flow_returns_none_for_unmatched_name() -> None:\\n    user_id = uuid4()\\n    await _create_flow(name=\\\"MyFlow\\\", user_id=user_id)\\n\\n    async with session_scope() as session:\\n        result = await find_existing_flow(\\n            session,\\n            flow_id=uuid4(),\\n            flow_endpoint_name=None,\\n            user_id=user_id,\\n            name=\\\"OtherFlow\\\",\\n        )\\n        assert result is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_find_existing_flow_id_match_still_wins() -> None:\\n    \\\"\\\"\\\"The id branch still runs first; name fallback only fires on no id match.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(name=\\\"N1\\\", user_id=user_id)\\n\\n    async with session_scope() as session:\\n        # Mismatched name -- should still match by id and return the original.\\n        result = await find_existing_flow(\\n            session,\\n            flow_id=original.id,\\n            flow_endpoint_name=None,\\n            user_id=user_id,\\n            name=\\\"N2\\\",\\n        )\\n        assert result is not None\\n        assert result.id == original.id\\n        assert result.name == \\\"N1\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_find_existing_flow_endpoint_name_scoped_by_user() -> None:\\n    \\\"\\\"\\\"Endpoint-name lookup must not return another user's flow when user_id is supplied.\\\"\\\"\\\"\\n    user_a = uuid4()\\n    user_b = uuid4()\\n    flow_a = await _create_flow(name=\\\"A\\\", user_id=user_a, endpoint_name=\\\"shared\\\")\\n\\n    # user_b doesn't have any flow at all -- but unscoped lookup would still match flow_a.\\n    async with session_scope() as session:\\n        result = await find_existing_flow(\\n            session,\\n            flow_id=uuid4(),\\n            flow_endpoint_name=\\\"shared\\\",\\n            user_id=user_b,\\n        )\\n        assert result is None, \\\"endpoint_name lookup must be scoped by user_id\\\"\\n\\n        # Scoping to flow_a's user returns it.\\n        result = await find_existing_flow(\\n            session,\\n            flow_id=uuid4(),\\n            flow_endpoint_name=\\\"shared\\\",\\n            user_id=user_a,\\n        )\\n        assert result is not None\\n        assert result.id == flow_a.id\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_updates_existing_by_name() -> None:\\n    \\\"\\\"\\\"Reporter's CI/CD scenario with overwrite enabled: name match updates existing row.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(\\n        name=\\\"MyFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n    )\\n\\n    file_id = uuid4()\\n    file_content = orjson.dumps(\\n        {\\n            \\\"id\\\": str(file_id),\\n            \\\"name\\\": \\\"MyFlow\\\",\\n            \\\"description\\\": \\\"updated from file\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"n1\\\"}], \\\"edges\\\": []},\\n        }\\n    )\\n\\n    with _overwrite_on_name_match(enabled=True):\\n        async with session_scope() as session:\\n            # Must not raise IntegrityError on the unique_flow_name constraint.\\n            await upsert_flow_from_file(file_content, \\\"MyFlow\\\", session, user_id)\\n            await session.commit()\\n\\n    # Confirm: exactly one row, DB id preserved, content updated.\\n    async with session_scope() as session:\\n        flows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(flows) == 1\\n        updated = flows[0]\\n        assert updated.id == original.id, \\\"DB id must be preserved on name-matched update\\\"\\n        assert updated.description == \\\"updated from file\\\"\\n        assert updated.data == {\\\"nodes\\\": [{\\\"id\\\": \\\"n1\\\"}], \\\"edges\\\": []}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_default_skips_name_match() -> None:\\n    \\\"\\\"\\\"Default (overwrite=False): name match with differing id does NOT crash and does NOT overwrite.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(\\n        name=\\\"MyFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [{\\\"id\\\": \\\"user-node\\\"}], \\\"edges\\\": []},\\n    )\\n\\n    file_id = uuid4()\\n    file_content = orjson.dumps(\\n        {\\n            \\\"id\\\": str(file_id),\\n            \\\"name\\\": \\\"MyFlow\\\",\\n            \\\"description\\\": \\\"would overwrite\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        }\\n    )\\n\\n    async with session_scope() as session:\\n        # Must not raise IntegrityError; must not overwrite.\\n        await upsert_flow_from_file(file_content, \\\"MyFlow\\\", session, user_id)\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        flows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(flows) == 1\\n        preserved = flows[0]\\n        assert preserved.id == original.id\\n        assert preserved.description == \\\"initial\\\"\\n        assert preserved.data == {\\\"nodes\\\": [{\\\"id\\\": \\\"user-node\\\"}], \\\"edges\\\": []}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_creates_when_no_match() -> None:\\n    \\\"\\\"\\\"Empty DB -> upsert creates the row with the file's id.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    # Need a default folder for the user so upsert can assign folder_id.\\n    async with session_scope() as session:\\n        await get_or_create_default_folder(session, user_id)\\n\\n    file_id = uuid4()\\n    file_content = orjson.dumps(\\n        {\\n            \\\"id\\\": str(file_id),\\n            \\\"name\\\": \\\"FreshFlow\\\",\\n            \\\"description\\\": \\\"brand new\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        }\\n    )\\n\\n    async with session_scope() as session:\\n        await upsert_flow_from_file(file_content, \\\"FreshFlow\\\", session, user_id)\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        result = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(result) == 1\\n        assert result[0].id == file_id\\n        assert result[0].name == \\\"FreshFlow\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_no_unique_violation_on_repeat() -> None:\\n    \\\"\\\"\\\"Calling upsert twice with different file ids and the same name must not raise.\\n\\n    With overwrite enabled this is the CI/CD nightly-rebuild path: second import updates.\\n    \\\"\\\"\\\"\\n    user_id = uuid4()\\n    async with session_scope() as session:\\n        await get_or_create_default_folder(session, user_id)\\n\\n    def make_payload(flow_id, description: str) -> bytes:\\n        return orjson.dumps(\\n            {\\n                \\\"id\\\": str(flow_id),\\n                \\\"name\\\": \\\"Recurring\\\",\\n                \\\"description\\\": description,\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            }\\n        )\\n\\n    with _overwrite_on_name_match(enabled=True):\\n        # First import: row inserted with id=A.\\n        id_a = uuid4()\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(make_payload(id_a, \\\"first\\\"), \\\"Recurring\\\", session, user_id)\\n            await session.commit()\\n\\n        # Second import (e.g. nightly upgrade with regenerated UUIDs): same name, id=B.\\n        # Must update the existing row, not raise IntegrityError.\\n        id_b = uuid4()\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(make_payload(id_b, \\\"second\\\"), \\\"Recurring\\\", session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        rows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(rows) == 1\\n        assert rows[0].id == id_a, \\\"DB id from first import is preserved\\\"\\n        assert rows[0].description == \\\"second\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_id_match_still_overwrites_id_field() -> None:\\n    \\\"\\\"\\\"When matched by id, the existing setattr loop is unchanged (no regression).\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(name=\\\"IdMatch\\\", user_id=user_id)\\n\\n    file_content = orjson.dumps(\\n        {\\n            \\\"id\\\": str(original.id),  # same id -> matched_by_id is True\\n            \\\"name\\\": \\\"IdMatch\\\",\\n            \\\"description\\\": \\\"updated\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        }\\n    )\\n\\n    async with session_scope() as session:\\n        await upsert_flow_from_file(file_content, \\\"IdMatch\\\", session, user_id)\\n        await session.commit()\\n\\n    async with session_scope() as session:\\n        rows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(rows) == 1\\n        assert rows[0].id == original.id\\n        assert rows[0].description == \\\"updated\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\n@pytest.mark.parametrize(\\\"incoming_load_from_db\\\", [False, True])\\nasync def test_upsert_flow_from_file_preserves_existing_variable_binding(incoming_load_from_db) -> None:\\n    \\\"\\\"\\\"A UI-configured global-variable binding survives a same-id startup re-import.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    existing_node = _node_with_field(\\\"n1\\\", value=\\\"OPENAI_API_KEY\\\", load_from_db=True)\\n    existing_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"][\\\"display_name\\\"] = \\\"Old label\\\"\\n    original = await _create_flow(\\n        name=\\\"BoundFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [existing_node], \\\"edges\\\": []},\\n    )\\n    incoming_data = {\\n        \\\"nodes\\\": [_node_with_field(\\\"n1\\\", value=\\\"\\\", load_from_db=incoming_load_from_db)],\\n        \\\"edges\\\": [{\\\"id\\\": \\\"updated-edge\\\"}],\\n    }\\n    incoming_data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"][\\\"display_name\\\"] = \\\"New label\\\"\\n    file_content = orjson.dumps({\\\"id\\\": str(original.id), \\\"name\\\": original.name, \\\"data\\\": incoming_data})\\n\\n    with _preserve_variable_bindings(enabled=True):\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, original.name, session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        updated = (await session.exec(select(Flow).where(Flow.id == original.id))).one()\\n        field = updated.data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"]\\n        assert field == {\\\"value\\\": \\\"OPENAI_API_KEY\\\", \\\"load_from_db\\\": True, \\\"display_name\\\": \\\"New label\\\"}\\n        assert updated.data[\\\"edges\\\"] == incoming_data[\\\"edges\\\"]\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_explicit_file_variable_binding_wins() -> None:\\n    \\\"\\\"\\\"An explicit binding in the file remains the source of truth.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(\\n        name=\\\"ReboundFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [_node_with_field(\\\"n1\\\", value=\\\"OLD_API_KEY\\\", load_from_db=True)], \\\"edges\\\": []},\\n    )\\n    incoming_data = {\\n        \\\"nodes\\\": [_node_with_field(\\\"n1\\\", value=\\\"NEW_API_KEY\\\", load_from_db=True)],\\n        \\\"edges\\\": [],\\n    }\\n    file_content = orjson.dumps({\\\"id\\\": str(original.id), \\\"name\\\": original.name, \\\"data\\\": incoming_data})\\n\\n    with _preserve_variable_bindings(enabled=True):\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, original.name, session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        updated = (await session.exec(select(Flow).where(Flow.id == original.id))).one()\\n        field = updated.data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"]\\n        assert field == {\\\"value\\\": \\\"NEW_API_KEY\\\", \\\"load_from_db\\\": True}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_preserves_nested_variable_binding() -> None:\\n    \\\"\\\"\\\"Bindings inside grouped flows survive the same recursive startup merge.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    existing_group = _group_node(\\\"group\\\", _node_with_field(\\\"nested\\\", value=\\\"NESTED_API_KEY\\\", load_from_db=True))\\n    original = await _create_flow(\\n        name=\\\"GroupedFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [existing_group], \\\"edges\\\": []},\\n    )\\n    incoming_group = _group_node(\\\"group\\\", _node_with_field(\\\"nested\\\", value=\\\"\\\", load_from_db=False))\\n    incoming_data = {\\\"nodes\\\": [incoming_group], \\\"edges\\\": []}\\n    file_content = orjson.dumps({\\\"id\\\": str(original.id), \\\"name\\\": original.name, \\\"data\\\": incoming_data})\\n\\n    with _preserve_variable_bindings(enabled=True):\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, original.name, session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        updated = (await session.exec(select(Flow).where(Flow.id == original.id))).one()\\n        nested_node = updated.data[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"flow\\\"][\\\"data\\\"][\\\"nodes\\\"][0]\\n        field = nested_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"]\\n        assert field == {\\\"value\\\": \\\"NESTED_API_KEY\\\", \\\"load_from_db\\\": True}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_keeps_new_file_nodes_unchanged() -> None:\\n    \\\"\\\"\\\"Nodes without a DB counterpart pass through the merge unchanged.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(\\n        name=\\\"ExpandedFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [_node_with_field(\\\"existing\\\", value=\\\"API_KEY\\\", load_from_db=True)], \\\"edges\\\": []},\\n    )\\n    new_node = _node_with_field(\\\"new\\\", value=\\\"literal-from-file\\\", load_from_db=False)\\n    incoming_data = {\\\"nodes\\\": [new_node], \\\"edges\\\": []}\\n    file_content = orjson.dumps({\\\"id\\\": str(original.id), \\\"name\\\": original.name, \\\"data\\\": incoming_data})\\n\\n    with _preserve_variable_bindings(enabled=True):\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, original.name, session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        updated = (await session.exec(select(Flow).where(Flow.id == original.id))).one()\\n        assert updated.data == incoming_data\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_can_disable_variable_binding_preservation() -> None:\\n    \\\"\\\"\\\"The opt-out restores the previous blind-overwrite behavior.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(\\n        name=\\\"GitOpsFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [_node_with_field(\\\"n1\\\", value=\\\"API_KEY\\\", load_from_db=True)], \\\"edges\\\": []},\\n    )\\n    incoming_data = {\\n        \\\"nodes\\\": [_node_with_field(\\\"n1\\\", value=\\\"literal-from-file\\\", load_from_db=False)],\\n        \\\"edges\\\": [],\\n    }\\n    file_content = orjson.dumps({\\\"id\\\": str(original.id), \\\"name\\\": original.name, \\\"data\\\": incoming_data})\\n\\n    with _preserve_variable_bindings(enabled=False):\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, original.name, session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        updated = (await session.exec(select(Flow).where(Flow.id == original.id))).one()\\n        assert updated.data == incoming_data\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_does_not_preserve_empty_default_binding() -> None:\\n    \\\"\\\"\\\"An empty load-from-DB default must not override a literal value from the file.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(\\n        name=\\\"DefaultSecretFlow\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [_node_with_field(\\\"n1\\\", value=\\\"\\\", load_from_db=True)], \\\"edges\\\": []},\\n    )\\n    incoming_data = {\\n        \\\"nodes\\\": [_node_with_field(\\\"n1\\\", value=\\\"literal-from-file\\\", load_from_db=False)],\\n        \\\"edges\\\": [],\\n    }\\n    file_content = orjson.dumps({\\\"id\\\": str(original.id), \\\"name\\\": original.name, \\\"data\\\": incoming_data})\\n\\n    with _preserve_variable_bindings(enabled=True):\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, original.name, session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        updated = (await session.exec(select(Flow).where(Flow.id == original.id))).one()\\n        assert updated.data == incoming_data\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_skips_name_match_when_overwrite_disabled() -> None:\\n    \\\"\\\"\\\"When load_flows_overwrite_on_name_match=False, name-matched rows are NOT overwritten.\\n\\n    Protects the case where a user edited a flow in the UI and Langflow restarts with a\\n    regenerated file id; the on-disk JSON should not silently wipe the user's changes.\\n    \\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(\\n        name=\\\"UserEdited\\\",\\n        user_id=user_id,\\n        data={\\\"nodes\\\": [{\\\"id\\\": \\\"user-node\\\"}], \\\"edges\\\": []},\\n    )\\n\\n    with _overwrite_on_name_match(enabled=False):\\n        file_content = orjson.dumps(\\n            {\\n                \\\"id\\\": str(uuid4()),  # regenerated id -> name match only\\n                \\\"name\\\": \\\"UserEdited\\\",\\n                \\\"description\\\": \\\"from disk (should be ignored)\\\",\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            }\\n        )\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, \\\"UserEdited\\\", session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        rows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(rows) == 1\\n        assert rows[0].id == original.id\\n        # User's UI edits preserved -- file contents did not overwrite them.\\n        assert rows[0].description == \\\"initial\\\"\\n        assert rows[0].data == {\\\"nodes\\\": [{\\\"id\\\": \\\"user-node\\\"}], \\\"edges\\\": []}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_ignores_relationship_keys_in_json() -> None:\\n    \\\"\\\"\\\"BUG-001 regression: JSON keys that collide with SQLAlchemy relationships must not crash.\\n\\n    Previously the loader used ``hasattr(existing, key)`` + ``setattr``. ``hasattr`` returns\\n    True for relationship attributes (``user``, ``folder``), and ``getattr`` on an unloaded\\n    relationship under an async session triggers an implicit lazy load outside greenlet\\n    context, raising ``MissingGreenlet`` (\\\"greenlet_spawn has not been called; can't call\\n    await_only() here.\\\") and crashing Langflow startup.\\n    \\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(name=\\\"WithRel\\\", user_id=user_id)\\n\\n    file_content = orjson.dumps(\\n        {\\n            \\\"id\\\": str(uuid4()),  # name-matched path (different id)\\n            \\\"name\\\": \\\"WithRel\\\",\\n            \\\"description\\\": \\\"updated\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            # Adversarial keys that match Flow relationship attribute names.\\n            # The loader must skip these instead of triggering a lazy load.\\n            \\\"user\\\": {\\\"id\\\": str(uuid4()), \\\"username\\\": \\\"ghost\\\"},\\n            \\\"folder\\\": {\\\"id\\\": str(uuid4()), \\\"name\\\": \\\"ghost-folder\\\"},\\n        }\\n    )\\n\\n    with _overwrite_on_name_match(enabled=True):\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, \\\"WithRel\\\", session, user_id)\\n\\n    async with session_scope() as session:\\n        rows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(rows) == 1\\n        assert rows[0].id == original.id\\n        assert rows[0].description == \\\"updated\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_with_user_loaded_in_same_session() -> None:\\n    \\\"\\\"\\\"BUG-001 regression: mimics ``load_flows_from_directory`` session shape.\\n\\n    ``load_flows_from_directory`` loads the superuser into the session *before* calling\\n    ``upsert_flow_from_file``. With ``back_populates`` on ``User.flows``, setting\\n    ``existing.user_id`` (or relying on autoflush at commit) can attempt to sync the\\n    back-reference and load relationships lazily. Letting ``session_scope`` auto-commit\\n    here (no explicit ``await session.commit()``) is the exact production code path that\\n    crashed with ``MissingGreenlet``.\\n    \\\"\\\"\\\"\\n    username = f\\\"u_{uuid4().hex}\\\"\\n    # Real User row + flow already linked, mirroring a flow created via the UI before\\n    # the load_flows_path file was added.\\n    async with session_scope() as session:\\n        user_row = User(\\n            username=username,\\n            password=\\\"x\\\",  # noqa: S106\\n            is_active=True,\\n            is_superuser=True,\\n        )\\n        session.add(user_row)\\n        await session.flush()\\n        await session.refresh(user_row)\\n        user_id = user_row.id\\n        folder = await get_or_create_default_folder(session, user_id)\\n        session.add(\\n            Flow(\\n                id=uuid4(),\\n                name=f\\\"le-1134-test-flow-{username}\\\",\\n                description=\\\"initial\\\",\\n                data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n                user_id=user_id,\\n                folder_id=folder.id,\\n            )\\n        )\\n\\n    file_content = orjson.dumps(\\n        {\\n            \\\"id\\\": str(uuid4()),  # different id -> name-match path\\n            \\\"name\\\": f\\\"le-1134-test-flow-{username}\\\",\\n            \\\"description\\\": \\\"updated from file\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [{\\\"id\\\": \\\"n1\\\"}], \\\"edges\\\": []},\\n        }\\n    )\\n\\n    with _overwrite_on_name_match(enabled=True):\\n        async with session_scope() as session:\\n            # Load *our* user into the session (mirrors load_flows_from_directory loading\\n            # the superuser). Filter by username so we don't pick up the default langflow\\n            # superuser the test fixture creates.\\n            stmt = select(User).where(User.username == username)\\n            loaded_user = (await session.exec(stmt)).first()\\n            assert loaded_user is not None\\n            await upsert_flow_from_file(file_content, f\\\"le-1134-test-flow-{username}\\\", session, loaded_user.id)\\n            # No explicit commit: session_scope must auto-commit without MissingGreenlet.\\n\\n    async with session_scope() as session:\\n        rows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(rows) == 1\\n        assert rows[0].description == \\\"updated from file\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_upsert_flow_from_file_id_match_still_overwrites_when_flag_disabled() -> None:\\n    \\\"\\\"\\\"The flag only gates name-matched overwrites; id-matched overwrites are unchanged.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    original = await _create_flow(name=\\\"IdMatchFlag\\\", user_id=user_id)\\n\\n    with _overwrite_on_name_match(enabled=False):\\n        file_content = orjson.dumps(\\n            {\\n                \\\"id\\\": str(original.id),  # same id -> matched_by_id is True\\n                \\\"name\\\": \\\"IdMatchFlag\\\",\\n                \\\"description\\\": \\\"updated via id-match\\\",\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            }\\n        )\\n        async with session_scope() as session:\\n            await upsert_flow_from_file(file_content, \\\"IdMatchFlag\\\", session, user_id)\\n            await session.commit()\\n\\n    async with session_scope() as session:\\n        rows = (await session.exec(select(Flow).where(Flow.user_id == user_id))).all()\\n        assert len(rows) == 1\\n        assert rows[0].description == \\\"updated via id-match\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/authorization/test_flow_route_guards.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"099588c7f450b37161758f562c67b36a620b038fce1eee8d1c024ab9224ebd4a\",\"content\":\"\\\"\\\"\\\"Source-level tests that flow routes call ensure_flow_permission.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n_API_V1 = Path(__file__).resolve().parents[4] / \\\"base\\\" / \\\"langflow\\\" / \\\"api\\\" / \\\"v1\\\"\\n_FLOWS_FILE = _API_V1 / \\\"flows.py\\\"\\n_CHAT_FILE = _API_V1 / \\\"chat.py\\\"\\n_ENDPOINTS_FILE = _API_V1 / \\\"endpoints.py\\\"\\n_PROJECTS_FILE = _API_V1 / \\\"projects.py\\\"\\n\\n\\ndef _parse_async_funcs(path: Path) -> dict[str, ast.AsyncFunctionDef]:\\n    \\\"\\\"\\\"Return the AST of every async function in *path* keyed by function name.\\\"\\\"\\\"\\n    tree = ast.parse(path.read_text())\\n    return {node.name: node for node in ast.walk(tree) if isinstance(node, ast.AsyncFunctionDef)}\\n\\n\\ndef _parse_flow_routes() -> dict[str, ast.AsyncFunctionDef]:\\n    \\\"\\\"\\\"Return the AST of every async route handler in flows.py keyed by function name.\\\"\\\"\\\"\\n    return _parse_async_funcs(_FLOWS_FILE)\\n\\n\\ndef _ensure_flow_permission_calls(func: ast.AsyncFunctionDef) -> list[ast.Call]:\\n    \\\"\\\"\\\"Return every ensure_flow_permission(...) call within the function body.\\\"\\\"\\\"\\n    calls: list[ast.Call] = []\\n    for node in ast.walk(func):\\n        if not isinstance(node, ast.Call):\\n            continue\\n        target = node.func\\n        is_match = (isinstance(target, ast.Name) and target.id == \\\"ensure_flow_permission\\\") or (\\n            isinstance(target, ast.Attribute) and target.attr == \\\"ensure_flow_permission\\\"\\n        )\\n        if is_match:\\n            calls.append(node)\\n    return calls\\n\\n\\ndef _uses_authorized_flow_dependency(func: ast.AsyncFunctionDef, alias: str) -> bool:\\n    \\\"\\\"\\\"Return True if *func* declares an authorized-flow dependency alias in its signature.\\\"\\\"\\\"\\n    for arg in func.args.args + func.args.kwonlyargs:\\n        if arg.annotation is None:\\n            continue\\n        ann = ast.unparse(arg.annotation)\\n        if alias in ann:\\n            return True\\n    for node in ast.walk(func):\\n        if isinstance(node, ast.AnnAssign) and node.annotation is not None and alias in ast.unparse(node.annotation):\\n            return True\\n    return False\\n\\n\\ndef _action_arg(call: ast.Call) -> str | None:\\n    \\\"\\\"\\\"Extract the action argument (positional[1]) as the dotted name like 'FlowAction.READ'.\\\"\\\"\\\"\\n    if len(call.args) < 2:\\n        return None\\n    arg = call.args[1]\\n    if isinstance(arg, ast.Attribute) and isinstance(arg.value, ast.Name):\\n        return f\\\"{arg.value.id}.{arg.attr}\\\"\\n    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):\\n        return arg.value\\n    return None\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef routes() -> dict[str, ast.AsyncFunctionDef]:\\n    return _parse_flow_routes()\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"func_name\\\", \\\"expected_action\\\"),\\n    [\\n        (\\\"create_flow\\\", \\\"FlowAction.CREATE\\\"),\\n        (\\\"read_flow\\\", \\\"FlowAction.READ\\\"),\\n        (\\\"update_flow\\\", \\\"FlowAction.WRITE\\\"),\\n        (\\\"delete_flow\\\", \\\"FlowAction.DELETE\\\"),\\n        (\\\"create_flows\\\", \\\"FlowAction.CREATE\\\"),\\n        (\\\"upload_file\\\", \\\"FlowAction.CREATE\\\"),\\n    ],\\n)\\ndef test_single_guard_route_uses_enum_action(routes, func_name, expected_action):\\n    \\\"\\\"\\\"Single-call guard routes call ensure_flow_permission once with the right FlowAction.\\\"\\\"\\\"\\n    func = routes[func_name]\\n    calls = _ensure_flow_permission_calls(func)\\n    if calls:\\n        actions = {_action_arg(c) for c in calls}\\n        assert expected_action in actions, f\\\"{func_name} actions={actions}, expected {expected_action}\\\"\\n        return\\n\\n    # Routes migrated to FastAPI dependencies declare protection in the signature.\\n    alias_by_action = {\\n        \\\"FlowAction.CREATE\\\": \\\"RequireFlowCreate\\\",\\n        \\\"FlowAction.READ\\\": \\\"AuthorizedReadFlow\\\",\\n        \\\"FlowAction.WRITE\\\": \\\"AuthorizedWriteFlow\\\",\\n        \\\"FlowAction.DELETE\\\": \\\"AuthorizedDeleteFlow\\\",\\n    }\\n    alias = alias_by_action.get(expected_action)\\n    assert alias is not None\\n    assert _uses_authorized_flow_dependency(func, alias), (\\n        f\\\"{func_name} has no ensure_flow_permission call or {alias} dependency\\\"\\n    )\\n\\n\\ndef test_upsert_flow_guards_both_create_and_write(routes):\\n    \\\"\\\"\\\"upsert_flow has two guard branches \u2014 WRITE for existing flows, CREATE for new ones.\\\"\\\"\\\"\\n    func = routes[\\\"upsert_flow\\\"]\\n    actions = {_action_arg(c) for c in _ensure_flow_permission_calls(func)}\\n    assert \\\"FlowAction.WRITE\\\" in actions\\n    assert \\\"FlowAction.CREATE\\\" in actions\\n\\n\\ndef test_delete_multiple_flows_guards_each_flow(routes):\\n    \\\"\\\"\\\"Bulk delete iterates and calls ensure_flow_permission per loaded flow.\\\"\\\"\\\"\\n    func = routes[\\\"delete_multiple_flows\\\"]\\n    actions = {_action_arg(c) for c in _ensure_flow_permission_calls(func)}\\n    assert actions == {\\\"FlowAction.DELETE\\\"}\\n\\n\\ndef test_download_multiple_file_guards_each_flow(routes):\\n    \\\"\\\"\\\"Bulk download iterates and calls ensure_flow_permission per loaded flow.\\\"\\\"\\\"\\n    func = routes[\\\"download_multiple_file\\\"]\\n    actions = {_action_arg(c) for c in _ensure_flow_permission_calls(func)}\\n    assert actions == {\\\"FlowAction.READ\\\"}\\n\\n\\ndef _kwarg_source(call: ast.Call, kw_name: str) -> str | None:\\n    \\\"\\\"\\\"Return the unparsed source of a keyword arg, or None if absent.\\\"\\\"\\\"\\n    for kw in call.keywords:\\n        if kw.arg == kw_name:\\n            return ast.unparse(kw.value)\\n    return None\\n\\n\\ndef _is_inside_for_loop_over(func: ast.AsyncFunctionDef, call: ast.Call, iter_attr: str) -> bool:\\n    \\\"\\\"\\\"Return True if *call* is inside a `for ... in <something>.<iter_attr>` loop in *func*.\\\"\\\"\\\"\\n    for node in ast.walk(func):\\n        if not isinstance(node, ast.For):\\n            continue\\n        iter_src = ast.unparse(node.iter)\\n        if not iter_src.endswith(f\\\".{iter_attr}\\\"):\\n            continue\\n        for sub in ast.walk(node):\\n            if sub is call:\\n                return True\\n    return False\\n\\n\\ndef test_create_flows_guards_each_flow_with_its_destination(routes):\\n    \\\"\\\"\\\"POST /batch/ must call ensure_flow_permission per flow with that flow's own scope.\\n\\n    A caller-supplied batch can target multiple workspace_id/folder_id values, so a\\n    single coarse check at the route boundary would let unauthorized destinations slip\\n    through. Each call must pass ``workspace_id=flow.workspace_id`` and\\n    ``folder_id=flow.folder_id`` and live inside an iteration over ``flow_list.flows``.\\n    \\\"\\\"\\\"\\n    func = routes[\\\"create_flows\\\"]\\n    calls = _ensure_flow_permission_calls(func)\\n    assert calls, \\\"create_flows lost its ensure_flow_permission call\\\"\\n    assert {_action_arg(c) for c in calls} == {\\\"FlowAction.CREATE\\\"}\\n    scoped_calls = [\\n        c\\n        for c in calls\\n        if _kwarg_source(c, \\\"workspace_id\\\") == \\\"flow.workspace_id\\\"\\n        and _kwarg_source(c, \\\"folder_id\\\") == \\\"flow.folder_id\\\"\\n        and _is_inside_for_loop_over(func, c, \\\"flows\\\")\\n    ]\\n    assert scoped_calls, (\\n        \\\"create_flows must call ensure_flow_permission inside a per-flow loop with flow.workspace_id and flow.folder_id\\\"\\n    )\\n\\n\\ndef test_upload_file_guards_each_flow_with_effective_destination(routes):\\n    \\\"\\\"\\\"POST /upload/ adds a per-flow check after parsing.\\n\\n    The query ``folder_id`` overrides each flow's folder_id while preserving\\n    each flow's workspace_id, so the per-flow check must use\\n    ``workspace_id=flow.workspace_id`` inside a loop over ``flow_list.flows``.\\n    \\\"\\\"\\\"\\n    func = routes[\\\"upload_file\\\"]\\n    calls = _ensure_flow_permission_calls(func)\\n    assert calls, \\\"upload_file lost its ensure_flow_permission call\\\"\\n    assert \\\"FlowAction.CREATE\\\" in {_action_arg(c) for c in calls}\\n    scoped_calls = [\\n        c\\n        for c in calls\\n        if _kwarg_source(c, \\\"workspace_id\\\") == \\\"flow.workspace_id\\\" and _is_inside_for_loop_over(func, c, \\\"flows\\\")\\n    ]\\n    assert scoped_calls, \\\"upload_file must call ensure_flow_permission inside a per-flow loop with flow.workspace_id\\\"\\n\\n\\ndef _has_destination_check(\\n    func: ast.AsyncFunctionDef,\\n    *,\\n    target_workspace_kw: str,\\n    target_folder_kw: str,\\n) -> bool:\\n    \\\"\\\"\\\"Return True if *func* has a WRITE ensure_flow_permission call with the destination kwargs.\\\"\\\"\\\"\\n    for call in _ensure_flow_permission_calls(func):\\n        if _action_arg(call) != \\\"FlowAction.WRITE\\\":\\n            continue\\n        ws = _kwarg_source(call, \\\"workspace_id\\\")\\n        fld = _kwarg_source(call, \\\"folder_id\\\")\\n        if ws == target_workspace_kw and fld == target_folder_kw:\\n            return True\\n    return False\\n\\n\\ndef test_update_flow_authorizes_destination_on_move(routes):\\n    \\\"\\\"\\\"PATCH /flows/{flow_id} must authorize the destination on workspace/folder change.\\n\\n    Without this, a caller could write to a flow in scope A and move it into\\n    scope B even when they lack permission to write at B (e.g., share-based\\n    access in Phase 3 or workspace-scoped roles in plugin).\\n    \\\"\\\"\\\"\\n    func = routes[\\\"update_flow\\\"]\\n    assert _has_destination_check(\\n        func,\\n        target_workspace_kw=\\\"target_workspace_id\\\",\\n        target_folder_kw=\\\"target_folder_id\\\",\\n    ), \\\"update_flow must authorize WRITE at target_workspace_id/target_folder_id when moving\\\"\\n\\n\\ndef test_upsert_flow_update_branch_authorizes_destination_on_move(routes):\\n    \\\"\\\"\\\"PUT /flows/{flow_id} (update branch) must authorize the destination on move.\\\"\\\"\\\"\\n    func = routes[\\\"upsert_flow\\\"]\\n    assert _has_destination_check(\\n        func,\\n        target_workspace_kw=\\\"target_workspace_id\\\",\\n        target_folder_kw=\\\"target_folder_id\\\",\\n    ), \\\"upsert_flow must authorize WRITE at target_workspace_id/target_folder_id when moving\\\"\\n\\n\\ndef test_upsert_flow_reauthorizes_fresh_source_and_destination(routes):\\n    \\\"\\\"\\\"Every PUT retry must re-check the freshly loaded source and destination.\\\"\\\"\\\"\\n    func = routes[\\\"upsert_flow\\\"]\\n    write_calls = [call for call in _ensure_flow_permission_calls(func) if _action_arg(call) == \\\"FlowAction.WRITE\\\"]\\n    assert any(\\n        _kwarg_source(call, \\\"workspace_id\\\") == \\\"existing_flow_for_attempt.workspace_id\\\"\\n        and _kwarg_source(call, \\\"folder_id\\\") == \\\"existing_flow_for_attempt.folder_id\\\"\\n        for call in write_calls\\n    ), \\\"upsert_flow retry must re-authorize the freshly loaded source scope\\\"\\n    assert _has_destination_check(\\n        func,\\n        target_workspace_kw=\\\"attempt_target_workspace_id\\\",\\n        target_folder_kw=\\\"attempt_target_folder_id\\\",\\n    ), \\\"upsert_flow retry must re-authorize its freshly resolved destination scope\\\"\\n\\n\\ndef test_no_bare_string_actions_remain(routes):\\n    \\\"\\\"\\\"No flow-route guard should use a bare string action \u2014 the enum is now canonical.\\\"\\\"\\\"\\n    offenders: list[str] = []\\n    for name, func in routes.items():\\n        for call in _ensure_flow_permission_calls(func):\\n            arg = _action_arg(call)\\n            if arg is not None and not arg.startswith(\\\"FlowAction.\\\"):\\n                offenders.append(f\\\"{name}:{arg}\\\")\\n    assert offenders == [], f\\\"bare-string actions found: {offenders}\\\"\\n\\n\\ndef test_read_public_flow_remains_unguarded(routes):\\n    \\\"\\\"\\\"The /public_flow/{id} endpoint must not call ensure_flow_permission \u2014 public means public.\\\"\\\"\\\"\\n    func = routes[\\\"read_public_flow\\\"]\\n    assert _ensure_flow_permission_calls(func) == []\\n\\n\\ndef test_get_note_translations_is_owner_scoped_and_guarded(routes):\\n    \\\"\\\"\\\"`GET /flows/{flow_id}/note_translations` must authorize READ via dependency or inline guard.\\\"\\\"\\\"\\n    func = routes[\\\"get_note_translations\\\"]\\n    calls = _ensure_flow_permission_calls(func)\\n    if calls:\\n        actions = {_action_arg(c) for c in calls}\\n        assert \\\"FlowAction.READ\\\" in actions, f\\\"expected FlowAction.READ, got {actions}\\\"\\n        read_flow_calls = [\\n            node\\n            for node in ast.walk(func)\\n            if isinstance(node, ast.Call)\\n            and (\\n                (isinstance(node.func, ast.Name) and node.func.id == \\\"_read_flow\\\")\\n                or (isinstance(node.func, ast.Attribute) and node.func.attr == \\\"_read_flow\\\")\\n            )\\n        ]\\n        assert read_flow_calls, \\\"get_note_translations must fetch the flow via _read_flow (owner-scoped)\\\"\\n        return\\n\\n    assert any(_uses_authorized_flow_dependency(func, alias) for alias in (\\\"AuthorizedReadFlow\\\",)), (\\n        \\\"get_note_translations must declare an authorized read dependency or call ensure_flow_permission\\\"\\n    )\\n\\n\\ndef test_read_flows_list_uses_filter_visible_resources(routes):\\n    \\\"\\\"\\\"GET /flows/ applies filter_visible_resources on BOTH the get_all and paginated paths.\\n\\n    The list helper drops items the user can't read. In OSS pass-through it\\n    returns the input unchanged; the authorization plugin uses batch_enforce to\\n    honor role + share grants. Per-item ensure_flow_permission is intentionally\\n    NOT used here \u2014 filtering is the right primitive for list endpoints.\\n\\n    Asserting **two** filter_visible_resources calls catches the earlier gap\\n    where only the get_all branch was filtered and the paginated branch\\n    (``get_all=False``) returned the raw ``apaginate`` result unfiltered.\\n    \\\"\\\"\\\"\\n    func = routes[\\\"read_flows\\\"]\\n    # No per-item ensure_flow_permission (would 403 on the first unauthorized item).\\n    assert _ensure_flow_permission_calls(func) == []\\n\\n    filter_calls = [\\n        node\\n        for node in ast.walk(func)\\n        if isinstance(node, ast.Call)\\n        and (\\n            (isinstance(node.func, ast.Name) and node.func.id == \\\"filter_visible_resources\\\")\\n            or (isinstance(node.func, ast.Attribute) and node.func.attr == \\\"filter_visible_resources\\\")\\n        )\\n    ]\\n    assert len(filter_calls) == 2, (\\n        f\\\"expected two filter_visible_resources calls (get_all + paginated branches), got {len(filter_calls)}\\\"\\n    )\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# Phase B: execute-action guards on build/run/webhook surfaces\\n# ----------------------------------------------------------------------------- #\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"module_path\\\", \\\"func_name\\\"),\\n    [\\n        (_CHAT_FILE, \\\"build_flow\\\"),\\n        # Deprecated but still routed \u2014 guarded with EXECUTE just like the\\n        # supported build_flow. ``build_graph_from_db`` does a raw\\n        # ``session.get(Flow, flow_id)`` with no owner filter, so the route\\n        # handler must enforce ownership itself.\\n        (_CHAT_FILE, \\\"retrieve_vertices_order\\\"),\\n        (_CHAT_FILE, \\\"build_vertex\\\"),\\n        (_ENDPOINTS_FILE, \\\"simplified_run_flow\\\"),\\n        (_ENDPOINTS_FILE, \\\"simplified_run_flow_session\\\"),\\n        (_ENDPOINTS_FILE, \\\"webhook_run_flow\\\"),\\n        (_ENDPOINTS_FILE, \\\"experimental_run_flow\\\"),\\n    ],\\n)\\ndef test_execute_surfaces_guard_with_flow_execute(module_path, func_name):\\n    \\\"\\\"\\\"build/run/webhook handlers must call ensure_flow_permission(FlowAction.EXECUTE).\\\"\\\"\\\"\\n    funcs = _parse_async_funcs(module_path)\\n    assert func_name in funcs, f\\\"{func_name} missing from {module_path.name}\\\"\\n    calls = _ensure_flow_permission_calls(funcs[func_name])\\n    assert calls, f\\\"{func_name} has no ensure_flow_permission call\\\"\\n    actions = {_action_arg(c) for c in calls}\\n    assert \\\"FlowAction.EXECUTE\\\" in actions, f\\\"{func_name} actions={actions}, expected FlowAction.EXECUTE\\\"\\n\\n\\ndef test_check_flow_user_permission_is_gone():\\n    \\\"\\\"\\\"The standalone owner-only ``check_flow_user_permission`` helper has been removed.\\n\\n    It duplicated the work that ``ensure_flow_permission`` now does at the\\n    route boundary, AND it would have rejected legitimate plugin execute\\n    grants on shared flows (a real bug under policy engine enforcement). The new\\n    contract is \\\"every ``_run_flow_internal`` caller authorizes EXECUTE first\\\";\\n    leaving a downstream owner-only check would silently re-introduce the\\n    regression on any future route that wires up the internal helper without\\n    calling ensure_flow_permission upstream.\\n    \\\"\\\"\\\"\\n    funcs = _parse_async_funcs(_ENDPOINTS_FILE)\\n    assert \\\"check_flow_user_permission\\\" not in funcs, (\\n        \\\"check_flow_user_permission should be removed; the route-level \\\"\\n        \\\"ensure_flow_permission(EXECUTE) is the only authorization gate now\\\"\\n    )\\n\\n\\n# ----------------------------------------------------------------------------- #\\n# Phase B: project route guards\\n# ----------------------------------------------------------------------------- #\\n\\n\\ndef _ensure_project_permission_calls(func: ast.AsyncFunctionDef) -> list[ast.Call]:\\n    \\\"\\\"\\\"Return every ensure_project_permission(...) call within the function body.\\\"\\\"\\\"\\n    calls: list[ast.Call] = []\\n    for node in ast.walk(func):\\n        if not isinstance(node, ast.Call):\\n            continue\\n        target = node.func\\n        is_match = (isinstance(target, ast.Name) and target.id == \\\"ensure_project_permission\\\") or (\\n            isinstance(target, ast.Attribute) and target.attr == \\\"ensure_project_permission\\\"\\n        )\\n        if is_match:\\n            calls.append(node)\\n    return calls\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"func_name\\\", \\\"expected_action\\\"),\\n    [\\n        (\\\"create_project\\\", \\\"ProjectAction.CREATE\\\"),\\n        (\\\"read_project\\\", \\\"ProjectAction.READ\\\"),\\n        (\\\"update_project\\\", \\\"ProjectAction.WRITE\\\"),\\n        (\\\"delete_project\\\", \\\"ProjectAction.DELETE\\\"),\\n        (\\\"download_file\\\", \\\"ProjectAction.READ\\\"),\\n        (\\\"upload_file\\\", \\\"ProjectAction.CREATE\\\"),\\n    ],\\n)\\ndef test_project_routes_guarded(func_name, expected_action):\\n    \\\"\\\"\\\"Each project CRUD handler calls ensure_project_permission with the right ProjectAction.\\\"\\\"\\\"\\n    funcs = _parse_async_funcs(_PROJECTS_FILE)\\n    assert func_name in funcs, f\\\"{func_name} missing from projects.py\\\"\\n    calls = _ensure_project_permission_calls(funcs[func_name])\\n    assert calls, f\\\"{func_name} has no ensure_project_permission call\\\"\\n    actions = {_action_arg(c) for c in calls}\\n    assert expected_action in actions, f\\\"{func_name} actions={actions}, expected {expected_action}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/database/models/flow_version/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/database/models/flow_version/test_in_memory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"36e6c1a1efcdccd745bb27d10114b9b5f28fd28ad3bf804b864846b16e39ab76\",\"content\":\"\\\"\\\"\\\"In-memory SQLite integration tests for orphan attachment cleanup.\\n\\nVerifies that orphan detection and pruning works against a real database\\nwith foreign keys enabled \u2014 guards, CRUD counts, and version pruning all\\ncorrectly distinguish live vs. orphaned attachment rows.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.api.utils.flow_utils import cascade_delete_flow\\nfrom langflow.services.database.models.deployment.crud import list_deployments_page\\nfrom langflow.services.database.models.deployment.guards import (\\n    check_flow_has_deployed_versions,\\n)\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment_provider_account.model import (\\n    DeploymentProviderAccount,\\n    DeploymentProviderKey,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version.crud import (\\n    create_flow_version_entry,\\n    delete_flow_version_entry,\\n    get_flow_versions_with_provider_status,\\n    has_deployment_attachments,\\n)\\nfrom langflow.services.database.models.flow_version.exceptions import FlowVersionDeployedError, FlowVersionNotFoundError\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n    count_attachments_by_deployment_ids,\\n    count_deployment_attachments,\\n    delete_orphan_attachments_for_flow_ids,\\n    delete_orphan_attachments_for_project,\\n)\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import (\\n    FlowVersionDeploymentAttachment,\\n)\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.message.model import MessageTable\\nfrom langflow.services.database.models.traces.model import SpanTable, TraceTable\\nfrom langflow.services.database.models.transactions.model import TransactionTable\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.database.models.vertex_builds.model import VertexBuildTable\\nfrom sqlalchemy import event, text\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlalchemy.pool import StaticPool\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n_TEST_PASSWORD = \\\"hashed\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fixtures\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture(name=\\\"db_engine\\\")\\ndef db_engine_fixture():\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite://\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n\\n    @event.listens_for(engine.sync_engine, \\\"connect\\\")\\n    def _enable_fk(dbapi_connection, connection_record):  # noqa: ARG001\\n        cursor = dbapi_connection.cursor()\\n        cursor.execute(\\\"PRAGMA foreign_keys=ON\\\")\\n        cursor.close()\\n\\n    return engine\\n\\n\\n@pytest.fixture(name=\\\"db\\\")\\nasync def db_fixture(db_engine):\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    async with AsyncSession(db_engine, expire_on_commit=False) as session:\\n        yield session\\n    async with db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await db_engine.dispose()\\n\\n\\n@pytest.fixture\\nasync def user(db: AsyncSession) -> User:\\n    u = User(username=\\\"testuser\\\", password=_TEST_PASSWORD, is_active=True)\\n    db.add(u)\\n    await db.commit()\\n    await db.refresh(u)\\n    return u\\n\\n\\n@pytest.fixture\\nasync def folder(db: AsyncSession, user: User) -> Folder:\\n    f = Folder(name=\\\"test-project\\\", user_id=user.id)\\n    db.add(f)\\n    await db.commit()\\n    await db.refresh(f)\\n    return f\\n\\n\\n@pytest.fixture\\nasync def flow(db: AsyncSession, user: User, folder: Folder) -> Flow:\\n    f = Flow(name=\\\"test-flow\\\", user_id=user.id, folder_id=folder.id)\\n    db.add(f)\\n    await db.commit()\\n    await db.refresh(f)\\n    return f\\n\\n\\n@pytest.fixture\\nasync def provider_account(db: AsyncSession, user: User) -> DeploymentProviderAccount:\\n    acct = DeploymentProviderAccount(\\n        user_id=user.id,\\n        provider_tenant_id=\\\"tenant-1\\\",\\n        provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n        name=\\\"test-provider\\\",\\n        provider_url=\\\"https://provider.example.com\\\",\\n        api_key=\\\"encrypted-value\\\",  # pragma: allowlist secret\\n    )\\n    db.add(acct)\\n    await db.commit()\\n    await db.refresh(acct)\\n    return acct\\n\\n\\n@pytest.fixture\\nasync def deployment(\\n    db: AsyncSession,\\n    user: User,\\n    folder: Folder,\\n    provider_account: DeploymentProviderAccount,\\n) -> Deployment:\\n    d = Deployment(\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account.id,\\n        resource_key=\\\"rk-1\\\",\\n        display_name=\\\"my-deployment\\\",\\n    )\\n    db.add(d)\\n    await db.commit()\\n    await db.refresh(d)\\n    return d\\n\\n\\nasync def _create_version(db: AsyncSession, flow: Flow, user: User, n: int = 1) -> FlowVersion:\\n    fv = FlowVersion(flow_id=flow.id, user_id=user.id, version_number=n, data={\\\"nodes\\\": []})\\n    db.add(fv)\\n    await db.commit()\\n    await db.refresh(fv)\\n    return fv\\n\\n\\nasync def _attach(\\n    db: AsyncSession,\\n    user: User,\\n    version: FlowVersion,\\n    deployment: Deployment,\\n    snapshot_id: str = \\\"snap-1\\\",\\n) -> FlowVersionDeploymentAttachment:\\n    att = FlowVersionDeploymentAttachment(\\n        user_id=user.id,\\n        flow_version_id=version.id,\\n        deployment_id=deployment.id,\\n        provider_snapshot_id=snapshot_id,\\n    )\\n    db.add(att)\\n    await db.commit()\\n    await db.refresh(att)\\n    return att\\n\\n\\nasync def _make_orphan_attachment(\\n    db: AsyncSession,\\n    user: User,\\n    version: FlowVersion,\\n    snapshot_id: str = \\\"orphan-snap\\\",\\n) -> FlowVersionDeploymentAttachment:\\n    \\\"\\\"\\\"Insert an attachment row pointing to a non-existent deployment.\\n\\n    FK enforcement is temporarily disabled so the row can be written, then\\n    re-enabled to simulate legacy data from pre-FK-enforcement environments.\\n    \\\"\\\"\\\"\\n    fake_deployment_id = uuid4()\\n    await db.exec(text(\\\"PRAGMA foreign_keys=OFF\\\"))\\n    att = FlowVersionDeploymentAttachment(\\n        user_id=user.id,\\n        flow_version_id=version.id,\\n        deployment_id=fake_deployment_id,\\n        provider_snapshot_id=snapshot_id,\\n    )\\n    db.add(att)\\n    await db.commit()\\n    await db.refresh(att)\\n    await db.exec(text(\\\"PRAGMA foreign_keys=ON\\\"))\\n    return att\\n\\n\\n# ===========================================================================\\n# Guard: check_flow_has_deployed_versions\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestGuardOrphanPruning:\\n    async def test_guard_allows_when_no_attachments(self, db: AsyncSession, flow: Flow, user: User):\\n        await _create_version(db, flow, user)\\n        await check_flow_has_deployed_versions(db, flow_id=flow.id)\\n\\n    async def test_guard_raises_for_live_attachment(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        from langflow.services.database.models.deployment.exceptions import DeploymentGuardError\\n\\n        version = await _create_version(db, flow, user)\\n        await _attach(db, user, version, deployment)\\n\\n        with pytest.raises(DeploymentGuardError):\\n            await check_flow_has_deployed_versions(db, flow_id=flow.id)\\n\\n    async def test_guard_prunes_orphan_and_allows_delete(self, db: AsyncSession, flow: Flow, user: User):\\n        version = await _create_version(db, flow, user)\\n        orphan = await _make_orphan_attachment(db, user, version)\\n\\n        await check_flow_has_deployed_versions(db, flow_id=flow.id)\\n\\n        stmt = select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == orphan.id)\\n        assert (await db.exec(stmt)).first() is None\\n\\n    async def test_guard_prunes_orphan_but_raises_when_live_also_exists(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        from langflow.services.database.models.deployment.exceptions import DeploymentGuardError\\n\\n        version = await _create_version(db, flow, user)\\n        await _attach(db, user, version, deployment)\\n        await _make_orphan_attachment(db, user, version, snapshot_id=\\\"orphan-2\\\")\\n\\n        with pytest.raises(DeploymentGuardError):\\n            await check_flow_has_deployed_versions(db, flow_id=flow.id)\\n\\n\\n# ===========================================================================\\n# delete_flow_version_entry\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestDeleteFlowVersionEntry:\\n    async def test_rejects_deployed_version(self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment):\\n        version = await _create_version(db, flow, user)\\n        await _attach(db, user, version, deployment)\\n\\n        with pytest.raises(FlowVersionDeployedError):\\n            await delete_flow_version_entry(db, version.id, user.id)\\n\\n        assert (await db.exec(select(FlowVersion.id).where(FlowVersion.id == version.id))).one() == version.id\\n\\n    async def test_rejects_another_users_version(self, db: AsyncSession, flow: Flow, user: User):\\n        version = await _create_version(db, flow, user)\\n\\n        with pytest.raises(FlowVersionNotFoundError):\\n            await delete_flow_version_entry(db, version.id, uuid4())\\n\\n        assert (await db.exec(select(FlowVersion.id).where(FlowVersion.id == version.id))).one() == version.id\\n\\n\\n# ===========================================================================\\n# cascade_delete_flow\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestCascadeDeleteFlow:\\n    async def test_reports_whether_flow_was_deleted(self, db: AsyncSession, flow: Flow):\\n        flow_id = flow.id\\n\\n        assert await cascade_delete_flow(db, flow_id) is True\\n        await db.commit()\\n        assert await cascade_delete_flow(db, flow_id) is False\\n\\n    async def test_deletes_related_rows_under_fk_enforcement(self, db: AsyncSession, flow: Flow, user: User):\\n        version = await _create_version(db, flow, user)\\n\\n        trace = TraceTable(name=\\\"trace-1\\\", flow_id=flow.id, session_id=\\\"session-1\\\")\\n        db.add(trace)\\n        await db.flush()\\n\\n        span = SpanTable(name=\\\"span-1\\\", trace_id=trace.id)\\n        message = MessageTable(\\n            sender=\\\"user\\\",\\n            sender_name=\\\"User\\\",\\n            session_id=\\\"session-1\\\",\\n            text=\\\"hello\\\",\\n            flow_id=flow.id,\\n        )\\n        transaction = TransactionTable(vertex_id=\\\"vertex-1\\\", status=\\\"ok\\\", flow_id=flow.id)\\n        vertex_build = VertexBuildTable(id=\\\"vertex-1\\\", valid=True, flow_id=flow.id)\\n        db.add_all([span, message, transaction, vertex_build])\\n        await db.commit()\\n\\n        await cascade_delete_flow(db, flow.id)\\n        await db.commit()\\n\\n        assert (await db.exec(select(Flow).where(Flow.id == flow.id))).first() is None\\n        assert (await db.exec(select(FlowVersion).where(FlowVersion.id == version.id))).first() is None\\n        assert (await db.exec(select(TraceTable).where(TraceTable.id == trace.id))).first() is None\\n        assert (await db.exec(select(SpanTable).where(SpanTable.id == span.id))).first() is None\\n        assert (await db.exec(select(MessageTable).where(MessageTable.flow_id == flow.id))).all() == []\\n        assert (await db.exec(select(TransactionTable).where(TransactionTable.flow_id == flow.id))).all() == []\\n        assert (await db.exec(select(VertexBuildTable).where(VertexBuildTable.flow_id == flow.id))).all() == []\\n\\n    async def test_deletes_flow_when_only_orphan_attachments_exist(self, db: AsyncSession, flow: Flow, user: User):\\n        version = await _create_version(db, flow, user)\\n        orphan = await _make_orphan_attachment(db, user, version, snapshot_id=\\\"orphan-only\\\")\\n\\n        await cascade_delete_flow(db, flow.id)\\n        await db.commit()\\n\\n        assert (await db.exec(select(Flow).where(Flow.id == flow.id))).first() is None\\n        assert (await db.exec(select(FlowVersion).where(FlowVersion.id == version.id))).first() is None\\n        assert (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == orphan.id)\\n            )\\n        ).first() is None\\n\\n\\n# ===========================================================================\\n# has_deployment_attachments\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestHasDeploymentAttachments:\\n    async def test_returns_true_for_live_attachment(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        version = await _create_version(db, flow, user)\\n        await _attach(db, user, version, deployment)\\n\\n        assert await has_deployment_attachments(db, version.id, user_id=user.id) is True\\n\\n    async def test_returns_false_and_prunes_orphan(self, db: AsyncSession, flow: Flow, user: User):\\n        version = await _create_version(db, flow, user)\\n        orphan = await _make_orphan_attachment(db, user, version)\\n\\n        assert await has_deployment_attachments(db, version.id, user_id=user.id) is False\\n\\n        stmt = select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == orphan.id)\\n        assert (await db.exec(stmt)).first() is None\\n\\n    async def test_returns_false_when_no_attachments(self, db: AsyncSession, flow: Flow, user: User):\\n        version = await _create_version(db, flow, user)\\n        assert await has_deployment_attachments(db, version.id, user_id=user.id) is False\\n\\n\\n# ===========================================================================\\n# count_* CRUD functions exclude orphans\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestCountFunctionsExcludeOrphans:\\n    async def test_count_by_deployment_ids_excludes_orphan_version(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        \\\"\\\"\\\"Attachment pointing to a deleted flow_version should not be counted.\\\"\\\"\\\"\\n        version = await _create_version(db, flow, user)\\n        await _attach(db, user, version, deployment)\\n\\n        counts = await count_attachments_by_deployment_ids(db, user_id=user.id, deployment_ids=[deployment.id])\\n        assert counts[deployment.id] == 1\\n\\n        # Delete the version (FK cascades delete the attachment in a real DB).\\n        # The count should drop to 0.\\n        await db.delete(version)\\n        await db.commit()\\n\\n        counts = await count_attachments_by_deployment_ids(db, user_id=user.id, deployment_ids=[deployment.id])\\n        assert counts[deployment.id] == 0\\n\\n    async def test_count_deployment_attachments_excludes_orphan_version(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        version = await _create_version(db, flow, user)\\n        await _attach(db, user, version, deployment)\\n\\n        total = await count_deployment_attachments(db, user_id=user.id, deployment_id=deployment.id)\\n        assert total == 1\\n\\n        await db.delete(version)\\n        await db.commit()\\n\\n        total = await count_deployment_attachments(db, user_id=user.id, deployment_id=deployment.id)\\n        assert total == 0\\n\\n\\n# ===========================================================================\\n# delete_orphan_attachments_for_flow_ids\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestDeleteOrphanAttachmentsForFlowIds:\\n    async def test_deletes_orphan_leaves_live(self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment):\\n        version = await _create_version(db, flow, user)\\n        live = await _attach(db, user, version, deployment)\\n        orphan = await _make_orphan_attachment(db, user, version, snapshot_id=\\\"orphan-snap\\\")\\n\\n        deleted = await delete_orphan_attachments_for_flow_ids(db, user_id=user.id, flow_ids=[flow.id])\\n        await db.commit()\\n\\n        assert deleted == 1\\n\\n        stmt = select(FlowVersionDeploymentAttachment.id)\\n        remaining = (await db.exec(stmt)).all()\\n        assert live.id in remaining\\n        assert orphan.id not in remaining\\n\\n    async def test_no_op_when_no_orphans(self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment):\\n        version = await _create_version(db, flow, user)\\n        await _attach(db, user, version, deployment)\\n\\n        deleted = await delete_orphan_attachments_for_flow_ids(db, user_id=user.id, flow_ids=[flow.id])\\n        assert deleted == 0\\n\\n    async def test_empty_flow_ids_returns_zero(self, db: AsyncSession, user: User):\\n        deleted = await delete_orphan_attachments_for_flow_ids(db, user_id=user.id, flow_ids=[])\\n        assert deleted == 0\\n\\n    async def test_scopes_deletion_by_user(self, db: AsyncSession, user: User, flow: Flow):\\n        version = await _create_version(db, flow, user)\\n        own_orphan = await _make_orphan_attachment(db, user, version, snapshot_id=\\\"self-orphan\\\")\\n\\n        other_user = User(username=\\\"other-user\\\", password=_TEST_PASSWORD, is_active=True)\\n        db.add(other_user)\\n        await db.commit()\\n        await db.refresh(other_user)\\n\\n        other_folder = Folder(name=\\\"other-user-project\\\", user_id=other_user.id)\\n        db.add(other_folder)\\n        await db.commit()\\n        await db.refresh(other_folder)\\n\\n        other_flow = Flow(name=\\\"other-user-flow\\\", user_id=other_user.id, folder_id=other_folder.id)\\n        db.add(other_flow)\\n        await db.commit()\\n        await db.refresh(other_flow)\\n\\n        other_version = await _create_version(db, other_flow, other_user)\\n        other_orphan = await _make_orphan_attachment(db, other_user, other_version, snapshot_id=\\\"other-orphan\\\")\\n\\n        deleted = await delete_orphan_attachments_for_flow_ids(db, user_id=user.id, flow_ids=[flow.id])\\n        await db.commit()\\n        assert deleted == 1\\n\\n        remaining_ids = (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment.id).where(\\n                    FlowVersionDeploymentAttachment.id.in_([own_orphan.id, other_orphan.id])\\n                )\\n            )\\n        ).all()\\n        assert own_orphan.id not in remaining_ids\\n        assert other_orphan.id in remaining_ids\\n\\n\\n# ===========================================================================\\n# delete_orphan_attachments_for_project\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestDeleteOrphanAttachmentsForProject:\\n    async def test_deletes_orphan_scoped_to_project(\\n        self, db: AsyncSession, flow: Flow, user: User, folder: Folder, deployment: Deployment\\n    ):\\n        version = await _create_version(db, flow, user)\\n        live = await _attach(db, user, version, deployment)\\n        orphan = await _make_orphan_attachment(db, user, version, snapshot_id=\\\"proj-orphan\\\")\\n\\n        deleted = await delete_orphan_attachments_for_project(db, user_id=user.id, project_id=folder.id)\\n        await db.commit()\\n\\n        assert deleted == 1\\n\\n        stmt = select(FlowVersionDeploymentAttachment.id)\\n        remaining = (await db.exec(stmt)).all()\\n        assert live.id in remaining\\n        assert orphan.id not in remaining\\n\\n    async def test_does_not_touch_other_projects(self, db: AsyncSession, flow: Flow, user: User, folder: Folder):  # noqa: ARG002\\n        version = await _create_version(db, flow, user)\\n        await _make_orphan_attachment(db, user, version)\\n\\n        other_folder = Folder(name=\\\"other-project\\\", user_id=user.id)\\n        db.add(other_folder)\\n        await db.commit()\\n        await db.refresh(other_folder)\\n\\n        deleted = await delete_orphan_attachments_for_project(db, user_id=user.id, project_id=other_folder.id)\\n        assert deleted == 0\\n\\n    async def test_project_cleanup_scopes_by_user(self, db: AsyncSession, user: User, folder: Folder, flow: Flow):\\n        own_version = await _create_version(db, flow, user)\\n        own_orphan = await _make_orphan_attachment(db, user, own_version, snapshot_id=\\\"own-project-orphan\\\")\\n\\n        other_user = User(username=\\\"project-other-user\\\", password=_TEST_PASSWORD, is_active=True)\\n        db.add(other_user)\\n        await db.commit()\\n        await db.refresh(other_user)\\n\\n        other_folder = Folder(name=\\\"project-other-folder\\\", user_id=other_user.id)\\n        db.add(other_folder)\\n        await db.commit()\\n        await db.refresh(other_folder)\\n\\n        other_flow = Flow(name=\\\"project-other-flow\\\", user_id=other_user.id, folder_id=other_folder.id)\\n        db.add(other_flow)\\n        await db.commit()\\n        await db.refresh(other_flow)\\n\\n        other_version = await _create_version(db, other_flow, other_user)\\n        other_orphan = await _make_orphan_attachment(db, other_user, other_version, snapshot_id=\\\"other-project-orphan\\\")\\n\\n        deleted = await delete_orphan_attachments_for_project(db, user_id=user.id, project_id=folder.id)\\n        await db.commit()\\n        assert deleted == 1\\n\\n        remaining_ids = (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment.id).where(\\n                    FlowVersionDeploymentAttachment.id.in_([own_orphan.id, other_orphan.id])\\n                )\\n            )\\n        ).all()\\n        assert own_orphan.id not in remaining_ids\\n        assert other_orphan.id in remaining_ids\\n\\n\\n# ===========================================================================\\n# Version pruning respects live deployments only\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestVersionPruningRespectsLiveDeployments:\\n    async def test_orphan_attachment_does_not_pin_version_during_pruning(\\n        self, db: AsyncSession, flow: Flow, user: User\\n    ):\\n        \\\"\\\"\\\"A version with only orphan attachments should be prunable.\\\"\\\"\\\"\\n        settings_mock = SimpleNamespace(settings=SimpleNamespace(max_flow_version_entries_per_flow=1))\\n        with patch(\\n            \\\"langflow.services.database.models.flow_version.crud.get_settings_service\\\",\\n            return_value=settings_mock,\\n        ):\\n            v1 = await _create_version(db, flow, user, n=1)\\n            await _make_orphan_attachment(db, user, v1, snapshot_id=\\\"pin-orphan\\\")\\n\\n            await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n            await db.commit()\\n\\n        stmt = select(FlowVersion).where(FlowVersion.flow_id == flow.id)\\n        remaining = (await db.exec(stmt)).all()\\n        assert len(remaining) == 1, \\\"Orphan attachment should not have pinned v1\\\"\\n        assert remaining[0].version_number == 2\\n\\n    async def test_live_attachment_pins_version_during_pruning(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        \\\"\\\"\\\"A version with a live attachment must survive pruning.\\\"\\\"\\\"\\n        settings_mock = SimpleNamespace(settings=SimpleNamespace(max_flow_version_entries_per_flow=1))\\n        with patch(\\n            \\\"langflow.services.database.models.flow_version.crud.get_settings_service\\\",\\n            return_value=settings_mock,\\n        ):\\n            v1 = await _create_version(db, flow, user, n=1)\\n            await _attach(db, user, v1, deployment)\\n\\n            await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n            await db.commit()\\n\\n        stmt = select(FlowVersion).where(FlowVersion.flow_id == flow.id).order_by(FlowVersion.version_number)\\n        remaining = (await db.exec(stmt)).all()\\n        assert len(remaining) == 2, \\\"Live attachment should have pinned v1\\\"\\n        assert remaining[0].version_number == 1\\n        assert remaining[1].version_number == 2\\n\\n\\n# ===========================================================================\\n# Pruning cleans attachment children (no doubly-orphan attachments form)\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestVersionPruningCleansOrphanAttachments:\\n    \\\"\\\"\\\"Source-fix coverage for prune cleanup.\\n\\n    attachment children for the versions it removes, otherwise stale\\n    orphan-deployment attachments would survive as doubly-orphaned rows\\n    (deployment AND flow_version both missing). No existing cleanup helper\\n    catches that shape, so the only place to plug it is at the formation site.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def _patch_max_entries(self, request):\\n        \\\"\\\"\\\"Allow each test to set max_flow_version_entries_per_flow via marker.\\\"\\\"\\\"\\n        max_entries = getattr(request, \\\"param\\\", 1)\\n        with patch(\\n            \\\"langflow.services.database.models.flow_version.crud.get_settings_service\\\",\\n            return_value=SimpleNamespace(settings=SimpleNamespace(max_flow_version_entries_per_flow=max_entries)),\\n        ):\\n            yield\\n\\n    async def test_prune_deletes_orphan_attachment_alongside_version(self, db: AsyncSession, flow: Flow, user: User):\\n        \\\"\\\"\\\"A version that gets pruned must also have its orphan attachment removed.\\\"\\\"\\\"\\n        v1 = await _create_version(db, flow, user, n=1)\\n        orphan = await _make_orphan_attachment(db, user, v1, snapshot_id=\\\"orphan-pruned\\\")\\n\\n        await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n        await db.commit()\\n\\n        # v1 was pruned (only v2 remains)\\n        versions = (await db.exec(select(FlowVersion).where(FlowVersion.flow_id == flow.id))).all()\\n        assert len(versions) == 1\\n        assert versions[0].version_number == 2\\n\\n        # Crucially: the orphan attachment is gone too \u2014 no doubly-orphan formed.\\n        remaining_attachment = (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == orphan.id)\\n            )\\n        ).first()\\n        assert remaining_attachment is None\\n\\n    async def test_prune_with_no_attachments_is_unchanged(self, db: AsyncSession, flow: Flow, user: User):\\n        \\\"\\\"\\\"The fast-path (no attachments to clean) must still prune the version.\\\"\\\"\\\"\\n        await _create_version(db, flow, user, n=1)\\n\\n        await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n        await db.commit()\\n\\n        versions = (await db.exec(select(FlowVersion).where(FlowVersion.flow_id == flow.id))).all()\\n        assert len(versions) == 1\\n        assert versions[0].version_number == 2\\n\\n    async def test_prune_preserves_live_attachment_and_its_version(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        \\\"\\\"\\\"A live-deployed version must not be pruned, and its attachment must stay.\\\"\\\"\\\"\\n        v1 = await _create_version(db, flow, user, n=1)\\n        live = await _attach(db, user, v1, deployment, snapshot_id=\\\"snap-live\\\")\\n\\n        await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n        await db.commit()\\n\\n        versions = (\\n            await db.exec(\\n                select(FlowVersion).where(FlowVersion.flow_id == flow.id).order_by(FlowVersion.version_number)\\n            )\\n        ).all()\\n        assert [v.version_number for v in versions] == [1, 2]\\n\\n        live_remaining = (\\n            await db.exec(select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == live.id))\\n        ).first()\\n        assert live_remaining is not None\\n\\n    async def test_prune_mixed_attachment_states_in_single_pass(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment\\n    ):\\n        \\\"\\\"\\\"Versions with no/orphan attachments are pruned together; live ones survive.\\n\\n        max_entries=1 so we keep only the newest non-deployed version (plus all\\n        deployed ones). Setup builds 4 versions with mixed attachment states,\\n        then create_flow_version_entry adds v5 and prunes.\\n        \\\"\\\"\\\"\\n        v1 = await _create_version(db, flow, user, n=1)  # no attachment\\n        v2 = await _create_version(db, flow, user, n=2)  # orphan attachment\\n        v3 = await _create_version(db, flow, user, n=3)  # live attachment\\n        v4 = await _create_version(db, flow, user, n=4)  # no attachment\\n\\n        live = await _attach(db, user, v3, deployment, snapshot_id=\\\"mixed-live\\\")\\n        orphan = await _make_orphan_attachment(db, user, v2, snapshot_id=\\\"mixed-orphan\\\")\\n\\n        await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n        await db.commit()\\n\\n        # Only v3 (live-deployed) and v5 (newest, just created) survive \u2014 v1,\\n        # v2, v4 are pruned.\\n        remaining_version_numbers = sorted(\\n            v.version_number for v in (await db.exec(select(FlowVersion).where(FlowVersion.flow_id == flow.id))).all()\\n        )\\n        assert remaining_version_numbers == [3, 5]\\n\\n        # The live attachment stays because v3 stayed.\\n        assert (\\n            await db.exec(select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == live.id))\\n        ).first() is not None\\n\\n        # The orphan attachment was reaped along with v2 \u2014 no doubly-orphan formed.\\n        assert (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == orphan.id)\\n            )\\n        ).first() is None\\n\\n        # And there are no doubly-orphan rows lurking anywhere.\\n        doubly_orphans = (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment.id)\\n                .outerjoin(\\n                    FlowVersion,\\n                    FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id,\\n                )\\n                .where(FlowVersion.id.is_(None))\\n            )\\n        ).all()\\n        assert doubly_orphans == []\\n\\n        # Touch v4 reference so the linter doesn't complain about unused vars.\\n        assert v1.version_number == 1\\n        assert v4.version_number == 4\\n\\n    async def test_prune_does_not_touch_attachments_for_other_flows(\\n        self, db: AsyncSession, flow: Flow, folder: Folder, user: User, deployment: Deployment\\n    ):\\n        \\\"\\\"\\\"Pruning flow A must not delete attachments belonging to flow B.\\\"\\\"\\\"\\n        v1_a = await _create_version(db, flow, user, n=1)\\n        await _make_orphan_attachment(db, user, v1_a, snapshot_id=\\\"flow-a-orphan\\\")\\n\\n        other_flow = Flow(name=\\\"other-flow\\\", user_id=user.id, folder_id=folder.id)\\n        db.add(other_flow)\\n        await db.commit()\\n        await db.refresh(other_flow)\\n\\n        v1_b = await _create_version(db, other_flow, user, n=1)\\n        live_b = await _attach(db, user, v1_b, deployment, snapshot_id=\\\"flow-b-live\\\")\\n        orphan_b = await _make_orphan_attachment(db, user, v1_b, snapshot_id=\\\"flow-b-orphan\\\")\\n\\n        await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n        await db.commit()\\n\\n        # Flow B's attachments are untouched.\\n        assert (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == live_b.id)\\n            )\\n        ).first() is not None\\n        assert (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == orphan_b.id)\\n            )\\n        ).first() is not None\\n\\n        # Flow B's version is untouched.\\n        assert (await db.exec(select(FlowVersion).where(FlowVersion.id == v1_b.id))).first() is not None\\n\\n    async def test_prune_does_not_touch_attachments_for_other_users(self, db: AsyncSession, flow: Flow, user: User):\\n        \\\"\\\"\\\"Pruning user A's flow must not delete user B's attachments.\\\"\\\"\\\"\\n        v1 = await _create_version(db, flow, user, n=1)\\n        await _make_orphan_attachment(db, user, v1, snapshot_id=\\\"user-a-orphan\\\")\\n\\n        other_user = User(username=\\\"prune-other-user\\\", password=_TEST_PASSWORD, is_active=True)\\n        db.add(other_user)\\n        await db.commit()\\n        await db.refresh(other_user)\\n\\n        other_folder = Folder(name=\\\"prune-other-folder\\\", user_id=other_user.id)\\n        db.add(other_folder)\\n        await db.commit()\\n        await db.refresh(other_folder)\\n\\n        other_flow = Flow(name=\\\"prune-other-flow\\\", user_id=other_user.id, folder_id=other_folder.id)\\n        db.add(other_flow)\\n        await db.commit()\\n        await db.refresh(other_flow)\\n\\n        other_v1 = await _create_version(db, other_flow, other_user, n=1)\\n        other_orphan = await _make_orphan_attachment(db, other_user, other_v1, snapshot_id=\\\"user-b-orphan\\\")\\n\\n        await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n        await db.commit()\\n\\n        # User B's row is untouched.\\n        assert (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment).where(FlowVersionDeploymentAttachment.id == other_orphan.id)\\n            )\\n        ).first() is not None\\n        assert (await db.exec(select(FlowVersion).where(FlowVersion.id == other_v1.id))).first() is not None\\n\\n    async def test_repeated_snapshots_never_accumulate_doubly_orphans(self, db: AsyncSession, flow: Flow, user: User):\\n        \\\"\\\"\\\"Stress test repeated snapshot cycles with a stale orphan attachment.\\n\\n        converge to zero doubly-orphan rows.\\n        \\\"\\\"\\\"\\n        v1 = await _create_version(db, flow, user, n=1)\\n        await _make_orphan_attachment(db, user, v1, snapshot_id=\\\"legacy-orphan\\\")\\n\\n        for _ in range(10):\\n            await create_flow_version_entry(db, flow.id, user.id, data={\\\"nodes\\\": []})\\n            await db.commit()\\n\\n        doubly_orphans = (\\n            await db.exec(\\n                select(FlowVersionDeploymentAttachment.id)\\n                .outerjoin(\\n                    FlowVersion,\\n                    FlowVersion.id == FlowVersionDeploymentAttachment.flow_version_id,\\n                )\\n                .where(FlowVersion.id.is_(None))\\n            )\\n        ).all()\\n        assert doubly_orphans == []\\n\\n\\n# ===========================================================================\\n# list_deployments_page excludes orphan flow-version attachments from counts\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestListDeploymentsPageAttachmentCount:\\n    async def test_counts_only_live_flow_version_attachments(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment, provider_account\\n    ):\\n        v1 = await _create_version(db, flow, user, n=1)\\n        await _attach(db, user, v1, deployment)\\n\\n        page = await list_deployments_page(\\n            db,\\n            user_id=user.id,\\n            row_owner_id=user.id,\\n            deployment_provider_account_id=provider_account.id,\\n            offset=0,\\n            limit=10,\\n        )\\n        assert len(page) == 1\\n        dep, attached_count, _matched = page[0]\\n        assert dep.id == deployment.id\\n        assert attached_count == 1\\n\\n    async def test_orphan_flow_version_attachment_excluded_from_count(\\n        self, db: AsyncSession, flow: Flow, user: User, deployment: Deployment, provider_account\\n    ):\\n        v1 = await _create_version(db, flow, user, n=1)\\n        await _attach(db, user, v1, deployment)\\n\\n        v2 = await _create_version(db, flow, user, n=2)\\n        await _attach(db, user, v2, deployment, snapshot_id=\\\"snap-2\\\")\\n\\n        page = await list_deployments_page(\\n            db,\\n            user_id=user.id,\\n            row_owner_id=user.id,\\n            deployment_provider_account_id=provider_account.id,\\n            offset=0,\\n            limit=10,\\n        )\\n        _, count_before, _ = page[0]\\n        assert count_before == 2\\n\\n        # Delete v2, leaving an orphan attachment (FK cascade cleans it in\\n        # real environments, but verify the join-based count is resilient).\\n        await db.delete(v2)\\n        await db.commit()\\n\\n        page = await list_deployments_page(\\n            db,\\n            user_id=user.id,\\n            row_owner_id=user.id,\\n            deployment_provider_account_id=provider_account.id,\\n            offset=0,\\n            limit=10,\\n        )\\n        _, count_after, _ = page[0]\\n        assert count_after == 1\\n\\n\\n# ===========================================================================\\n# Provider-scoped deployment status uses live deployments only\\n# ===========================================================================\\n\\n\\n@pytest.mark.asyncio\\nclass TestGetFlowVersionsWithProviderStatus:\\n    async def test_live_attachment_marks_version_as_deployed(\\n        self,\\n        db: AsyncSession,\\n        flow: Flow,\\n        user: User,\\n        deployment: Deployment,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        v1 = await _create_version(db, flow, user, n=1)\\n        await _attach(db, user, v1, deployment)\\n\\n        rows = await get_flow_versions_with_provider_status(\\n            db,\\n            flow.id,\\n            user.id,\\n            provider_account_id=provider_account.id,\\n        )\\n        assert len(rows) == 1\\n        version, is_deployed = rows[0]\\n        assert version.id == v1.id\\n        assert is_deployed is True\\n\\n    async def test_orphan_attachment_does_not_mark_version_as_deployed(\\n        self, db: AsyncSession, flow: Flow, user: User, provider_account: DeploymentProviderAccount\\n    ):\\n        v1 = await _create_version(db, flow, user, n=1)\\n        await _make_orphan_attachment(db, user, v1)\\n\\n        rows = await get_flow_versions_with_provider_status(\\n            db,\\n            flow.id,\\n            user.id,\\n            provider_account_id=provider_account.id,\\n        )\\n        assert len(rows) == 1\\n        _, is_deployed = rows[0]\\n        assert is_deployed is False\\n\\n    async def test_mixed_live_and_orphan_only_live_counts(\\n        self,\\n        db: AsyncSession,\\n        flow: Flow,\\n        user: User,\\n        deployment: Deployment,\\n        provider_account: DeploymentProviderAccount,\\n    ):\\n        v1 = await _create_version(db, flow, user, n=1)\\n        await _attach(db, user, v1, deployment)\\n\\n        v2 = await _create_version(db, flow, user, n=2)\\n        await _make_orphan_attachment(db, user, v2)\\n\\n        rows = await get_flow_versions_with_provider_status(\\n            db,\\n            flow.id,\\n            user.id,\\n            provider_account_id=provider_account.id,\\n        )\\n        by_id = {version.id: is_deployed for version, is_deployed in rows}\\n        assert by_id[v1.id] is True\\n        assert by_id[v2.id] is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/database/models/flow_version/test_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7c9b9e34eb71818c1577d5c090b29afb8f8e91263902033677a47f3d9235d3e5\",\"content\":\"\\\"\\\"\\\"Schema contracts for the ``flow_version`` model.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.services.database.models.flow_version.model import VERSION_NUMBER_CHECK_NAME, FlowVersion\\nfrom sqlalchemy import CheckConstraint, Column, Integer, MetaData, Table\\nfrom sqlalchemy.sql.naming import conv\\n\\n# Mirrors NAMING_CONVENTION in ``langflow/alembic/env.py`` (env.py cannot be imported: it runs migrations on import).\\n_NAMING_CONVENTION = {\\n    \\\"ix\\\": \\\"ix_%(column_0_label)s\\\",\\n    \\\"uq\\\": \\\"uq_%(table_name)s_%(column_0_name)s\\\",\\n    \\\"ck\\\": \\\"ck_%(table_name)s_%(constraint_name)s\\\",\\n    \\\"fk\\\": \\\"fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s\\\",\\n    \\\"pk\\\": \\\"pk_%(table_name)s\\\",\\n}\\n\\n\\ndef _check_names(table: Table) -> set[str]:\\n    return {constraint.name for constraint in table.constraints if isinstance(constraint, CheckConstraint)}\\n\\n\\ndef test_flow_version_check_name_is_final_and_survives_naming_convention():\\n    \\\"\\\"\\\"The conv()-marked name must not be re-prefixed when the table is copied under env.py's convention.\\\"\\\"\\\"\\n    table = FlowVersion.__table__\\n    check_names = _check_names(table)\\n\\n    assert check_names == {VERSION_NUMBER_CHECK_NAME}\\n    assert all(isinstance(name, conv) for name in check_names)\\n\\n    copied = table.to_metadata(MetaData(naming_convention=_NAMING_CONVENTION))\\n    assert _check_names(copied) == check_names\\n\\n\\ndef test_plain_string_check_name_is_re_prefixed_by_naming_convention():\\n    \\\"\\\"\\\"Negative control: a plain-string name is rewritten by the convention, which is the drift being guarded.\\\"\\\"\\\"\\n    table = Table(\\n        \\\"flow_version\\\",\\n        MetaData(naming_convention=_NAMING_CONVENTION),\\n        Column(\\\"version_number\\\", Integer),\\n        CheckConstraint(\\\"version_number >= 1\\\", name=\\\"check_version_number_positive\\\"),\\n    )\\n\\n    assert _check_names(table) == {\\\"ck_flow_version_check_version_number_positive\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/database/test_orphaned_flow_assignment.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c0c5ce243436ae5a20358e2c55f245ef858388e4c88ba7bc70cb63bbadae457a\",\"content\":\"from types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nfrom langflow.initial_setup.constants import STARTER_FOLDER_NAME\\nfrom langflow.services.database import service as database_service_module\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.deps import get_db_service, session_scope\\nfrom sqlmodel import select\\n\\n\\nasync def test_orphan_assignment_reserves_only_the_ownerless_starter_project(active_user, monkeypatch) -> None:\\n    \\\"\\\"\\\"A user-owned same-name project remains ordinary during orphan adoption.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        system_starter = (\\n            await session.exec(select(Folder).where(Folder.name == STARTER_FOLDER_NAME, Folder.user_id.is_(None)))\\n        ).first()\\n        assert system_starter is not None\\n\\n        user_starter = Folder(name=STARTER_FOLDER_NAME, user_id=active_user.id)\\n        session.add(user_starter)\\n        await session.flush()\\n\\n        system_flow = Flow(name=f\\\"system-{uuid4()}\\\", folder_id=system_starter.id, user_id=None)\\n        user_project_flow = Flow(name=f\\\"user-project-{uuid4()}\\\", folder_id=user_starter.id, user_id=None)\\n        session.add_all([system_flow, user_project_flow])\\n        await session.commit()\\n\\n    settings = SimpleNamespace(auth_settings=SimpleNamespace(AUTO_LOGIN=True, SUPERUSER=\\\"test-superuser\\\"))\\n\\n    async def get_test_superuser(_session, _username):\\n        return SimpleNamespace(id=active_user.id)\\n\\n    monkeypatch.setattr(database_service_module, \\\"get_settings_service\\\", lambda: settings)\\n    monkeypatch.setattr(database_service_module, \\\"get_user_by_username\\\", get_test_superuser)\\n\\n    await get_db_service().assign_orphaned_flows_to_superuser()\\n\\n    async with session_scope() as session:\\n        reloaded_system_flow = await session.get(Flow, system_flow.id)\\n        reloaded_user_project_flow = await session.get(Flow, user_project_flow.id)\\n\\n    assert reloaded_system_flow is not None\\n    assert reloaded_system_flow.user_id is None\\n    assert reloaded_user_project_flow is not None\\n    assert reloaded_user_project_flow.user_id == active_user.id\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/flow/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/flow/test_flow_runner.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66155662c18b5948b2ac1eb809fc3461bc3bcbc5b23a696dbfd1a2a9de03d0e0\",\"content\":\"from unittest.mock import AsyncMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.flow.flow_runner import LangflowRunnerExperimental\\n\\n\\n@pytest.fixture\\ndef sample_flow_dict():\\n    return {\\n        \\\"id\\\": str(uuid4()),  # Add required ID field\\n        \\\"name\\\": \\\"test_flow\\\",  # Add name field\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [],\\n            \\\"edges\\\": [],\\n        },\\n    }\\n\\n\\n@pytest.fixture\\ndef flow_runner():\\n    return LangflowRunnerExperimental()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_database_exists_check(flow_runner, monkeypatch):\\n    \\\"\\\"\\\"The runner derives initialization state from Alembic's current heads.\\\"\\\"\\\"\\n    from langflow.services.flow import flow_runner as flow_runner_module\\n\\n    probe = AsyncMock(side_effect=[(\\\"current_head\\\",), ()])\\n    monkeypatch.setattr(flow_runner_module, \\\"get_current_alembic_heads\\\", probe)\\n\\n    assert await flow_runner.database_exists_check() is True\\n    assert await flow_runner.database_exists_check() is False\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_flow_dict_from_dict(flow_runner, sample_flow_dict):\\n    \\\"\\\"\\\"Test loading flow from a dictionary.\\\"\\\"\\\"\\n    result = await flow_runner.get_flow_dict(sample_flow_dict)\\n    assert result == sample_flow_dict\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_flow_dict_invalid_input(flow_runner):\\n    \\\"\\\"\\\"Test loading flow with invalid input type.\\\"\\\"\\\"\\n    pattern = r\\\"Input must be a file path .* or a JSON object .*\\\"\\n    with pytest.raises(TypeError, match=pattern):\\n        await flow_runner.get_flow_dict(123)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_run_with_dict_input(flow_runner, sample_flow_dict):\\n    \\\"\\\"\\\"Test running flow with dictionary input.\\\"\\\"\\\"\\n    session_id = str(uuid4())\\n    input_value = \\\"test input\\\"\\n\\n    result = await flow_runner.run(\\n        session_id=session_id,\\n        flow=sample_flow_dict,\\n        input_value=input_value,\\n    )\\n    assert result is not None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_run_with_different_input_types(flow_runner, sample_flow_dict):\\n    \\\"\\\"\\\"Test running flow with different input and output types.\\\"\\\"\\\"\\n    session_id = str(uuid4())\\n    test_cases = [\\n        (\\\"text input\\\", \\\"text\\\", \\\"text\\\"),\\n        (\\\"chat input\\\", \\\"chat\\\", \\\"chat\\\"),\\n        (\\\"test input\\\", \\\"chat\\\", \\\"all\\\"),  # Updated to use \\\"all\\\" as default output_type\\n    ]\\n\\n    for input_value, input_type, output_type in test_cases:\\n        result = await flow_runner.run(\\n            session_id=session_id,\\n            flow=sample_flow_dict,\\n            input_value=input_value,\\n            input_type=input_type,\\n            output_type=output_type,\\n        )\\n        assert result is not None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_initialize_database(flow_runner, monkeypatch):\\n    \\\"\\\"\\\"Test database initialization.\\\"\\\"\\\"\\n    from langflow.services.flow import flow_runner as flow_runner_module\\n\\n    database_exists_check = AsyncMock(return_value=False)\\n    initialize = AsyncMock()\\n    monkeypatch.setattr(flow_runner, \\\"database_exists_check\\\", database_exists_check)\\n    monkeypatch.setattr(flow_runner_module, \\\"initialize_database\\\", initialize)\\n    flow_runner.should_initialize_db = True\\n\\n    await flow_runner.init_db_if_needed()\\n\\n    database_exists_check.assert_awaited_once()\\n    initialize.assert_awaited_once_with(fix_migration=True)\\n    assert not flow_runner.should_initialize_db\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tasks/test_temp_flow_cleanup.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e8f0516743b6c189996cc04557750e40610e525640583fe4e54b58214c65e71d\",\"content\":\"from __future__ import annotations\\n\\nimport datetime\\nfrom datetime import timezone\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.flow import Flow as FlowTable\\nfrom langflow.services.database.models.message.model import MessageTable\\nfrom langflow.services.deps import get_settings_service, get_storage_service, session_scope\\nfrom langflow.services.task.temp_flow_cleanup import (\\n    CleanupWorker,\\n    cleanup_orphaned_records,\\n)\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_cleanup_orphaned_records_no_orphans():\\n    \\\"\\\"\\\"Test cleanup when there are no orphaned records.\\\"\\\"\\\"\\n    storage_service = get_storage_service()\\n    flow_id = uuid4()\\n\\n    async with session_scope() as session:\\n        # Create a flow and associated message\\n        flow = FlowTable(\\n            id=flow_id,\\n            name=\\\"Test Flow\\\",\\n            data=\\\"null\\\",\\n            updated_at=datetime.datetime.now(timezone.utc),\\n        )\\n        message = MessageTable(\\n            id=uuid4(),\\n            flow_id=flow_id,\\n            sender=\\\"test_user\\\",\\n            sender_name=\\\"Test User\\\",\\n            timestamp=datetime.datetime.now(timezone.utc),\\n            session_id=str(uuid4()),\\n        )\\n        session.add(flow)\\n        session.add(message)\\n        await session.commit()\\n\\n    # Write a file for the flow\\n    await storage_service.save_file(str(flow_id), \\\"test.json\\\", b\\\"test data\\\")\\n\\n    # Run cleanup\\n    async with session_scope() as session:\\n        await cleanup_orphaned_records()\\n\\n    # Verify message still exists\\n    async with session_scope() as session:\\n        message = await session.get(MessageTable, message.id)\\n        assert message is not None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_cleanup_orphaned_records_with_orphans():\\n    \\\"\\\"\\\"Test cleanup when there are orphaned records.\\\"\\\"\\\"\\n    orphaned_flow_id = uuid4()\\n\\n    async with session_scope() as session:\\n        # Create orphaned records without an associated flow\\n        message = MessageTable(\\n            id=uuid4(),\\n            flow_id=orphaned_flow_id,\\n            sender=\\\"test_user\\\",\\n            sender_name=\\\"Test User\\\",\\n            timestamp=datetime.datetime.now(timezone.utc),\\n            session_id=str(uuid4()),\\n        )\\n        session.add(message)\\n        await session.commit()\\n\\n    # Run cleanup\\n    async with session_scope() as session:\\n        await cleanup_orphaned_records()\\n\\n    # Verify orphaned message was deleted\\n    async with session_scope() as session:\\n        message = await session.get(MessageTable, message.id)\\n        assert message is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cleanup_worker_start_stop():\\n    \\\"\\\"\\\"Test CleanupWorker start and stop functionality.\\\"\\\"\\\"\\n    worker = CleanupWorker()\\n    await worker.start()\\n    assert worker._task is not None\\n    assert not worker._stop_event.is_set()\\n    await worker.stop()\\n    assert worker._task is None\\n    assert worker._stop_event.is_set()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cleanup_worker_run_with_exception(mocker):\\n    \\\"\\\"\\\"Test CleanupWorker handles exceptions gracefully.\\\"\\\"\\\"\\n    # Mock the logger to capture log calls\\n    mock_logger = mocker.patch(\\\"langflow.services.task.temp_flow_cleanup.logger\\\")\\n    mock_logger.adebug = mocker.AsyncMock()\\n    mock_logger.awarning = mocker.AsyncMock()\\n\\n    settings = get_settings_service().settings\\n    settings.public_flow_cleanup_interval = 601  # Minimum valid interval\\n    worker = CleanupWorker()\\n\\n    # Start and immediately stop the worker\\n    await worker.start()\\n    await worker.stop()\\n\\n    # Verify the worker was started and stopped properly\\n    assert worker._task is None\\n    assert worker._stop_event.is_set()\\n\\n    # Verify the expected log messages were called\\n    mock_logger.adebug.assert_any_call(\\\"Started database cleanup worker\\\")\\n    mock_logger.adebug.assert_any_call(\\\"Stopping database cleanup worker...\\\")\\n    mock_logger.adebug.assert_any_call(\\\"Database cleanup worker stopped\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_flow_execution_span.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c4109077a9ab007c386a772a8185381f8e3a8b4a3dc416a13d3df8327a56716d\",\"content\":\"\\\"\\\"\\\"The tracer provider is process-global and installed once, so each case runs in a subprocess.\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\nimport tempfile\\nfrom pathlib import Path\\n\\nfrom langflow.services.telemetry.opentelemetry import APPLICATION_INSTRUMENTATION_SCOPES\\nfrom lfx.observability import APPLICATION_TRACER_NAME\\n\\nPROVIDER_SETUP = \\\"\\\"\\\"\\nimport asyncio, json\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export import SimpleSpanProcessor\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\nexporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(SimpleSpanProcessor(exporter))\\ntrace.set_tracer_provider(provider)\\n\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph.graph.base import Graph\\n\\ndef build_graph():\\n    chat_input = ChatInput(_id=\\\"chat-input\\\")\\n    chat_input.set(input_value=\\\"hello operator\\\")\\n    chat_output = ChatOutput(_id=\\\"chat-output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n    return Graph(chat_input, chat_output, flow_id=\\\"11111111-1111-1111-1111-111111111111\\\")\\n\\ndef report(result):\\n    provider.force_flush()\\n    result[\\\"spans\\\"] = [\\n        {\\n            \\\"name\\\": span.name,\\n            \\\"scope\\\": span.instrumentation_scope.name,\\n            \\\"attrs\\\": dict(span.attributes),\\n            \\\"status\\\": span.status.status_code.name,\\n            \\\"description\\\": span.status.description,\\n            \\\"span_id\\\": span.context.span_id,\\n            \\\"parent_span_id\\\": span.parent.span_id if span.parent else None,\\n            \\\"links\\\": [link.context.span_id for link in span.links],\\n        }\\n        for span in exporter.get_finished_spans()\\n    ]\\n    print(\\\"PROBE_RESULT \\\" + json.dumps(result))\\n\\\"\\\"\\\"\\n\\nASYNC_START_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nasync def main():\\n    graph = build_graph()\\n    ran = []\\n    async for step in graph.async_start():\\n        if hasattr(step, \\\"vertex\\\"):\\n            ran.append(step.vertex.id)\\n    report({\\\"ran\\\": ran})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\nARUN_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nasync def main():\\n    graph = build_graph()\\n    run_outputs = await graph.arun(inputs=[{}], outputs=[\\\"chat-output\\\"], session_id=\\\"session-abc\\\")\\n    text = run_outputs[0].outputs[0].results[\\\"message\\\"].text\\n    report({\\\"text\\\": text})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\nSENTINEL = \\\"prompt-text-that-must-not-be-exported\\\"\\n\\nFAILING_PROBE = (\\n    PROVIDER_SETUP\\n    + f\\\"\\\"\\\"\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.schema.message import Message\\n\\nclass Boom(Component):\\n    display_name = \\\"Boom\\\"\\n    inputs = [MessageTextInput(name=\\\"input_value\\\", display_name=\\\"Input\\\")]\\n    outputs = [Output(name=\\\"message\\\", display_name=\\\"Message\\\", method=\\\"explode\\\")]\\n\\n    def explode(self) -> Message:\\n        raise KeyError({SENTINEL!r})\\n\\nasync def main():\\n    chat_input = ChatInput(_id=\\\"chat-input\\\")\\n    chat_input.set(input_value=\\\"hello operator\\\")\\n    boom = Boom(_id=\\\"boom\\\")\\n    boom.set(input_value=chat_input.message_response)\\n    graph = Graph(chat_input, boom, flow_id=\\\"11111111-1111-1111-1111-111111111111\\\")\\n    error = None\\n    try:\\n        await graph.arun(inputs=[{{}}], outputs=[\\\"boom\\\"])\\n    except Exception as exc:  # noqa: BLE001\\n        error = type(exc).__name__\\n    report({{\\\"error\\\": error}})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\n# A Loop runs its body as a subgraph, so without the guard a loop over N items would bury the\\n# operator's flow.execute span under N identical ones.\\nSUBGRAPH_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nasync def main():\\n    graph = build_graph()\\n    graph.prepare()\\n    async with graph.create_subgraph({\\\"chat-input\\\", \\\"chat-output\\\"}) as subgraph:\\n        assert subgraph._is_subgraph is True\\n        spans_before = len(exporter.get_finished_spans())\\n        with subgraph.flow_execution_span():\\n            pass\\n        opened = len(exporter.get_finished_spans()) - spans_before\\n    report({\\\"opened\\\": opened})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\n# A HITL pause is a suspend, not a failure. The resume is a separate span, opened by whichever\\n# runner drives Graph.process next.\\nPAUSED_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nfrom lfx.graph.exceptions import GraphPausedException\\n\\nasync def main():\\n    graph = build_graph()\\n    raised = False\\n    try:\\n        with graph.flow_execution_span():\\n            raise GraphPausedException(checkpoint_id=\\\"checkpoint-1\\\", reason=\\\"waiting on a human\\\")\\n    except GraphPausedException:\\n        raised = True\\n    report({\\\"raised\\\": raised})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\n# flow-as-tool runs a whole child Graph inside a component of the parent flow.\\nNESTED_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nasync def main():\\n    parent = build_graph()\\n    with parent.flow_execution_span():\\n        child = build_graph()\\n        await child.arun(inputs=[{}], outputs=[\\\"chat-output\\\"], session_id=\\\"child-session\\\")\\n    report({})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\n# A driver that outlives its request still has the request's span in context, because\\n# asyncio.create_task copies it. Parenting to a span that has already ended renders as a child\\n# starting after its parent finished, so the run becomes its own root and links back instead.\\nDEAD_PARENT_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nfrom opentelemetry import trace as otel_trace\\n\\nasync def main():\\n    tracer = otel_trace.get_tracer(\\\"probe.request\\\")\\n    request_span = tracer.start_span(\\\"POST /api/v1/build\\\")\\n    request_id = request_span.get_span_context().span_id\\n    with otel_trace.use_span(request_span, end_on_exit=False):\\n        # The route returns here and the work carries on in the copied context.\\n        request_span.end()\\n        graph = build_graph()\\n        await graph.arun(inputs=[{}], outputs=[\\\"chat-output\\\"])\\n    report({\\\"request_span_id\\\": request_id})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\n# The same context, but the request is still open (the v2 stream holds its server span for the\\n# whole response). That is a real parent and must be left as one.\\nLIVE_PARENT_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nfrom opentelemetry import trace as otel_trace\\n\\nasync def main():\\n    tracer = otel_trace.get_tracer(\\\"probe.request\\\")\\n    request_span = tracer.start_span(\\\"POST /api/v2/workflows\\\")\\n    request_id = request_span.get_span_context().span_id\\n    with otel_trace.use_span(request_span, end_on_exit=True):\\n        graph = build_graph()\\n        await graph.arun(inputs=[{}], outputs=[\\\"chat-output\\\"])\\n    report({\\\"request_span_id\\\": request_id})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\nPROTOCOL_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nfrom lfx.observability import execution_protocol\\n\\nasync def main():\\n    graph = build_graph()\\n    with execution_protocol(\\\"webhook\\\"):\\n        await graph.arun(inputs=[{}], outputs=[\\\"chat-output\\\"])\\n    report({})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\n# Several surfaces share one driver (voice reaches the graph through the build loop), so the\\n# inner generic binding must not overwrite the outer one that knows how the request actually\\n# arrived. The pair here is the real one: voice enters through build_flow_and_stream, which\\n# binds v1.build for itself.\\nNESTED_PROTOCOL_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nfrom lfx.observability import execution_protocol, get_execution_protocol\\n\\nasync def main():\\n    graph = build_graph()\\n    with execution_protocol(\\\"voice\\\"):\\n        with execution_protocol(\\\"v1.build\\\"):\\n            inner = get_execution_protocol()\\n            await graph.arun(inputs=[{}], outputs=[\\\"chat-output\\\"])\\n    after = get_execution_protocol()\\n    report({\\\"inner\\\": inner, \\\"after\\\": after})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\n# CancelledError is a BaseException, so an `except Exception` handler never sees it. A user\\n# pressing stop and the v2 execution ceiling both cancel the driver this span wraps.\\nCANCELLED_PROBE = (\\n    PROVIDER_SETUP\\n    + \\\"\\\"\\\"\\nasync def main():\\n    graph = build_graph()\\n    raised = False\\n    try:\\n        with graph.flow_execution_span():\\n            raise asyncio.CancelledError()\\n    except asyncio.CancelledError:\\n        raised = True\\n    report({\\\"raised\\\": raised})\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n)\\n\\nNO_OTEL_PROBE = \\\"\\\"\\\"\\nimport asyncio, json, sys\\n\\nsys.modules[\\\"opentelemetry\\\"] = None\\nsys.modules[\\\"opentelemetry.trace\\\"] = None\\n\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph.graph.base import Graph\\nimport lfx.graph.graph.base as graph_base\\n\\nassert graph_base.otel_trace is None, \\\"guard did not trip\\\"\\n\\nasync def main():\\n    chat_input = ChatInput(_id=\\\"chat-input\\\")\\n    chat_input.set(input_value=\\\"hello operator\\\")\\n    chat_output = ChatOutput(_id=\\\"chat-output\\\")\\n    chat_output.set(input_value=chat_input.message_response)\\n    graph = Graph(chat_input, chat_output, flow_id=\\\"11111111-1111-1111-1111-111111111111\\\")\\n    ran = []\\n    async for step in graph.async_start():\\n        if hasattr(step, \\\"vertex\\\"):\\n            ran.append(step.vertex.id)\\n    print(\\\"PROBE_RESULT \\\" + json.dumps({\\\"ran\\\": ran}))\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe(source: str) -> dict:\\n    # Start from a clean slate so the developer's own OTEL_* vars cannot skew the result.\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    with tempfile.TemporaryDirectory() as tmp:\\n        # A file rather than -c: Component.__init__ reads its own class source with inspect.\\n        probe_path = Path(tmp) / \\\"probe.py\\\"\\n        probe_path.write_text(source, encoding=\\\"utf-8\\\")\\n        completed = subprocess.run(  # noqa: S603\\n            [sys.executable, str(probe_path)],\\n            env=env,\\n            capture_output=True,\\n            text=True,\\n            timeout=300,\\n            check=False,\\n        )\\n    assert completed.returncode == 0, completed.stderr\\n    line = next(ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\"))\\n    return json.loads(line.removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n\\ndef test_lfx_tracer_name_is_allowlisted_by_langflow():\\n    \\\"\\\"\\\"Drift between the two constants would silently drop every application span.\\\"\\\"\\\"\\n    assert APPLICATION_TRACER_NAME in APPLICATION_INSTRUMENTATION_SCOPES\\n\\n\\ndef test_async_start_emits_one_application_span():\\n    result = run_probe(ASYNC_START_PROBE)\\n    assert result[\\\"ran\\\"] == [\\\"chat-input\\\", \\\"chat-output\\\"]\\n\\n    # Exactly one span is also the assertion that no component-level spans are produced.\\n    assert len(result[\\\"spans\\\"]) == 1\\n    span = result[\\\"spans\\\"][0]\\n    assert span[\\\"name\\\"] == \\\"flow.execute\\\"\\n    assert span[\\\"scope\\\"] == APPLICATION_TRACER_NAME\\n    assert span[\\\"attrs\\\"][\\\"flow_id\\\"] == \\\"11111111-1111-1111-1111-111111111111\\\"\\n    assert span[\\\"attrs\\\"][\\\"run_id\\\"]\\n\\n\\ndef test_arun_emits_one_application_span():\\n    result = run_probe(ARUN_PROBE)\\n    assert result[\\\"text\\\"] == \\\"hello operator\\\"\\n\\n    assert len(result[\\\"spans\\\"]) == 1\\n    span = result[\\\"spans\\\"][0]\\n    assert span[\\\"name\\\"] == \\\"flow.execute\\\"\\n    assert span[\\\"scope\\\"] == APPLICATION_TRACER_NAME\\n    assert set(span[\\\"attrs\\\"]) == {\\\"flow_id\\\", \\\"run_id\\\", \\\"session_id\\\", \\\"status\\\"}\\n    assert span[\\\"attrs\\\"][\\\"session_id\\\"] == \\\"session-abc\\\"\\n    assert span[\\\"attrs\\\"][\\\"status\\\"] == \\\"ok\\\"\\n    # No surface bound one, so the attribute is absent rather than guessed. An operator seeing a\\n    # protocol-less flow span is looking at a genuinely unwired path.\\n    assert \\\"protocol\\\" not in span[\\\"attrs\\\"]\\n    assert span[\\\"status\\\"] == \\\"UNSET\\\"\\n\\n\\ndef test_failing_flow_marks_the_span_as_an_error_without_leaking_the_message():\\n    result = run_probe(FAILING_PROBE)\\n    # Graph execution wraps the component failure for the API, but telemetry must classify the\\n    # actionable root cause rather than the wrapper shared by unrelated failures.\\n    assert result[\\\"error\\\"] == \\\"ValueError\\\"\\n\\n    assert len(result[\\\"spans\\\"]) == 1\\n    span = result[\\\"spans\\\"][0]\\n    assert span[\\\"status\\\"] == \\\"ERROR\\\"\\n    assert span[\\\"description\\\"] == \\\"KeyError\\\"\\n    assert span[\\\"attrs\\\"][\\\"status\\\"] == \\\"error\\\"\\n    assert span[\\\"attrs\\\"][\\\"error.type\\\"] == \\\"KeyError\\\"\\n    # The wrapped message embeds component output, which must not reach the operator's APM.\\n    assert SENTINEL not in json.dumps(span)\\n\\n\\ndef test_flow_runs_with_no_opentelemetry_installed():\\n    result = run_probe(NO_OTEL_PROBE)\\n    assert result[\\\"ran\\\"] == [\\\"chat-input\\\", \\\"chat-output\\\"]\\n\\n\\ndef test_subgraph_does_not_open_its_own_span():\\n    result = run_probe(SUBGRAPH_PROBE)\\n    assert result[\\\"opened\\\"] == 0\\n    assert result[\\\"spans\\\"] == []\\n\\n\\ndef test_a_paused_flow_is_not_recorded_as_an_error():\\n    result = run_probe(PAUSED_PROBE)\\n    assert result[\\\"raised\\\"] is True\\n\\n    assert len(result[\\\"spans\\\"]) == 1\\n    span = result[\\\"spans\\\"][0]\\n    # Span status stays UNSET so a pause never counts toward the error rate, but the attribute\\n    # tells a paused run apart from a finished one, which UNSET alone cannot.\\n    assert span[\\\"status\\\"] == \\\"UNSET\\\"\\n    assert span[\\\"attrs\\\"][\\\"status\\\"] == \\\"paused\\\"\\n    assert \\\"error.type\\\" not in span[\\\"attrs\\\"]\\n\\n\\ndef test_a_flow_run_from_inside_a_flow_nests_under_its_caller():\\n    result = run_probe(NESTED_PROBE)\\n\\n    # Child ends first, so it is the one the exporter sees first.\\n    child, parent = result[\\\"spans\\\"]\\n    assert child[\\\"attrs\\\"][\\\"session_id\\\"] == \\\"child-session\\\"\\n    assert child[\\\"parent_span_id\\\"] == parent[\\\"span_id\\\"]\\n\\n\\ndef test_the_span_records_the_surface_the_run_arrived_through():\\n    result = run_probe(PROTOCOL_PROBE)\\n\\n    assert len(result[\\\"spans\\\"]) == 1\\n    assert result[\\\"spans\\\"][0][\\\"attrs\\\"][\\\"protocol\\\"] == \\\"webhook\\\"\\n\\n\\ndef test_an_inner_binding_does_not_overwrite_the_surface_that_took_the_request():\\n    result = run_probe(NESTED_PROTOCOL_PROBE)\\n\\n    assert result[\\\"inner\\\"] == \\\"voice\\\", \\\"the inner generic driver overwrote the real surface\\\"\\n    assert len(result[\\\"spans\\\"]) == 1\\n    assert result[\\\"spans\\\"][0][\\\"attrs\\\"][\\\"protocol\\\"] == \\\"voice\\\"\\n    # Reset on exit, so a worker reusing this task for the next request starts unbound.\\n    assert result[\\\"after\\\"] is None\\n\\n\\ndef test_a_run_that_outlives_its_request_becomes_its_own_root():\\n    \\\"\\\"\\\"A run that outlives its request gets its own trace root.\\n\\n    The v1 build route returns the job_id and keeps working, so its server span is already\\n    closed. A child of a finished parent is a broken trace in any APM that renders the tree.\\n    \\\"\\\"\\\"\\n    result = run_probe(DEAD_PARENT_PROBE)\\n\\n    flow_spans = [span for span in result[\\\"spans\\\"] if span[\\\"name\\\"] == \\\"flow.execute\\\"]\\n    assert len(flow_spans) == 1\\n    span = flow_spans[0]\\n    assert span[\\\"parent_span_id\\\"] is None, \\\"the flow span adopted a parent that had already ended\\\"\\n    # The request stays reachable from the run; it just is not pretended to contain it.\\n    assert span[\\\"links\\\"] == [result[\\\"request_span_id\\\"]]\\n\\n\\ndef test_a_run_inside_a_live_request_still_nests_under_it():\\n    \\\"\\\"\\\"A run inside a still-open request keeps nesting under it.\\n\\n    The other half of the same rule: the v2 stream holds its server span open for the whole\\n    response, so that one is a real parent and detaching it would lose the correlation.\\n    \\\"\\\"\\\"\\n    result = run_probe(LIVE_PARENT_PROBE)\\n\\n    flow_spans = [span for span in result[\\\"spans\\\"] if span[\\\"name\\\"] == \\\"flow.execute\\\"]\\n    assert len(flow_spans) == 1\\n    span = flow_spans[0]\\n    assert span[\\\"parent_span_id\\\"] == result[\\\"request_span_id\\\"]\\n    assert span[\\\"links\\\"] == []\\n\\n\\ndef test_a_cancelled_flow_is_not_recorded_as_a_successful_one():\\n    result = run_probe(CANCELLED_PROBE)\\n    assert result[\\\"raised\\\"] is True\\n\\n    assert len(result[\\\"spans\\\"]) == 1\\n    span = result[\\\"spans\\\"][0]\\n    assert span[\\\"attrs\\\"][\\\"status\\\"] == \\\"cancelled\\\"\\n    # A withdrawn request is not a service fault, so it must not land on the error rate.\\n    assert span[\\\"status\\\"] == \\\"UNSET\\\"\\n    assert \\\"error.type\\\" not in span[\\\"attrs\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/test_flow_version_deployment_attachment_crud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d102ebc6740e64c54493109e3c7e7b67f15086510cc0fc4f56b6b4e3f297f0a\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.api.v1.mappers.deployments.contracts import ProviderSnapshotBinding\\nfrom langflow.services.database.models.deployment.crud import create_deployment\\nfrom langflow.services.database.models.deployment.model import Deployment\\nfrom langflow.services.database.models.deployment_provider_account.crud import create_provider_account\\nfrom langflow.services.database.models.deployment_provider_account.model import DeploymentProviderAccount\\nfrom langflow.services.database.models.deployment_provider_account.schemas import DeploymentProviderKey\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version.model import FlowVersion\\nfrom langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n    create_deployment_attachment,\\n    delete_deployment_attachments_by_keys,\\n    delete_unbound_attachments,\\n    list_attachments_by_deployment_ids,\\n    update_deployment_attachment_provider_snapshot_id,\\n)\\nfrom langflow.services.database.models.flow_version_deployment_attachment.model import FlowVersionDeploymentAttachment\\nfrom langflow.services.database.models.flow_version_deployment_attachment.schema import (\\n    DeploymentAttachmentKeyBatch,\\n)\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.deps import session_scope\\nfrom lfx.services.adapters.deployment.schema import DeploymentType\\n\\nif TYPE_CHECKING:\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nasync def _create_folder(*, user_id):\\n    async with session_scope() as session:\\n        folder = Folder(name=f\\\"project-{uuid4()}\\\", description=None, user_id=user_id)\\n        session.add(folder)\\n        await session.flush()\\n        await session.refresh(folder)\\n        return folder.id\\n\\n\\nasync def _create_flow_versions(*, user_id, folder_id, count: int = 3):\\n    async with session_scope() as session:\\n        flow = Flow(\\n            name=f\\\"flow-{uuid4()}\\\",\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n            user_id=user_id,\\n            folder_id=folder_id,\\n            is_component=False,\\n        )\\n        session.add(flow)\\n        await session.flush()\\n        await session.refresh(flow)\\n\\n        versions: list[FlowVersion] = []\\n        for index in range(1, count + 1):\\n            version = FlowVersion(\\n                flow_id=flow.id,\\n                user_id=user_id,\\n                data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n                version_number=index,\\n            )\\n            session.add(version)\\n            versions.append(version)\\n        await session.flush()\\n        for version in versions:\\n            await session.refresh(version)\\n        return [version.id for version in versions]\\n\\n\\nasync def _create_provider_account(*, user_id):\\n    async with session_scope() as session:\\n        provider_account = await create_provider_account(\\n            session,\\n            user_id=user_id,\\n            name=f\\\"provider-{uuid4()}\\\",\\n            provider_tenant_id=None,\\n            provider_key=\\\"watsonx-orchestrate\\\",\\n            provider_url=\\\"https://test.example.com\\\",\\n            api_key=\\\"test-key\\\",  # pragma: allowlist secret\\n        )\\n        return provider_account.id\\n\\n\\nasync def _create_deployments(*, user_id, folder_id, provider_account_id):\\n    async with session_scope() as session:\\n        dep1 = await create_deployment(\\n            session,\\n            user_id=user_id,\\n            project_id=folder_id,\\n            deployment_provider_account_id=provider_account_id,\\n            resource_key=\\\"agent-1\\\",\\n            display_name=f\\\"dep-1-{uuid4()}\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        dep2 = await create_deployment(\\n            session,\\n            user_id=user_id,\\n            project_id=folder_id,\\n            deployment_provider_account_id=provider_account_id,\\n            resource_key=\\\"agent-2\\\",\\n            display_name=f\\\"dep-2-{uuid4()}\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        return dep1.id, dep2.id\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_unbound_attachments_keeps_matching_bindings(active_user: User):\\n    folder_id = await _create_folder(user_id=active_user.id)\\n    version_ids = await _create_flow_versions(user_id=active_user.id, folder_id=folder_id)\\n    provider_account_id = await _create_provider_account(user_id=active_user.id)\\n    dep1_id, dep2_id = await _create_deployments(\\n        user_id=active_user.id,\\n        folder_id=folder_id,\\n        provider_account_id=provider_account_id,\\n    )\\n\\n    async with session_scope() as session:\\n        keep_dep1 = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n        )\\n        stale_dep1 = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[1],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-stale\\\",\\n        )\\n        keep_dep2 = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[2],\\n            deployment_id=dep2_id,\\n            provider_snapshot_id=\\\"tool-2\\\",\\n        )\\n\\n        deleted_count = await delete_unbound_attachments(\\n            session,\\n            user_id=active_user.id,\\n            provider_account_id=provider_account_id,\\n            deployment_ids=[dep1_id, dep2_id],\\n            bindings=[\\n                ProviderSnapshotBinding(resource_key=\\\"agent-1\\\", snapshot_id=\\\"tool-1\\\"),\\n                ProviderSnapshotBinding(resource_key=\\\"agent-2\\\", snapshot_id=\\\"tool-2\\\"),\\n            ],\\n        )\\n        remaining = await list_attachments_by_deployment_ids(\\n            session,\\n            user_id=active_user.id,\\n            deployment_ids=[dep1_id, dep2_id],\\n        )\\n\\n    remaining_ids = {row.id for row in remaining}\\n    assert deleted_count == 1\\n    assert keep_dep1.id in remaining_ids\\n    assert keep_dep2.id in remaining_ids\\n    assert stale_dep1.id not in remaining_ids\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_unbound_attachments_empty_bindings_deletes_all_attachments(active_user: User):\\n    folder_id = await _create_folder(user_id=active_user.id)\\n    version_ids = await _create_flow_versions(user_id=active_user.id, folder_id=folder_id)\\n    provider_account_id = await _create_provider_account(user_id=active_user.id)\\n    dep1_id, _dep2_id = await _create_deployments(\\n        user_id=active_user.id,\\n        folder_id=folder_id,\\n        provider_account_id=provider_account_id,\\n    )\\n\\n    async with session_scope() as session:\\n        stale_a = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n        )\\n        keep_empty_str = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[1],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-2\\\",\\n        )\\n        keep_null = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[2],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-3\\\",\\n        )\\n\\n        deleted_count = await delete_unbound_attachments(\\n            session,\\n            user_id=active_user.id,\\n            provider_account_id=provider_account_id,\\n            deployment_ids=[dep1_id],\\n            bindings=[],\\n        )\\n        remaining = await list_attachments_by_deployment_ids(\\n            session,\\n            user_id=active_user.id,\\n            deployment_ids=[dep1_id],\\n        )\\n\\n    remaining_ids = {row.id for row in remaining}\\n    assert deleted_count == 3\\n    assert stale_a.id not in remaining_ids\\n    assert keep_empty_str.id not in remaining_ids\\n    assert keep_null.id not in remaining_ids\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_unbound_attachments_empty_deployment_ids_noop(active_user: User):\\n    async with session_scope() as session:\\n        deleted_count = await delete_unbound_attachments(\\n            session,\\n            user_id=active_user.id,\\n            provider_account_id=uuid4(),\\n            deployment_ids=[],\\n            bindings=[ProviderSnapshotBinding(resource_key=\\\"agent-1\\\", snapshot_id=\\\"tool-1\\\")],\\n        )\\n    assert deleted_count == 0\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_unbound_attachments_drops_deployments_outside_provider_scope(active_user: User):\\n    folder_id = await _create_folder(user_id=active_user.id)\\n    version_ids = await _create_flow_versions(user_id=active_user.id, folder_id=folder_id, count=1)\\n    provider_account_id_a = await _create_provider_account(user_id=active_user.id)\\n    provider_account_id_b = await _create_provider_account(user_id=active_user.id)\\n\\n    async with session_scope() as session:\\n        dep_a = await create_deployment(\\n            session,\\n            user_id=active_user.id,\\n            project_id=folder_id,\\n            deployment_provider_account_id=provider_account_id_a,\\n            resource_key=\\\"shared-resource\\\",\\n            display_name=f\\\"dep-a-{uuid4()}\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        dep_b = await create_deployment(\\n            session,\\n            user_id=active_user.id,\\n            project_id=folder_id,\\n            deployment_provider_account_id=provider_account_id_b,\\n            resource_key=\\\"shared-resource\\\",\\n            display_name=f\\\"dep-b-{uuid4()}\\\",\\n            deployment_type=DeploymentType.AGENT,\\n        )\\n        scoped_attachment = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep_a.id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n        )\\n        out_of_scope_attachment = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep_b.id,\\n            provider_snapshot_id=\\\"tool-2\\\",\\n        )\\n\\n        deleted_count = await delete_unbound_attachments(\\n            session,\\n            user_id=active_user.id,\\n            provider_account_id=provider_account_id_a,\\n            deployment_ids=[dep_a.id, dep_b.id],\\n            bindings=[],\\n        )\\n        remaining = await list_attachments_by_deployment_ids(\\n            session,\\n            user_id=active_user.id,\\n            deployment_ids=[dep_a.id, dep_b.id],\\n        )\\n\\n    remaining_ids = {row.id for row in remaining}\\n    assert deleted_count == 1\\n    assert scoped_attachment.id not in remaining_ids\\n    assert out_of_scope_attachment.id in remaining_ids\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_unbound_attachments_in_memory_sqlite_coverage(async_session: AsyncSession):\\n    user = User(\\n        username=f\\\"user-{uuid4()}\\\",\\n        password=\\\"hashed-password\\\",  # noqa: S106  # pragma: allowlist secret\\n        is_active=True,\\n        is_superuser=False,\\n    )\\n    async_session.add(user)\\n    await async_session.flush()\\n\\n    folder = Folder(name=f\\\"project-{uuid4()}\\\", description=None, user_id=user.id)\\n    async_session.add(folder)\\n    await async_session.flush()\\n\\n    flow = Flow(\\n        name=f\\\"flow-{uuid4()}\\\",\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        user_id=user.id,\\n        folder_id=folder.id,\\n        is_component=False,\\n    )\\n    async_session.add(flow)\\n    await async_session.flush()\\n\\n    flow_version = FlowVersion(\\n        flow_id=flow.id,\\n        user_id=user.id,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        version_number=1,\\n    )\\n    async_session.add(flow_version)\\n    await async_session.flush()\\n\\n    provider_account_a = DeploymentProviderAccount(\\n        user_id=user.id,\\n        provider_tenant_id=None,\\n        provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n        name=f\\\"provider-a-{uuid4()}\\\",\\n        provider_url=\\\"https://test-a.example.com\\\",\\n        api_key=\\\"test-key-a\\\",  # pragma: allowlist secret\\n    )\\n    provider_account_b = DeploymentProviderAccount(\\n        user_id=user.id,\\n        provider_tenant_id=None,\\n        provider_key=DeploymentProviderKey.WATSONX_ORCHESTRATE,\\n        name=f\\\"provider-b-{uuid4()}\\\",\\n        provider_url=\\\"https://test-b.example.com\\\",\\n        api_key=\\\"test-key-b\\\",  # pragma: allowlist secret\\n    )\\n    async_session.add(provider_account_a)\\n    async_session.add(provider_account_b)\\n    await async_session.flush()\\n\\n    deployment_a = Deployment(\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account_a.id,\\n        resource_key=\\\"shared-resource\\\",\\n        display_name=f\\\"dep-a-{uuid4()}\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    deployment_b = Deployment(\\n        user_id=user.id,\\n        project_id=folder.id,\\n        deployment_provider_account_id=provider_account_b.id,\\n        resource_key=\\\"shared-resource\\\",\\n        display_name=f\\\"dep-b-{uuid4()}\\\",\\n        deployment_type=DeploymentType.AGENT,\\n    )\\n    async_session.add(deployment_a)\\n    async_session.add(deployment_b)\\n    await async_session.flush()\\n\\n    attachment_a = FlowVersionDeploymentAttachment(\\n        user_id=user.id,\\n        flow_version_id=flow_version.id,\\n        deployment_id=deployment_a.id,\\n        provider_snapshot_id=\\\"tool-1\\\",\\n    )\\n    attachment_b = FlowVersionDeploymentAttachment(\\n        user_id=user.id,\\n        flow_version_id=flow_version.id,\\n        deployment_id=deployment_b.id,\\n        provider_snapshot_id=\\\"tool-2\\\",\\n    )\\n    async_session.add(attachment_a)\\n    async_session.add(attachment_b)\\n    await async_session.flush()\\n\\n    deleted_count = await delete_unbound_attachments(\\n        async_session,\\n        user_id=user.id,\\n        provider_account_id=provider_account_a.id,\\n        deployment_ids=[deployment_a.id, deployment_b.id],\\n        bindings=[],\\n    )\\n    remaining = await list_attachments_by_deployment_ids(\\n        async_session,\\n        user_id=user.id,\\n        deployment_ids=[deployment_a.id, deployment_b.id],\\n    )\\n\\n    remaining_ids = {row.id for row in remaining}\\n    assert deleted_count == 1\\n    assert attachment_a.id not in remaining_ids\\n    assert attachment_b.id in remaining_ids\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_deployment_attachment_rejects_falsy_snapshot_id(active_user: User):\\n    folder_id = await _create_folder(user_id=active_user.id)\\n    version_ids = await _create_flow_versions(user_id=active_user.id, folder_id=folder_id, count=1)\\n    provider_account_id = await _create_provider_account(user_id=active_user.id)\\n    dep1_id, _dep2_id = await _create_deployments(\\n        user_id=active_user.id,\\n        folder_id=folder_id,\\n        provider_account_id=provider_account_id,\\n    )\\n\\n    async with session_scope() as session:\\n        with pytest.raises(ValueError, match=\\\"provider_snapshot_id must not be empty\\\"):\\n            await create_deployment_attachment(\\n                session,\\n                user_id=active_user.id,\\n                flow_version_id=version_ids[0],\\n                deployment_id=dep1_id,\\n                provider_snapshot_id=None,  # type: ignore[arg-type]\\n            )\\n        with pytest.raises(ValueError, match=\\\"provider_snapshot_id must not be empty\\\"):\\n            await create_deployment_attachment(\\n                session,\\n                user_id=active_user.id,\\n                flow_version_id=version_ids[0],\\n                deployment_id=dep1_id,\\n                provider_snapshot_id=\\\"   \\\",\\n            )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_update_deployment_attachment_rejects_falsy_snapshot_id(active_user: User):\\n    folder_id = await _create_folder(user_id=active_user.id)\\n    version_ids = await _create_flow_versions(user_id=active_user.id, folder_id=folder_id, count=1)\\n    provider_account_id = await _create_provider_account(user_id=active_user.id)\\n    dep1_id, _dep2_id = await _create_deployments(\\n        user_id=active_user.id,\\n        folder_id=folder_id,\\n        provider_account_id=provider_account_id,\\n    )\\n\\n    async with session_scope() as session:\\n        attachment = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-1\\\",\\n        )\\n        with pytest.raises(ValueError, match=\\\"provider_snapshot_id must not be empty\\\"):\\n            await update_deployment_attachment_provider_snapshot_id(\\n                session,\\n                attachment=attachment,\\n                provider_snapshot_id=\\\"\\\",\\n            )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_deployment_attachments_by_keys_removes_exact_rows(active_user: User):\\n    folder_id = await _create_folder(user_id=active_user.id)\\n    version_ids = await _create_flow_versions(user_id=active_user.id, folder_id=folder_id)\\n    provider_account_id = await _create_provider_account(user_id=active_user.id)\\n    dep1_id, dep2_id = await _create_deployments(\\n        user_id=active_user.id,\\n        folder_id=folder_id,\\n        provider_account_id=provider_account_id,\\n    )\\n\\n    async with session_scope() as session:\\n        dep1_stale = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-stale\\\",\\n        )\\n        dep1_keep = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[1],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"tool-keep\\\",\\n        )\\n        dep2_keep = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[2],\\n            deployment_id=dep2_id,\\n            provider_snapshot_id=\\\"tool-keep-dep2\\\",\\n        )\\n\\n        deleted_count = await delete_deployment_attachments_by_keys(\\n            session,\\n            user_id=active_user.id,\\n            attachment_key_batch=DeploymentAttachmentKeyBatch(\\n                keys=[\\n                    {\\n                        \\\"deployment_id\\\": dep1_id,\\n                        \\\"flow_version_id\\\": version_ids[0],\\n                    }\\n                ]\\n            ),\\n        )\\n        remaining = await list_attachments_by_deployment_ids(\\n            session,\\n            user_id=active_user.id,\\n            deployment_ids=[dep1_id, dep2_id],\\n        )\\n\\n    remaining_ids = {row.id for row in remaining}\\n    assert deleted_count == 1\\n    assert dep1_stale.id not in remaining_ids\\n    assert dep1_keep.id in remaining_ids\\n    assert dep2_keep.id in remaining_ids\\n\\n\\n@pytest.mark.asyncio\\nasync def test_delete_deployment_attachments_by_keys_avoids_cartesian_cross_delete(active_user: User):\\n    \\\"\\\"\\\"Regression: only exact keys are deleted, not deployment_id x flow_version_id combinations.\\\"\\\"\\\"\\n    folder_id = await _create_folder(user_id=active_user.id)\\n    version_ids = await _create_flow_versions(user_id=active_user.id, folder_id=folder_id, count=4)\\n    provider_account_id = await _create_provider_account(user_id=active_user.id)\\n    dep1_id, dep2_id = await _create_deployments(\\n        user_id=active_user.id,\\n        folder_id=folder_id,\\n        provider_account_id=provider_account_id,\\n    )\\n\\n    async with session_scope() as session:\\n        dep1_target = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"snap-a\\\",\\n        )\\n        dep2_target = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[1],\\n            deployment_id=dep2_id,\\n            provider_snapshot_id=\\\"snap-b\\\",\\n        )\\n        dep1_cross = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[1],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"snap-cross-1\\\",\\n        )\\n        dep2_cross = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[0],\\n            deployment_id=dep2_id,\\n            provider_snapshot_id=\\\"snap-cross-2\\\",\\n        )\\n        dep1_keep = await create_deployment_attachment(\\n            session,\\n            user_id=active_user.id,\\n            flow_version_id=version_ids[2],\\n            deployment_id=dep1_id,\\n            provider_snapshot_id=\\\"snap-keep\\\",\\n        )\\n\\n        deleted_count = await delete_deployment_attachments_by_keys(\\n            session,\\n            user_id=active_user.id,\\n            attachment_key_batch=DeploymentAttachmentKeyBatch(\\n                keys=[\\n                    {\\\"deployment_id\\\": dep1_id, \\\"flow_version_id\\\": version_ids[0]},\\n                    {\\\"deployment_id\\\": dep2_id, \\\"flow_version_id\\\": version_ids[1]},\\n                ]\\n            ),\\n        )\\n        remaining = await list_attachments_by_deployment_ids(\\n            session,\\n            user_id=active_user.id,\\n            deployment_ids=[dep1_id, dep2_id],\\n        )\\n\\n    remaining_ids = {row.id for row in remaining}\\n    assert deleted_count == 2\\n    assert dep1_target.id not in remaining_ids\\n    assert dep2_target.id not in remaining_ids\\n    assert dep1_cross.id in remaining_ids\\n    assert dep2_cross.id in remaining_ids\\n    assert dep1_keep.id in remaining_ids\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/warm_registry/test_warm_flow_resolver.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8b9b8a692f12d7cf3490963a862cec2d6ce3e394d8cd6354d3b53707353e1a80\",\"content\":\"\\\"\\\"\\\"Warm FlowRead resolution without re-selecting executable graph data.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.api.v2 import workflow as workflow_mod\\nfrom langflow.services.database.models.flow.model import FlowRead\\nfrom langflow.services.warm_registry import resolver as resolver_mod\\n\\n\\ndef _snapshot(\\n    *,\\n    flow_id: UUID,\\n    owner_id: UUID,\\n    endpoint_name: str,\\n    name: str,\\n    marker: str,\\n) -> FlowRead:\\n    return FlowRead(\\n        id=flow_id,\\n        name=name,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": [], \\\"marker\\\": marker},\\n        user_id=owner_id,\\n        folder_id=None,\\n        workspace_id=None,\\n        endpoint_name=endpoint_name,\\n        updated_at=datetime(2026, 8, 5, 12, tzinfo=timezone.utc),\\n    )\\n\\n\\ndef _revision(flow: FlowRead) -> tuple[object, ...]:\\n    return (\\n        resolver_mod.flow_version(flow.updated_at),\\n        flow.name,\\n        flow.user_id,\\n        flow.workspace_id,\\n        flow.folder_id,\\n        flow.endpoint_name,\\n        flow.webhook,\\n        flow.access_type,\\n        flow.mcp_enabled,\\n        flow.flow_type,\\n        flow.a2a_enabled,\\n    )\\n\\n\\ndef _metadata_row(flow: FlowRead) -> tuple[object, ...]:\\n    revision = _revision(flow)\\n    return (flow.updated_at, *revision[1:])\\n\\n\\nclass _FakeRegistry:\\n    def __init__(self, snapshots: list[FlowRead]) -> None:\\n        self.snapshots = {str(flow.id): flow for flow in snapshots}\\n        self.aliases = {(str(flow.user_id), flow.endpoint_name): str(flow.id) for flow in snapshots}\\n        self.revisions = {str(flow.id): _revision(flow) for flow in snapshots}\\n        self.endpoint_lookups: list[tuple[str, str]] = []\\n        self.evictions: list[tuple[str, tuple[object, ...]]] = []\\n\\n    def get_flow(self, flow_id: str) -> FlowRead | None:\\n        resolved = self.get_flow_with_revision(flow_id)\\n        return resolved[0] if resolved is not None else None\\n\\n    def get_flow_with_revision(self, flow_id: str) -> tuple[FlowRead, tuple[object, ...]] | None:\\n        flow = self.snapshots.get(flow_id)\\n        revision = self.revisions.get(flow_id)\\n        if flow is None or revision is None:\\n            return None\\n        return flow.model_copy(deep=True), revision\\n\\n    def get_flow_by_endpoint(self, user_id: object, endpoint_name: str) -> FlowRead | None:\\n        resolved = self.get_flow_by_endpoint_with_revision(user_id, endpoint_name)\\n        return resolved[0] if resolved is not None else None\\n\\n    def get_flow_by_endpoint_with_revision(\\n        self,\\n        user_id: object,\\n        endpoint_name: str,\\n    ) -> tuple[FlowRead, tuple[object, ...]] | None:\\n        owner_id = str(user_id)\\n        self.endpoint_lookups.append((owner_id, endpoint_name))\\n        flow_id = self.aliases.get((owner_id, endpoint_name))\\n        return self.get_flow_with_revision(flow_id) if flow_id is not None else None\\n\\n    def get_entry_revision(self, flow_id: str) -> tuple[object, ...] | None:\\n        return self.revisions.get(flow_id)\\n\\n    async def evict_if_revision(self, flow_id: str, revision: tuple[object, ...]) -> bool:\\n        self.evictions.append((flow_id, revision))\\n        if self.revisions.get(flow_id) != revision:\\n            return False\\n        self.revisions.pop(flow_id, None)\\n        self.snapshots.pop(flow_id, None)\\n        return True\\n\\n\\nclass _Result:\\n    def __init__(self, row: tuple[object, ...] | None) -> None:\\n        self.row = row\\n\\n    def first(self):\\n        return self.row\\n\\n\\nclass _Session:\\n    def __init__(self, rows: list[tuple[object, ...] | None]) -> None:\\n        self.rows = rows\\n        self.statements = []\\n\\n    async def exec(self, statement):\\n        self.statements.append(statement)\\n        return _Result(self.rows.pop(0))\\n\\n\\nclass _Scope:\\n    def __init__(self, session: _Session) -> None:\\n        self.session = session\\n\\n    async def __aenter__(self) -> _Session:\\n        return self.session\\n\\n    async def __aexit__(self, *_args) -> None:\\n        return None\\n\\n\\ndef _install_resolver_fakes(monkeypatch, registry: _FakeRegistry, session: _Session) -> None:\\n    monkeypatch.setattr(resolver_mod, \\\"_warm_registry_active\\\", lambda: True)\\n    monkeypatch.setattr(resolver_mod, \\\"get_warm_registry\\\", lambda: registry)\\n    monkeypatch.setattr(resolver_mod, \\\"session_scope\\\", lambda: _Scope(session))\\n\\n\\nasync def test_owner_uuid_hit_selects_only_metadata_and_skips_full_helper(monkeypatch):\\n    owner_id = uuid4()\\n    cached = _snapshot(\\n        flow_id=uuid4(),\\n        owner_id=owner_id,\\n        endpoint_name=\\\"shared-name\\\",\\n        name=\\\"Owner flow\\\",\\n        marker=\\\"cached\\\",\\n    )\\n    registry = _FakeRegistry([cached])\\n    session = _Session([_metadata_row(cached)])\\n    _install_resolver_fakes(monkeypatch, registry, session)\\n    full_resolver = AsyncMock()\\n    monkeypatch.setattr(workflow_mod, \\\"get_flow_by_id_or_endpoint_name\\\", full_resolver)\\n\\n    resolved = await workflow_mod.resolve_flow_for_execution(\\n        str(cached.id),\\n        SimpleNamespace(id=owner_id),\\n    )\\n\\n    assert resolved == cached\\n    assert resolved is not cached\\n    assert resolved.data is not cached.data\\n    full_resolver.assert_not_awaited()\\n    selected_fields = set(session.statements[0].selected_columns.keys())\\n    assert \\\"data\\\" not in selected_fields\\n    assert selected_fields == {\\n        \\\"updated_at\\\",\\n        \\\"name\\\",\\n        \\\"user_id\\\",\\n        \\\"workspace_id\\\",\\n        \\\"folder_id\\\",\\n        \\\"endpoint_name\\\",\\n        \\\"webhook\\\",\\n        \\\"access_type\\\",\\n        \\\"mcp_enabled\\\",\\n        \\\"flow_type\\\",\\n        \\\"a2a_enabled\\\",\\n    }\\n\\n\\nasync def test_same_endpoint_name_is_resolved_in_each_owner_namespace(monkeypatch):\\n    owner_a = uuid4()\\n    owner_b = uuid4()\\n    flow_a = _snapshot(flow_id=uuid4(), owner_id=owner_a, endpoint_name=\\\"same\\\", name=\\\"A\\\", marker=\\\"a\\\")\\n    flow_b = _snapshot(flow_id=uuid4(), owner_id=owner_b, endpoint_name=\\\"same\\\", name=\\\"B\\\", marker=\\\"b\\\")\\n    registry = _FakeRegistry([flow_a, flow_b])\\n    session = _Session([_metadata_row(flow_a), _metadata_row(flow_b)])\\n    _install_resolver_fakes(monkeypatch, registry, session)\\n\\n    resolved_a = await resolver_mod.resolve_warm_flow_for_execution(\\\"same\\\", owner_a)\\n    resolved_b = await resolver_mod.resolve_warm_flow_for_execution(\\\"same\\\", owner_b)\\n\\n    assert resolved_a.id == flow_a.id\\n    assert resolved_b.id == flow_b.id\\n    assert registry.endpoint_lookups == [(str(owner_a), \\\"same\\\"), (str(owner_b), \\\"same\\\")]\\n\\n\\nasync def test_cross_owner_uuid_with_oss_authz_falls_back_to_private_404(monkeypatch):\\n    owner_id = uuid4()\\n    caller_id = uuid4()\\n    cached = _snapshot(flow_id=uuid4(), owner_id=owner_id, endpoint_name=\\\"private\\\", name=\\\"Private\\\", marker=\\\"cached\\\")\\n    registry = _FakeRegistry([cached])\\n    session = _Session([])\\n    _install_resolver_fakes(monkeypatch, registry, session)\\n    authz = SimpleNamespace(\\n        is_enabled=AsyncMock(return_value=False),\\n        supports_cross_user_fetch=AsyncMock(return_value=False),\\n    )\\n    monkeypatch.setattr(resolver_mod, \\\"get_authorization_service\\\", lambda: authz)\\n    full_resolver = AsyncMock(\\n        side_effect=HTTPException(status_code=404, detail=f\\\"Flow identifier {cached.id} not found\\\")\\n    )\\n    monkeypatch.setattr(workflow_mod, \\\"get_flow_by_id_or_endpoint_name\\\", full_resolver)\\n\\n    with pytest.raises(HTTPException) as exc:\\n        await workflow_mod.resolve_flow_for_execution(str(cached.id), SimpleNamespace(id=caller_id))\\n\\n    assert exc.value.status_code == 404\\n    assert exc.value.detail[\\\"code\\\"] == \\\"FLOW_NOT_FOUND\\\"\\n    full_resolver.assert_awaited_once_with(str(cached.id), caller_id, widen_for_shares=True)\\n    assert session.statements == []\\n    assert registry.evictions == []\\n\\n\\nasync def test_share_aware_cross_owner_uuid_validates_metadata_then_returns_snapshot(monkeypatch):\\n    owner_id = uuid4()\\n    caller_id = uuid4()\\n    shared = _snapshot(flow_id=uuid4(), owner_id=owner_id, endpoint_name=\\\"shared\\\", name=\\\"Shared\\\", marker=\\\"cached\\\")\\n    registry = _FakeRegistry([shared])\\n    session = _Session([_metadata_row(shared)])\\n    _install_resolver_fakes(monkeypatch, registry, session)\\n    authz = SimpleNamespace(\\n        is_enabled=AsyncMock(return_value=True),\\n        supports_cross_user_fetch=AsyncMock(return_value=True),\\n    )\\n    monkeypatch.setattr(resolver_mod, \\\"get_authorization_service\\\", lambda: authz)\\n\\n    resolved = await resolver_mod.resolve_warm_flow_for_execution(str(shared.id), caller_id, widen_for_shares=True)\\n\\n    assert resolved == shared\\n    authz.is_enabled.assert_awaited_once()\\n    authz.supports_cross_user_fetch.assert_awaited_once()\\n\\n\\nasync def test_shared_uuid_never_pairs_old_snapshot_with_new_revision(monkeypatch):\\n    \\\"\\\"\\\"A reconcile during async authz checks must not return the superseded payload.\\\"\\\"\\\"\\n    owner_id = uuid4()\\n    caller_id = uuid4()\\n    cached = _snapshot(flow_id=uuid4(), owner_id=owner_id, endpoint_name=\\\"shared\\\", name=\\\"Old\\\", marker=\\\"old\\\")\\n    current = cached.model_copy(\\n        update={\\n            \\\"name\\\": \\\"New\\\",\\n            \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": [], \\\"marker\\\": \\\"new\\\"},\\n            \\\"updated_at\\\": datetime(2026, 8, 5, 13, tzinfo=timezone.utc),\\n        },\\n        deep=True,\\n    )\\n    registry = _FakeRegistry([cached])\\n    session = _Session([_metadata_row(current)])\\n    _install_resolver_fakes(monkeypatch, registry, session)\\n\\n    async def _enable_and_reconcile() -> bool:\\n        registry.snapshots[str(current.id)] = current\\n        registry.revisions[str(current.id)] = _revision(current)\\n        return True\\n\\n    authz = SimpleNamespace(\\n        is_enabled=AsyncMock(side_effect=_enable_and_reconcile),\\n        supports_cross_user_fetch=AsyncMock(return_value=True),\\n    )\\n    monkeypatch.setattr(resolver_mod, \\\"get_authorization_service\\\", lambda: authz)\\n\\n    resolved = await resolver_mod.resolve_warm_flow_for_execution(str(cached.id), caller_id, widen_for_shares=True)\\n\\n    assert resolved is None\\n    assert registry.snapshots[str(current.id)].data[\\\"marker\\\"] == \\\"new\\\"\\n    assert registry.evictions == [(str(cached.id), _revision(cached))]\\n\\n\\nasync def test_metadata_mismatch_evicts_observed_revision_and_falls_back(monkeypatch):\\n    owner_id = uuid4()\\n    cached = _snapshot(flow_id=uuid4(), owner_id=owner_id, endpoint_name=\\\"renamed\\\", name=\\\"Old\\\", marker=\\\"cached\\\")\\n    current = cached.model_copy(update={\\\"name\\\": \\\"New\\\"}, deep=True)\\n    registry = _FakeRegistry([cached])\\n    session = _Session([_metadata_row(current)])\\n    _install_resolver_fakes(monkeypatch, registry, session)\\n    full_resolver = AsyncMock(return_value=current)\\n    monkeypatch.setattr(workflow_mod, \\\"get_flow_by_id_or_endpoint_name\\\", full_resolver)\\n\\n    resolved = await workflow_mod.resolve_flow_for_execution(\\n        str(cached.id),\\n        SimpleNamespace(id=owner_id),\\n    )\\n\\n    assert resolved.name == \\\"New\\\"\\n    assert registry.evictions == [(str(cached.id), _revision(cached))]\\n    full_resolver.assert_awaited_once_with(str(cached.id), owner_id, widen_for_shares=True)\\n\\n\\nasync def test_share_aware_non_owner_endpoint_uses_full_resolver(monkeypatch):\\n    owner_id = uuid4()\\n    caller_id = uuid4()\\n    shared = _snapshot(flow_id=uuid4(), owner_id=owner_id, endpoint_name=\\\"ambiguous\\\", name=\\\"Shared\\\", marker=\\\"cached\\\")\\n    registry = _FakeRegistry([shared])\\n    session = _Session([])\\n    _install_resolver_fakes(monkeypatch, registry, session)\\n    full_resolver = AsyncMock(return_value=shared)\\n    monkeypatch.setattr(workflow_mod, \\\"get_flow_by_id_or_endpoint_name\\\", full_resolver)\\n\\n    resolved = await workflow_mod.resolve_flow_for_execution(\\n        \\\"ambiguous\\\",\\n        SimpleNamespace(id=caller_id),\\n    )\\n\\n    assert resolved.id == shared.id\\n    assert registry.endpoint_lookups == [(str(caller_id), \\\"ambiguous\\\")]\\n    assert session.statements == []\\n    full_resolver.assert_awaited_once_with(\\\"ambiguous\\\", caller_id, widen_for_shares=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_cryptography_dependency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cd7181b1380a333aec29d3a70d274b6036a877edc543a555f4d96763362107f8\",\"content\":\"\\\"\\\"\\\"Guard the cryptography security floor across uv and published extras.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport sys\\nfrom pathlib import Path\\n\\nfrom packaging.markers import default_environment\\nfrom packaging.requirements import Requirement\\nfrom packaging.version import Version\\n\\nif sys.version_info >= (3, 11):\\n    import tomllib\\nelse:\\n    import tomli as tomllib\\n\\nREPO_ROOT = Path(__file__).resolve().parents[4]\\nCRYPTOGRAPHY_FLOOR = Version(\\\"50.0.0\\\")\\nLANGCHAIN_LITELLM_COMPAT_VERSION = Version(\\\"0.5.1\\\")\\n\\nPACKAGE_MANIFESTS = {\\n    \\\"lfx\\\": REPO_ROOT / \\\"src\\\" / \\\"lfx\\\" / \\\"pyproject.toml\\\",\\n    \\\"langflow-base\\\": REPO_ROOT / \\\"src\\\" / \\\"backend\\\" / \\\"base\\\" / \\\"pyproject.toml\\\",\\n}\\nCOMPAT_EXTRAS = {\\n    REPO_ROOT / \\\"src\\\" / \\\"backend\\\" / \\\"base\\\" / \\\"pyproject.toml\\\": {\\n        \\\"cuga\\\": \\\"cuga\\\",\\n    },\\n    REPO_ROOT / \\\"src\\\" / \\\"bundles\\\" / \\\"lfx-bundles\\\" / \\\"pyproject.toml\\\": {\\n        \\\"cuga\\\": \\\"cuga\\\",\\n    },\\n}\\n\\n\\ndef _load_toml(path: Path) -> dict:\\n    with path.open(\\\"rb\\\") as file:\\n        return tomllib.load(file)\\n\\n\\ndef _requirements(specs: list[str], package_name: str) -> list[Requirement]:\\n    return [requirement for spec in specs if (requirement := Requirement(spec)).name.lower() == package_name]\\n\\n\\ndef _is_exact_version(requirement: Requirement, version: Version) -> bool:\\n    return str(requirement.specifier) == f\\\"=={version}\\\"\\n\\n\\ndef _requires_at_least(requirement: Requirement, version: Version) -> bool:\\n    return requirement.marker is None and any(\\n        specifier.operator == \\\">=\\\" and Version(specifier.version) >= version for specifier in requirement.specifier\\n    )\\n\\n\\ndef _is_active(requirement: Requirement, environment: dict[str, str]) -> bool:\\n    return requirement.marker is None or requirement.marker.evaluate(environment)\\n\\n\\ndef test_published_core_packages_require_patched_cryptography() -> None:\\n    \\\"\\\"\\\"Both independently installable core wheels must carry the fixed floor.\\\"\\\"\\\"\\n    for package_name, manifest_path in PACKAGE_MANIFESTS.items():\\n        dependencies = _load_toml(manifest_path)[\\\"project\\\"][\\\"dependencies\\\"]\\n        cryptography = _requirements(dependencies, \\\"cryptography\\\")\\n\\n        assert len(cryptography) == 1, f\\\"Expected one cryptography dependency in {package_name}\\\"\\n        assert _requires_at_least(cryptography[0], CRYPTOGRAPHY_FLOOR)\\n\\n\\ndef test_uv_overrides_enforce_the_security_floor_and_compatibility_valve() -> None:\\n    \\\"\\\"\\\"Universal uv resolution must not retain a vulnerable or incompatible fork.\\\"\\\"\\\"\\n    overrides = _load_toml(REPO_ROOT / \\\"pyproject.toml\\\")[\\\"tool\\\"][\\\"uv\\\"][\\\"override-dependencies\\\"]\\n\\n    cryptography = _requirements(overrides, \\\"cryptography\\\")\\n    assert len(cryptography) == 1\\n    assert _requires_at_least(cryptography[0], CRYPTOGRAPHY_FLOOR)\\n\\n    langchain_litellm = _requirements(overrides, \\\"langchain-litellm\\\")\\n    assert len(langchain_litellm) == 1\\n    assert _is_exact_version(langchain_litellm[0], LANGCHAIN_LITELLM_COMPAT_VERSION)\\n\\n\\ndef test_floor_guard_rejects_excluding_only_one_vulnerable_version() -> None:\\n    vulnerable_requirement = Requirement(\\\"cryptography>=48.0.1,!=49.0.0\\\")\\n    assert not _requires_at_least(vulnerable_requirement, CRYPTOGRAPHY_FLOOR)\\n\\n\\ndef test_pip_facing_extras_pin_the_highest_cryptography_50_compatible_release() -> None:\\n    \\\"\\\"\\\"CUGA wheel metadata must expose the uv compatibility choice to pip.\\\"\\\"\\\"\\n    environments = []\\n    for python_version in (\\\"3.10\\\", \\\"3.11\\\", \\\"3.12\\\", \\\"3.13\\\", \\\"3.14\\\"):\\n        for sys_platform, platform_machine in (\\n            (\\\"linux\\\", \\\"x86_64\\\"),\\n            (\\\"win32\\\", \\\"AMD64\\\"),\\n            (\\\"darwin\\\", \\\"arm64\\\"),\\n            (\\\"darwin\\\", \\\"x86_64\\\"),\\n        ):\\n            environment = default_environment()\\n            environment.update(\\n                {\\n                    \\\"python_full_version\\\": f\\\"{python_version}.0\\\",\\n                    \\\"python_version\\\": python_version,\\n                    \\\"sys_platform\\\": sys_platform,\\n                    \\\"platform_machine\\\": platform_machine,\\n                }\\n            )\\n            environments.append(environment)\\n\\n    for manifest_path, extras in COMPAT_EXTRAS.items():\\n        optional_dependencies = _load_toml(manifest_path)[\\\"project\\\"][\\\"optional-dependencies\\\"]\\n        for extra_name, upstream_name in extras.items():\\n            extra = optional_dependencies[extra_name]\\n            upstream_requirements = _requirements(extra, upstream_name)\\n            compat_requirements = _requirements(extra, \\\"langchain-litellm\\\")\\n\\n            assert upstream_requirements, f\\\"Missing {upstream_name} dependency in {manifest_path}:{extra_name}\\\"\\n            assert compat_requirements, f\\\"Missing langchain-litellm pin in {manifest_path}:{extra_name}\\\"\\n            assert all(\\n                _is_exact_version(requirement, LANGCHAIN_LITELLM_COMPAT_VERSION) for requirement in compat_requirements\\n            )\\n            for environment in environments:\\n                assert any(_is_active(requirement, environment) for requirement in upstream_requirements) == any(\\n                    _is_active(requirement, environment) for requirement in compat_requirements\\n                )\\n\\n\\ndef test_lock_contains_only_patched_cryptography_and_explicit_compat_release() -> None:\\n    packages = _load_toml(REPO_ROOT / \\\"uv.lock\\\")[\\\"package\\\"]\\n    cryptography_versions = {Version(package[\\\"version\\\"]) for package in packages if package[\\\"name\\\"] == \\\"cryptography\\\"}\\n    langchain_litellm_versions = {\\n        Version(package[\\\"version\\\"]) for package in packages if package[\\\"name\\\"] == \\\"langchain-litellm\\\"\\n    }\\n\\n    assert cryptography_versions\\n    assert min(cryptography_versions) >= CRYPTOGRAPHY_FLOOR\\n    assert langchain_litellm_versions == {LANGCHAIN_LITELLM_COMPAT_VERSION}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_expand_flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"05834dc9afc99e047dbbf011b6a3fcbb7307a0a0cd692f04614c95761d385055\",\"content\":\"\\\"\\\"\\\"Tests for expand_compact_flow functionality.\\\"\\\"\\\"\\n\\nimport pytest\\nfrom fastapi import status\\nfrom httpx import AsyncClient\\nfrom langflow.processing.expand_flow import (\\n    CompactEdge,\\n    CompactNode,\\n    _expand_edge,\\n    _expand_node,\\n    _get_flat_components,\\n    expand_compact_flow,\\n)\\n\\n# Sample component data mimicking the component_index structure\\nSAMPLE_COMPONENTS = {\\n    \\\"inputs\\\": {\\n        \\\"ChatInput\\\": {\\n            \\\"display_name\\\": \\\"Chat Input\\\",\\n            \\\"description\\\": \\\"Receives text input from user\\\",\\n            \\\"template\\\": {\\n                \\\"_type\\\": \\\"ChatInput\\\",\\n                \\\"input_value\\\": {\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"required\\\": False,\\n                    \\\"value\\\": \\\"\\\",\\n                    \\\"display_name\\\": \\\"Input\\\",\\n                },\\n            },\\n            \\\"base_classes\\\": [\\\"Message\\\"],\\n            \\\"outputs\\\": [\\n                {\\n                    \\\"name\\\": \\\"message\\\",\\n                    \\\"display_name\\\": \\\"Message\\\",\\n                    \\\"types\\\": [\\\"Message\\\"],\\n                }\\n            ],\\n        },\\n    },\\n    \\\"outputs\\\": {\\n        \\\"ChatOutput\\\": {\\n            \\\"display_name\\\": \\\"Chat Output\\\",\\n            \\\"description\\\": \\\"Displays text output to user\\\",\\n            \\\"template\\\": {\\n                \\\"_type\\\": \\\"ChatOutput\\\",\\n                \\\"input_value\\\": {\\n                    \\\"type\\\": \\\"Message\\\",\\n                    \\\"required\\\": True,\\n                    \\\"value\\\": \\\"\\\",\\n                    \\\"display_name\\\": \\\"Text\\\",\\n                    \\\"input_types\\\": [\\\"Message\\\"],\\n                },\\n            },\\n            \\\"base_classes\\\": [\\\"Message\\\"],\\n            \\\"outputs\\\": [\\n                {\\n                    \\\"name\\\": \\\"message\\\",\\n                    \\\"display_name\\\": \\\"Message\\\",\\n                    \\\"types\\\": [\\\"Message\\\"],\\n                }\\n            ],\\n        },\\n    },\\n    \\\"models\\\": {\\n        \\\"OpenAIModel\\\": {\\n            \\\"display_name\\\": \\\"OpenAI\\\",\\n            \\\"description\\\": \\\"OpenAI language models\\\",\\n            \\\"template\\\": {\\n                \\\"_type\\\": \\\"OpenAIModel\\\",\\n                \\\"model_name\\\": {\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"required\\\": False,\\n                    \\\"value\\\": \\\"gpt-4o-mini\\\",\\n                    \\\"display_name\\\": \\\"Model Name\\\",\\n                },\\n                \\\"temperature\\\": {\\n                    \\\"type\\\": \\\"float\\\",\\n                    \\\"required\\\": False,\\n                    \\\"value\\\": 0.1,\\n                    \\\"display_name\\\": \\\"Temperature\\\",\\n                },\\n                \\\"input_value\\\": {\\n                    \\\"type\\\": \\\"Message\\\",\\n                    \\\"required\\\": True,\\n                    \\\"value\\\": \\\"\\\",\\n                    \\\"display_name\\\": \\\"Input\\\",\\n                    \\\"input_types\\\": [\\\"Message\\\"],\\n                },\\n            },\\n            \\\"base_classes\\\": [\\\"Message\\\", \\\"LanguageModel\\\"],\\n            \\\"outputs\\\": [\\n                {\\n                    \\\"name\\\": \\\"text_output\\\",\\n                    \\\"display_name\\\": \\\"Text\\\",\\n                    \\\"types\\\": [\\\"Message\\\"],\\n                },\\n                {\\n                    \\\"name\\\": \\\"model\\\",\\n                    \\\"display_name\\\": \\\"Model\\\",\\n                    \\\"types\\\": [\\\"LanguageModel\\\"],\\n                },\\n            ],\\n        },\\n    },\\n}\\n\\n\\nclass TestGetFlatComponents:\\n    def test_flattens_component_dict(self):\\n        flat = _get_flat_components(SAMPLE_COMPONENTS)\\n        assert \\\"ChatInput\\\" in flat\\n        assert \\\"ChatOutput\\\" in flat\\n        assert \\\"OpenAIModel\\\" in flat\\n        assert len(flat) == 3\\n\\n    def test_empty_dict(self):\\n        flat = _get_flat_components({})\\n        assert flat == {}\\n\\n\\nclass TestExpandNode:\\n    def test_expand_simple_node(self):\\n        compact = CompactNode(id=\\\"1\\\", type=\\\"ChatInput\\\")\\n        flat = _get_flat_components(SAMPLE_COMPONENTS)\\n\\n        expanded = _expand_node(compact, flat)\\n\\n        assert expanded[\\\"id\\\"] == \\\"1\\\"\\n        assert expanded[\\\"type\\\"] == \\\"genericNode\\\"\\n        assert expanded[\\\"data\\\"][\\\"type\\\"] == \\\"ChatInput\\\"\\n        assert \\\"template\\\" in expanded[\\\"data\\\"][\\\"node\\\"]\\n\\n    def test_expand_node_with_values(self):\\n        compact = CompactNode(\\n            id=\\\"2\\\",\\n            type=\\\"OpenAIModel\\\",\\n            values={\\\"model_name\\\": \\\"gpt-4\\\", \\\"temperature\\\": 0.7},\\n        )\\n        flat = _get_flat_components(SAMPLE_COMPONENTS)\\n\\n        expanded = _expand_node(compact, flat)\\n\\n        assert expanded[\\\"data\\\"][\\\"type\\\"] == \\\"OpenAIModel\\\"\\n        template = expanded[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        assert template[\\\"model_name\\\"][\\\"value\\\"] == \\\"gpt-4\\\"\\n        assert template[\\\"temperature\\\"][\\\"value\\\"] == 0.7\\n\\n    def test_expand_node_unknown_type_raises(self):\\n        compact = CompactNode(id=\\\"1\\\", type=\\\"UnknownComponent\\\")\\n        flat = _get_flat_components(SAMPLE_COMPONENTS)\\n\\n        with pytest.raises(ValueError, match=\\\"not found in component index\\\"):\\n            _expand_node(compact, flat)\\n\\n    def test_expand_edited_node(self):\\n        custom_node_data = {\\n            \\\"template\\\": {\\\"custom_field\\\": {\\\"value\\\": \\\"custom\\\"}},\\n            \\\"outputs\\\": [],\\n        }\\n        compact = CompactNode(\\n            id=\\\"1\\\",\\n            type=\\\"CustomComponent\\\",\\n            edited=True,\\n            node=custom_node_data,\\n        )\\n        flat = _get_flat_components(SAMPLE_COMPONENTS)\\n\\n        expanded = _expand_node(compact, flat)\\n\\n        assert expanded[\\\"data\\\"][\\\"node\\\"] == custom_node_data\\n\\n    def test_expand_edited_node_without_node_data_raises(self):\\n        compact = CompactNode(id=\\\"1\\\", type=\\\"CustomComponent\\\", edited=True)\\n        flat = _get_flat_components(SAMPLE_COMPONENTS)\\n\\n        with pytest.raises(ValueError, match=\\\"marked as edited but has no node data\\\"):\\n            _expand_node(compact, flat)\\n\\n\\nclass TestExpandEdge:\\n    def test_expand_edge(self):\\n        compact_edge = CompactEdge(\\n            source=\\\"1\\\",\\n            source_output=\\\"message\\\",\\n            target=\\\"2\\\",\\n            target_input=\\\"input_value\\\",\\n        )\\n        expanded_nodes = {\\n            \\\"1\\\": {\\n                \\\"id\\\": \\\"1\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatInput\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"inputs\\\"][\\\"ChatInput\\\"],\\n                },\\n            },\\n            \\\"2\\\": {\\n                \\\"id\\\": \\\"2\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"OpenAIModel\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"models\\\"][\\\"OpenAIModel\\\"],\\n                },\\n            },\\n        }\\n\\n        expanded = _expand_edge(compact_edge, expanded_nodes)\\n\\n        assert expanded[\\\"source\\\"] == \\\"1\\\"\\n        assert expanded[\\\"target\\\"] == \\\"2\\\"\\n        assert \\\"sourceHandle\\\" in expanded\\n        assert \\\"targetHandle\\\" in expanded\\n        assert \\\"id\\\" in expanded\\n        assert expanded[\\\"id\\\"].startswith(\\\"reactflow__edge-\\\")\\n\\n    def test_expand_edge_source_handle_format(self):\\n        \\\"\\\"\\\"Test that sourceHandle is a JSON-encoded dict with \u0153 as quotes.\\\"\\\"\\\"\\n        compact_edge = CompactEdge(\\n            source=\\\"node1\\\",\\n            source_output=\\\"message\\\",\\n            target=\\\"node2\\\",\\n            target_input=\\\"input_value\\\",\\n        )\\n        expanded_nodes = {\\n            \\\"node1\\\": {\\n                \\\"id\\\": \\\"node1\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatInput\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"inputs\\\"][\\\"ChatInput\\\"],\\n                },\\n            },\\n            \\\"node2\\\": {\\n                \\\"id\\\": \\\"node2\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"OpenAIModel\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"models\\\"][\\\"OpenAIModel\\\"],\\n                },\\n            },\\n        }\\n\\n        expanded = _expand_edge(compact_edge, expanded_nodes)\\n\\n        # sourceHandle is JSON-encoded with \u0153 as quotes\\n        source_handle = expanded[\\\"sourceHandle\\\"]\\n        assert \\\"\u0153dataType\u0153\\\" in source_handle\\n        assert \\\"\u0153ChatInput\u0153\\\" in source_handle\\n        assert \\\"\u0153node1\u0153\\\" in source_handle\\n        assert \\\"\u0153message\u0153\\\" in source_handle\\n        assert \\\"\u0153Message\u0153\\\" in source_handle\\n\\n        # data.sourceHandle is the actual dict\\n        source_data = expanded[\\\"data\\\"][\\\"sourceHandle\\\"]\\n        assert source_data[\\\"dataType\\\"] == \\\"ChatInput\\\"\\n        assert source_data[\\\"id\\\"] == \\\"node1\\\"\\n        assert source_data[\\\"name\\\"] == \\\"message\\\"\\n        assert source_data[\\\"output_types\\\"] == [\\\"Message\\\"]\\n\\n    def test_expand_edge_target_handle_format(self):\\n        \\\"\\\"\\\"Test that targetHandle is a JSON-encoded dict with \u0153 as quotes.\\\"\\\"\\\"\\n        compact_edge = CompactEdge(\\n            source=\\\"node1\\\",\\n            source_output=\\\"message\\\",\\n            target=\\\"node2\\\",\\n            target_input=\\\"input_value\\\",\\n        )\\n        expanded_nodes = {\\n            \\\"node1\\\": {\\n                \\\"id\\\": \\\"node1\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatInput\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"inputs\\\"][\\\"ChatInput\\\"],\\n                },\\n            },\\n            \\\"node2\\\": {\\n                \\\"id\\\": \\\"node2\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"OpenAIModel\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"models\\\"][\\\"OpenAIModel\\\"],\\n                },\\n            },\\n        }\\n\\n        expanded = _expand_edge(compact_edge, expanded_nodes)\\n\\n        # targetHandle is JSON-encoded with \u0153 as quotes\\n        target_handle = expanded[\\\"targetHandle\\\"]\\n        assert \\\"\u0153fieldName\u0153\\\" in target_handle\\n        assert \\\"\u0153input_value\u0153\\\" in target_handle\\n        assert \\\"\u0153node2\u0153\\\" in target_handle\\n        assert \\\"\u0153Message\u0153\\\" in target_handle\\n\\n        # data.targetHandle is the actual dict\\n        target_data = expanded[\\\"data\\\"][\\\"targetHandle\\\"]\\n        assert target_data[\\\"fieldName\\\"] == \\\"input_value\\\"\\n        assert target_data[\\\"id\\\"] == \\\"node2\\\"\\n        assert target_data[\\\"inputTypes\\\"] == [\\\"Message\\\"]\\n        assert target_data[\\\"type\\\"] == \\\"Message\\\"\\n\\n    def test_expand_edge_with_multiple_output_types(self):\\n        \\\"\\\"\\\"Test edge from component with multiple output types (e.g., OpenAIModel).\\\"\\\"\\\"\\n        compact_edge = CompactEdge(\\n            source=\\\"model_node\\\",\\n            source_output=\\\"model\\\",  # The LanguageModel output\\n            target=\\\"target_node\\\",\\n            target_input=\\\"some_input\\\",\\n        )\\n        expanded_nodes = {\\n            \\\"model_node\\\": {\\n                \\\"id\\\": \\\"model_node\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"OpenAIModel\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"models\\\"][\\\"OpenAIModel\\\"],\\n                },\\n            },\\n            \\\"target_node\\\": {\\n                \\\"id\\\": \\\"target_node\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatOutput\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"outputs\\\"][\\\"ChatOutput\\\"],\\n                },\\n            },\\n        }\\n\\n        expanded = _expand_edge(compact_edge, expanded_nodes)\\n\\n        # Should use LanguageModel type for \\\"model\\\" output\\n        source_handle = expanded[\\\"sourceHandle\\\"]\\n        assert \\\"LanguageModel\\\" in source_handle\\n\\n    def test_expand_edge_fallback_to_base_classes(self):\\n        \\\"\\\"\\\"Test that edge falls back to base_classes when output not found.\\\"\\\"\\\"\\n        compact_edge = CompactEdge(\\n            source=\\\"node1\\\",\\n            source_output=\\\"nonexistent_output\\\",\\n            target=\\\"node2\\\",\\n            target_input=\\\"input_value\\\",\\n        )\\n        # Component without matching output name\\n        expanded_nodes = {\\n            \\\"node1\\\": {\\n                \\\"id\\\": \\\"node1\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatInput\\\",\\n                    \\\"node\\\": {\\n                        \\\"base_classes\\\": [\\\"Message\\\", \\\"Data\\\"],\\n                        \\\"outputs\\\": [],  # No outputs defined\\n                        \\\"template\\\": {},\\n                    },\\n                },\\n            },\\n            \\\"node2\\\": {\\n                \\\"id\\\": \\\"node2\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"OpenAIModel\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"models\\\"][\\\"OpenAIModel\\\"],\\n                },\\n            },\\n        }\\n\\n        expanded = _expand_edge(compact_edge, expanded_nodes)\\n\\n        # Should fall back to base_classes\\n        source_handle = expanded[\\\"sourceHandle\\\"]\\n        assert \\\"Message\\\" in source_handle or \\\"Data\\\" in source_handle\\n\\n    def test_expand_edge_target_type_fallback(self):\\n        \\\"\\\"\\\"Test that target handle falls back to field type when input_types not present.\\\"\\\"\\\"\\n        compact_edge = CompactEdge(\\n            source=\\\"node1\\\",\\n            source_output=\\\"message\\\",\\n            target=\\\"node2\\\",\\n            target_input=\\\"custom_field\\\",\\n        )\\n        expanded_nodes = {\\n            \\\"node1\\\": {\\n                \\\"id\\\": \\\"node1\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatInput\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"inputs\\\"][\\\"ChatInput\\\"],\\n                },\\n            },\\n            \\\"node2\\\": {\\n                \\\"id\\\": \\\"node2\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"CustomNode\\\",\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"custom_field\\\": {\\n                                \\\"type\\\": \\\"str\\\",  # No input_types, should use type\\n                                \\\"value\\\": \\\"\\\",\\n                            }\\n                        },\\n                        \\\"outputs\\\": [],\\n                    },\\n                },\\n            },\\n        }\\n\\n        expanded = _expand_edge(compact_edge, expanded_nodes)\\n\\n        # data.targetHandle should have \\\"str\\\" as the type and inputTypes\\n        target_data = expanded[\\\"data\\\"][\\\"targetHandle\\\"]\\n        assert target_data[\\\"type\\\"] == \\\"str\\\"\\n        assert target_data[\\\"inputTypes\\\"] == [\\\"str\\\"]\\n\\n    def test_expand_edge_id_uniqueness(self):\\n        \\\"\\\"\\\"Test that edge IDs are unique for different edges.\\\"\\\"\\\"\\n        expanded_nodes = {\\n            \\\"1\\\": {\\n                \\\"id\\\": \\\"1\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatInput\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"inputs\\\"][\\\"ChatInput\\\"],\\n                },\\n            },\\n            \\\"2\\\": {\\n                \\\"id\\\": \\\"2\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"OpenAIModel\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"models\\\"][\\\"OpenAIModel\\\"],\\n                },\\n            },\\n            \\\"3\\\": {\\n                \\\"id\\\": \\\"3\\\",\\n                \\\"type\\\": \\\"genericNode\\\",\\n                \\\"data\\\": {\\n                    \\\"type\\\": \\\"ChatOutput\\\",\\n                    \\\"node\\\": SAMPLE_COMPONENTS[\\\"outputs\\\"][\\\"ChatOutput\\\"],\\n                },\\n            },\\n        }\\n\\n        edge1 = _expand_edge(\\n            CompactEdge(source=\\\"1\\\", source_output=\\\"message\\\", target=\\\"2\\\", target_input=\\\"input_value\\\"),\\n            expanded_nodes,\\n        )\\n        edge2 = _expand_edge(\\n            CompactEdge(source=\\\"2\\\", source_output=\\\"text_output\\\", target=\\\"3\\\", target_input=\\\"input_value\\\"),\\n            expanded_nodes,\\n        )\\n\\n        assert edge1[\\\"id\\\"] != edge2[\\\"id\\\"]\\n\\n    def test_expand_edge_missing_source_raises(self):\\n        compact_edge = CompactEdge(\\n            source=\\\"missing\\\",\\n            source_output=\\\"message\\\",\\n            target=\\\"2\\\",\\n            target_input=\\\"input_value\\\",\\n        )\\n        expanded_nodes = {\\\"2\\\": {\\\"id\\\": \\\"2\\\", \\\"data\\\": {\\\"type\\\": \\\"X\\\", \\\"node\\\": {}}}}\\n\\n        with pytest.raises(ValueError, match=\\\"Source node 'missing' not found\\\"):\\n            _expand_edge(compact_edge, expanded_nodes)\\n\\n    def test_expand_edge_missing_target_raises(self):\\n        compact_edge = CompactEdge(\\n            source=\\\"1\\\",\\n            source_output=\\\"message\\\",\\n            target=\\\"missing\\\",\\n            target_input=\\\"input_value\\\",\\n        )\\n        expanded_nodes = {\\\"1\\\": {\\\"id\\\": \\\"1\\\", \\\"data\\\": {\\\"type\\\": \\\"X\\\", \\\"node\\\": {}}}}\\n\\n        with pytest.raises(ValueError, match=\\\"Target node 'missing' not found\\\"):\\n            _expand_edge(compact_edge, expanded_nodes)\\n\\n\\nclass TestExpandCompactFlow:\\n    def test_expand_simple_flow(self):\\n        compact_data = {\\n            \\\"nodes\\\": [\\n                {\\\"id\\\": \\\"1\\\", \\\"type\\\": \\\"ChatInput\\\"},\\n                {\\\"id\\\": \\\"2\\\", \\\"type\\\": \\\"OpenAIModel\\\", \\\"values\\\": {\\\"model_name\\\": \\\"gpt-4\\\"}},\\n                {\\\"id\\\": \\\"3\\\", \\\"type\\\": \\\"ChatOutput\\\"},\\n            ],\\n            \\\"edges\\\": [\\n                {\\n                    \\\"source\\\": \\\"1\\\",\\n                    \\\"source_output\\\": \\\"message\\\",\\n                    \\\"target\\\": \\\"2\\\",\\n                    \\\"target_input\\\": \\\"input_value\\\",\\n                },\\n                {\\n                    \\\"source\\\": \\\"2\\\",\\n                    \\\"source_output\\\": \\\"text_output\\\",\\n                    \\\"target\\\": \\\"3\\\",\\n                    \\\"target_input\\\": \\\"input_value\\\",\\n                },\\n            ],\\n        }\\n\\n        expanded = expand_compact_flow(compact_data, SAMPLE_COMPONENTS)\\n\\n        assert len(expanded[\\\"nodes\\\"]) == 3\\n        assert len(expanded[\\\"edges\\\"]) == 2\\n\\n        # Check nodes are properly expanded\\n        node_types = {n[\\\"data\\\"][\\\"type\\\"] for n in expanded[\\\"nodes\\\"]}\\n        assert node_types == {\\\"ChatInput\\\", \\\"OpenAIModel\\\", \\\"ChatOutput\\\"}\\n\\n        # Check values were merged\\n        openai_node = next(n for n in expanded[\\\"nodes\\\"] if n[\\\"data\\\"][\\\"type\\\"] == \\\"OpenAIModel\\\")\\n        assert openai_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"model_name\\\"][\\\"value\\\"] == \\\"gpt-4\\\"\\n\\n    def test_expand_flow_no_edges(self):\\n        compact_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"1\\\", \\\"type\\\": \\\"ChatInput\\\"}],\\n            \\\"edges\\\": [],\\n        }\\n\\n        expanded = expand_compact_flow(compact_data, SAMPLE_COMPONENTS)\\n\\n        assert len(expanded[\\\"nodes\\\"]) == 1\\n        assert len(expanded[\\\"edges\\\"]) == 0\\n\\n    def test_expand_flow_unknown_component_raises(self):\\n        compact_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"1\\\", \\\"type\\\": \\\"UnknownComponent\\\"}],\\n            \\\"edges\\\": [],\\n        }\\n\\n        with pytest.raises(ValueError, match=\\\"not found in component index\\\"):\\n            expand_compact_flow(compact_data, SAMPLE_COMPONENTS)\\n\\n\\nclass TestExpandFlowEndpoint:\\n    \\\"\\\"\\\"Integration tests for the /flows/expand endpoint.\\\"\\\"\\\"\\n\\n    async def test_expand_flow_endpoint_requires_auth(self, client: AsyncClient):\\n        \\\"\\\"\\\"Test that endpoint requires authentication.\\\"\\\"\\\"\\n        compact_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"1\\\", \\\"type\\\": \\\"ChatInput\\\"}],\\n            \\\"edges\\\": [],\\n        }\\n\\n        response = await client.post(\\\"api/v1/flows/expand/\\\", json=compact_data)\\n\\n        # Should return 401 or 403 without auth\\n        assert response.status_code in [status.HTTP_401_UNAUTHORIZED, status.HTTP_403_FORBIDDEN]\\n\\n    async def test_expand_flow_endpoint_success(self, client: AsyncClient, logged_in_headers):\\n        compact_data = {\\n            \\\"nodes\\\": [\\n                {\\\"id\\\": \\\"1\\\", \\\"type\\\": \\\"ChatInput\\\"},\\n            ],\\n            \\\"edges\\\": [],\\n        }\\n\\n        response = await client.post(\\\"api/v1/flows/expand/\\\", json=compact_data, headers=logged_in_headers)\\n\\n        # Component might not exist in test env, but endpoint should work\\n        assert response.status_code in [status.HTTP_200_OK, status.HTTP_400_BAD_REQUEST]\\n\\n    async def test_expand_flow_endpoint_invalid_component(self, client: AsyncClient, logged_in_headers):\\n        compact_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"1\\\", \\\"type\\\": \\\"NonExistentComponent12345\\\"}],\\n            \\\"edges\\\": [],\\n        }\\n\\n        response = await client.post(\\\"api/v1/flows/expand/\\\", json=compact_data, headers=logged_in_headers)\\n\\n        assert response.status_code == status.HTTP_400_BAD_REQUEST\\n        assert \\\"not found\\\" in response.json()[\\\"detail\\\"]\\n\\n    async def test_expand_flow_endpoint_invalid_edge(self, client: AsyncClient, logged_in_headers):\\n        compact_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"1\\\", \\\"type\\\": \\\"ChatInput\\\"}],\\n            \\\"edges\\\": [\\n                {\\n                    \\\"source\\\": \\\"missing\\\",\\n                    \\\"source_output\\\": \\\"message\\\",\\n                    \\\"target\\\": \\\"1\\\",\\n                    \\\"target_input\\\": \\\"input_value\\\",\\n                }\\n            ],\\n        }\\n\\n        response = await client.post(\\\"api/v1/flows/expand/\\\", json=compact_data, headers=logged_in_headers)\\n\\n        # Should fail due to missing source node\\n        assert response.status_code == status.HTTP_400_BAD_REQUEST\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_flow_events_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f004e4b3e77528d8fa60bf20ada484dee4bd06607e3ec99b2bb2aea62ef85644\",\"content\":\"import multiprocessing\\nimport time\\n\\nfrom langflow.services.flow_events.service import FlowEventsService\\n\\n\\ndef _worker_append(cache_dir, flow_id, event_type, summary):\\n    \\\"\\\"\\\"Top-level helper used by multiprocessing tests; must be picklable.\\\"\\\"\\\"\\n    svc = FlowEventsService(cache_dir=cache_dir)\\n    svc.append(flow_id, event_type, summary)\\n\\n\\ndef test_append_and_get_events(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Added OpenAI\\\")\\n    svc.append(\\\"flow-1\\\", \\\"connection_added\\\", \\\"Connected to Chat Output\\\")\\n\\n    events, settled = svc.get_since(\\\"flow-1\\\", 0.0)\\n    assert len(events) == 2\\n    assert events[0].type == \\\"component_added\\\"\\n    assert events[1].type == \\\"connection_added\\\"\\n    assert not settled\\n\\n\\ndef test_get_since_filters_by_timestamp(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    e1 = svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"First\\\")\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Second\\\")\\n\\n    events, _ = svc.get_since(\\\"flow-1\\\", e1.timestamp)\\n    assert len(events) == 1\\n    assert events[0].summary == \\\"Second\\\"\\n\\n\\ndef test_settled_on_flow_settled_event(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Added something\\\")\\n    svc.append(\\\"flow-1\\\", \\\"flow_settled\\\", \\\"Done\\\")\\n\\n    events, settled = svc.get_since(\\\"flow-1\\\", 0.0)\\n    assert settled is True\\n    assert any(e.type == \\\"flow_settled\\\" for e in events)\\n\\n\\ndef test_settled_on_timeout(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.SETTLE_TIMEOUT = 0.1\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Added something\\\")\\n\\n    time.sleep(0.15)\\n\\n    _, settled = svc.get_since(\\\"flow-1\\\", 0.0)\\n    assert settled is True\\n\\n\\ndef test_empty_flow_returns_settled(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    events, settled = svc.get_since(\\\"nonexistent\\\", 0.0)\\n    assert events == []\\n    assert settled is True\\n\\n\\ndef test_ttl_cleanup(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.TTL_SECONDS = 0.1\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Old event\\\")\\n\\n    time.sleep(0.15)\\n\\n    # The row should be filtered out by the expires_at >= now() predicate in get_since.\\n    events, _ = svc.get_since(\\\"flow-1\\\", 0.0)\\n    assert len(events) == 0\\n\\n\\ndef test_cursor_ahead_of_all_events_not_settled(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    e = svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Added something\\\")\\n\\n    events, settled = svc.get_since(\\\"flow-1\\\", e.timestamp + 1.0)\\n    assert events == []\\n    assert settled is False  # last event is recent, not past SETTLE_TIMEOUT\\n\\n\\ndef test_cursor_ahead_of_all_events_settled_after_timeout(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.SETTLE_TIMEOUT = 0.1\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Added something\\\")\\n\\n    time.sleep(0.15)\\n\\n    events, settled = svc.get_since(\\\"flow-1\\\", time.time())\\n    assert events == []\\n    assert settled is True  # last event is past SETTLE_TIMEOUT\\n\\n\\ndef test_flow_settled_before_cursor_does_not_settle(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    settled_event = svc.append(\\\"flow-1\\\", \\\"flow_settled\\\", \\\"Done\\\")\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Added after settle\\\")\\n\\n    events, settled = svc.get_since(\\\"flow-1\\\", settled_event.timestamp)\\n    assert len(events) == 1\\n    assert events[0].type == \\\"component_added\\\"\\n    assert settled is False  # flow_settled is before cursor, should not trigger\\n\\n\\ndef test_different_flows_isolated(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Flow 1\\\")\\n    svc.append(\\\"flow-2\\\", \\\"connection_added\\\", \\\"Flow 2\\\")\\n\\n    events_1, _ = svc.get_since(\\\"flow-1\\\", 0.0)\\n    events_2, _ = svc.get_since(\\\"flow-2\\\", 0.0)\\n\\n    assert len(events_1) == 1\\n    assert events_1[0].summary == \\\"Flow 1\\\"\\n    assert len(events_2) == 1\\n    assert events_2[0].summary == \\\"Flow 2\\\"\\n\\n\\ndef test_max_events_per_flow_cap(tmp_path):\\n    svc = FlowEventsService(cache_dir=tmp_path / \\\"cache\\\")\\n    svc.MAX_EVENTS_PER_FLOW = 5\\n\\n    for i in range(10):\\n        svc.append(\\\"flow-1\\\", \\\"component_added\\\", f\\\"Event {i}\\\")\\n\\n    events, _ = svc.get_since(\\\"flow-1\\\", 0.0)\\n    assert len(events) == 5\\n    # Should keep the most recent 5\\n    assert events[0].summary == \\\"Event 5\\\"\\n    assert events[-1].summary == \\\"Event 9\\\"\\n\\n\\ndef test_cross_worker_visibility(tmp_path):\\n    \\\"\\\"\\\"Two separate service instances sharing the same cache dir can see each other's events.\\n\\n    This simulates two uvicorn/gunicorn workers writing and reading from the same disk cache.\\n    \\\"\\\"\\\"\\n    shared_dir = tmp_path / \\\"shared_cache\\\"\\n\\n    worker_a = FlowEventsService(cache_dir=shared_dir)\\n    worker_b = FlowEventsService(cache_dir=shared_dir)\\n\\n    # Worker A appends an event\\n    worker_a.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Added by worker A\\\")\\n\\n    # Worker B should see it\\n    events, settled = worker_b.get_since(\\\"flow-1\\\", 0.0)\\n    assert len(events) == 1\\n    assert events[0].summary == \\\"Added by worker A\\\"\\n    assert not settled\\n\\n    # Worker B appends another event\\n    worker_b.append(\\\"flow-1\\\", \\\"connection_added\\\", \\\"Connected by worker B\\\")\\n\\n    # Worker A should see both\\n    events, _ = worker_a.get_since(\\\"flow-1\\\", 0.0)\\n    assert len(events) == 2\\n    assert events[0].summary == \\\"Added by worker A\\\"\\n    assert events[1].summary == \\\"Connected by worker B\\\"\\n\\n\\ndef test_cross_worker_settle(tmp_path):\\n    \\\"\\\"\\\"Worker A emits events, worker B emits flow_settled, worker A sees settled=True.\\\"\\\"\\\"\\n    shared_dir = tmp_path / \\\"shared_cache\\\"\\n\\n    worker_a = FlowEventsService(cache_dir=shared_dir)\\n    worker_b = FlowEventsService(cache_dir=shared_dir)\\n\\n    worker_a.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Work in progress\\\")\\n    worker_b.append(\\\"flow-1\\\", \\\"flow_settled\\\", \\\"Done\\\")\\n\\n    events, settled = worker_a.get_since(\\\"flow-1\\\", 0.0)\\n    assert settled is True\\n    assert len(events) == 2\\n\\n\\ndef test_cross_worker_flow_isolation(tmp_path):\\n    \\\"\\\"\\\"Events from different flows don't leak across workers.\\\"\\\"\\\"\\n    shared_dir = tmp_path / \\\"shared_cache\\\"\\n\\n    worker_a = FlowEventsService(cache_dir=shared_dir)\\n    worker_b = FlowEventsService(cache_dir=shared_dir)\\n\\n    worker_a.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Flow 1 event\\\")\\n    worker_b.append(\\\"flow-2\\\", \\\"component_added\\\", \\\"Flow 2 event\\\")\\n\\n    events_1, _ = worker_b.get_since(\\\"flow-1\\\", 0.0)\\n    events_2, _ = worker_a.get_since(\\\"flow-2\\\", 0.0)\\n\\n    assert len(events_1) == 1\\n    assert events_1[0].summary == \\\"Flow 1 event\\\"\\n    assert len(events_2) == 1\\n    assert events_2[0].summary == \\\"Flow 2 event\\\"\\n\\n\\ndef test_cross_worker_ttl_expiry(tmp_path):\\n    \\\"\\\"\\\"Expired events are invisible to all workers.\\\"\\\"\\\"\\n    shared_dir = tmp_path / \\\"shared_cache\\\"\\n\\n    worker_a = FlowEventsService(cache_dir=shared_dir)\\n    worker_a.TTL_SECONDS = 0.1\\n    worker_a.append(\\\"flow-1\\\", \\\"component_added\\\", \\\"Short-lived event\\\")\\n\\n    time.sleep(0.15)\\n\\n    worker_b = FlowEventsService(cache_dir=shared_dir)\\n    events, _ = worker_b.get_since(\\\"flow-1\\\", 0.0)\\n    assert len(events) == 0\\n\\n\\ndef test_multi_process_visibility(tmp_path):\\n    \\\"\\\"\\\"A separate OS process can write events that this process reads.\\n\\n    Proves the WAL-mode sqlite backend gives the same cross-worker contract that\\n    the prior diskcache-based implementation did under multi-uvicorn/gunicorn.\\n    \\\"\\\"\\\"\\n    shared_dir = tmp_path / \\\"shared_cache\\\"\\n\\n    # Use spawn so the child does not inherit the parent's sqlite handle.\\n    ctx = multiprocessing.get_context(\\\"spawn\\\")\\n    proc = ctx.Process(\\n        target=_worker_append,\\n        args=(str(shared_dir), \\\"flow-mp\\\", \\\"component_added\\\", \\\"from-other-process\\\"),\\n    )\\n    proc.start()\\n    # Generous bound: a spawned child cold-imports the full langflow package\\n    # (plus coverage's multiprocessing hooks in CI), which can take >10s on a\\n    # loaded CI runner sharing 4 vCPUs with another xdist worker.\\n    proc.join(timeout=60)\\n    if proc.is_alive():\\n        proc.kill()\\n        proc.join(timeout=5)\\n    assert proc.exitcode == 0, \\\"Child process failed to append event\\\"\\n\\n    reader = FlowEventsService(cache_dir=shared_dir)\\n    events, _ = reader.get_since(\\\"flow-mp\\\", 0.0)\\n    assert len(events) == 1\\n    assert events[0].summary == \\\"from-other-process\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_flow_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"15594efdc22b6a4bbd5c52a91d73468a8c4c275d3bb3360f89859cad2f6a5042\",\"content\":\"\\\"\\\"\\\"Tests for flow validation utilities (lfx.utils.flow_validation).\\n\\nCovers:\\n- Hash-based validation: blocked (unknown type) and outdated (hash mismatch)\\n- code_hash_matches_any_template utility\\n- check_flow_and_raise integration\\n- Nested/group node recursion\\n- Security: edited=False with custom code still gets blocked\\n- Shared alias generation for legacy built-in node types\\n- Unified flow validator behavior when custom components are disabled\\n\\\"\\\"\\\"\\n\\nimport hashlib\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom lfx.interface.components import component_cache\\nfrom lfx.utils.flow_validation import (\\n    CustomComponentValidationError,\\n    _compute_code_hash,\\n    _get_invalid_components,\\n    check_flow_and_raise,\\n    code_hash_matches_any_template,\\n    collect_code_by_hash,\\n    collect_component_hash_lookups,\\n    get_trusted_code_for_validation,\\n    validate_flow_for_current_settings,\\n)\\n\\n# ==================== Helpers ====================\\n\\n\\ndef _hash(code: str) -> str:\\n    \\\"\\\"\\\"Compute code hash the same way the component index does.\\\"\\\"\\\"\\n    return hashlib.sha256(code.encode(\\\"utf-8\\\")).hexdigest()[:12]\\n\\n\\ndef _make_node(\\n    *,\\n    node_type: str = \\\"ChatInput\\\",\\n    node_id: str = \\\"node-1\\\",\\n    code: str = \\\"current_code\\\",\\n    edited: bool = False,\\n    display_name: str | None = None,\\n    nested_nodes: list | None = None,\\n) -> dict:\\n    \\\"\\\"\\\"Helper to build a flow node dict.\\\"\\\"\\\"\\n    node_info = {\\n        \\\"template\\\": {\\\"code\\\": {\\\"value\\\": code}},\\n        \\\"edited\\\": edited,\\n    }\\n    if display_name:\\n        node_info[\\\"display_name\\\"] = display_name\\n    if nested_nodes is not None:\\n        node_info[\\\"flow\\\"] = {\\\"data\\\": {\\\"nodes\\\": nested_nodes}}\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"data\\\": {\\n            \\\"type\\\": node_type,\\n            \\\"id\\\": node_id,\\n            \\\"node\\\": node_info,\\n        },\\n    }\\n\\n\\ndef _make_type_hash_dict(\\n    components: dict[str, str | list[str]] | None = None,\\n) -> dict[str, set[str]]:\\n    \\\"\\\"\\\"Helper to build a type_to_current_hash dict.\\n\\n    Args:\\n        components: dict of {component_type: code_string_or_list}\\n            The code is hashed to produce the expected hash.\\n            Pass a list of code strings to register multiple valid hashes per type.\\n    \\\"\\\"\\\"\\n    if components is None:\\n        components = {\\n            \\\"ChatInput\\\": \\\"chat_input_code\\\",\\n            \\\"ChatOutput\\\": \\\"chat_output_code\\\",\\n        }\\n    result: dict[str, set[str]] = {}\\n    for comp_type, code in components.items():\\n        if isinstance(code, list):\\n            result[comp_type] = {_hash(c) for c in code}\\n        else:\\n            result[comp_type] = {_hash(code)}\\n    return result\\n\\n\\n# ==================== Tests ====================\\n\\n\\nclass TestComputeCodeHash:\\n    def test_returns_12_char_hex(self):\\n        result = _compute_code_hash(\\\"some code\\\")\\n        assert len(result) == 12\\n        assert all(c in \\\"0123456789abcdef\\\" for c in result)\\n\\n    def test_consistent(self):\\n        assert _compute_code_hash(\\\"code\\\") == _compute_code_hash(\\\"code\\\")\\n\\n    def test_different_codes_different_hashes(self):\\n        assert _compute_code_hash(\\\"code_a\\\") != _compute_code_hash(\\\"code_b\\\")\\n\\n\\nclass TestGetInvalidComponents:\\n    def test_empty_nodes(self):\\n        blocked, outdated = _get_invalid_components([], {})\\n        assert blocked == []\\n        assert outdated == []\\n\\n    def test_current_code_passes(self):\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"current_code\\\"})\\n        nodes = [_make_node(code=\\\"current_code\\\", node_type=\\\"ChatInput\\\")]\\n        blocked, outdated = _get_invalid_components(nodes, hash_dict)\\n        assert blocked == []\\n        assert outdated == []\\n\\n    def test_unknown_type_is_blocked(self):\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"code\\\"})\\n        nodes = [_make_node(code=\\\"anything\\\", node_type=\\\"TotallyCustom\\\", display_name=\\\"Custom\\\", node_id=\\\"n1\\\")]\\n        blocked, outdated = _get_invalid_components(nodes, hash_dict)\\n        assert len(blocked) == 1\\n        assert \\\"Custom\\\" in blocked[0]\\n        assert outdated == []\\n\\n    def test_hash_mismatch_is_outdated(self):\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"v2_code\\\"})\\n        nodes = [_make_node(code=\\\"v1_code\\\", node_type=\\\"ChatInput\\\", display_name=\\\"Chat Input\\\")]\\n        blocked, outdated = _get_invalid_components(nodes, hash_dict)\\n        assert blocked == []\\n        assert len(outdated) == 1\\n        assert \\\"Chat Input\\\" in outdated[0]\\n\\n    def test_edited_false_with_custom_code_still_blocked(self):\\n        \\\"\\\"\\\"Security: edited=False does NOT prevent blocking when code is unknown type.\\\"\\\"\\\"\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"legitimate_code\\\"})\\n        nodes = [_make_node(code=\\\"evil_code\\\", node_type=\\\"UnknownType\\\", edited=False, display_name=\\\"Sneaky\\\")]\\n        blocked, _outdated = _get_invalid_components(nodes, hash_dict)\\n        assert len(blocked) == 1\\n        assert \\\"Sneaky\\\" in blocked[0]\\n\\n    def test_edited_false_with_modified_code_is_outdated(self):\\n        \\\"\\\"\\\"Security: edited=False with modified code for a known type is caught as outdated.\\\"\\\"\\\"\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"legitimate_code\\\"})\\n        nodes = [_make_node(code=\\\"modified_code\\\", node_type=\\\"ChatInput\\\", edited=False, display_name=\\\"Sneaky\\\")]\\n        blocked, outdated = _get_invalid_components(nodes, hash_dict)\\n        assert blocked == []\\n        assert len(outdated) == 1\\n        assert \\\"Sneaky\\\" in outdated[0]\\n\\n    def test_nested_unknown_type_blocked(self):\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"known\\\"})\\n        inner = _make_node(code=\\\"anything\\\", node_type=\\\"CustomType\\\", display_name=\\\"Nested\\\", node_id=\\\"inner\\\")\\n        outer = _make_node(code=\\\"known\\\", node_type=\\\"ChatInput\\\", nested_nodes=[inner])\\n        blocked, _outdated = _get_invalid_components([outer], hash_dict)\\n        assert len(blocked) == 1\\n        assert \\\"Nested\\\" in blocked[0]\\n\\n    def test_nested_outdated_detection(self):\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"v2\\\"})\\n        inner = _make_node(code=\\\"v1\\\", node_type=\\\"ChatInput\\\", display_name=\\\"Nested Chat\\\")\\n        outer = _make_node(code=\\\"v2\\\", node_type=\\\"ChatInput\\\", nested_nodes=[inner])\\n        blocked, outdated = _get_invalid_components([outer], hash_dict)\\n        assert blocked == []\\n        assert len(outdated) == 1\\n        assert \\\"Nested Chat\\\" in outdated[0]\\n\\n    def test_node_without_code_skipped(self):\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"code\\\"})\\n        node = {\\n            \\\"data\\\": {\\n                \\\"type\\\": \\\"NoCodeNode\\\",\\n                \\\"node\\\": {\\\"template\\\": {}},\\n            }\\n        }\\n        blocked, outdated = _get_invalid_components([node], hash_dict)\\n        assert blocked == []\\n        assert outdated == []\\n\\n\\nclass TestCodeHashMatchesAnyTemplate:\\n    def test_matching_code(self):\\n        known = {_hash(\\\"my_code\\\")}\\n        assert code_hash_matches_any_template(\\\"my_code\\\", known) is True\\n\\n    def test_non_matching_code(self):\\n        known = {_hash(\\\"my_code\\\")}\\n        assert code_hash_matches_any_template(\\\"other_code\\\", known) is False\\n\\n    def test_empty_set(self):\\n        assert code_hash_matches_any_template(\\\"any\\\", set()) is False\\n\\n\\nclass TestCheckFlowAndRaise:\\n    def test_allows_when_custom_components_enabled(self):\\n        \\\"\\\"\\\"Should not raise when allow_custom_components=True.\\\"\\\"\\\"\\n        flow_data = {\\\"nodes\\\": [_make_node(code=\\\"custom_evil_code\\\", edited=True)]}\\n        # Should not raise\\n        check_flow_and_raise(flow_data, allow_custom_components=True)\\n\\n    def test_none_flow_data_ok(self):\\n        check_flow_and_raise(None, allow_custom_components=False)\\n\\n    def test_empty_nodes_ok(self):\\n        check_flow_and_raise({\\\"nodes\\\": []}, allow_custom_components=False)\\n\\n    def test_blocks_unknown_type(self):\\n        \\\"\\\"\\\"Primary path: unknown component type is blocked even with edited=False.\\\"\\\"\\\"\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"known_code\\\"})\\n        flow_data = {\\\"nodes\\\": [_make_node(code=\\\"evil_code\\\", node_type=\\\"CustomEvil\\\", edited=False)]}\\n        with pytest.raises(CustomComponentValidationError, match=\\\"custom components are not allowed\\\"):\\n            check_flow_and_raise(flow_data, allow_custom_components=False, type_to_current_hash=hash_dict)\\n\\n    def test_blocks_outdated_components(self):\\n        \\\"\\\"\\\"Primary path: outdated code (hash mismatch for known type) is blocked.\\\"\\\"\\\"\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"v2_code\\\"})\\n        flow_data = {\\\"nodes\\\": [_make_node(code=\\\"v1_code\\\", node_type=\\\"ChatInput\\\")]}\\n        with pytest.raises(CustomComponentValidationError, match=\\\"outdated components must be updated\\\"):\\n            check_flow_and_raise(flow_data, allow_custom_components=False, type_to_current_hash=hash_dict)\\n\\n    def test_allows_current_code(self):\\n        \\\"\\\"\\\"Primary path: current code passes.\\\"\\\"\\\"\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"current_code\\\"})\\n        flow_data = {\\\"nodes\\\": [_make_node(code=\\\"current_code\\\", node_type=\\\"ChatInput\\\")]}\\n        # Should not raise\\n        check_flow_and_raise(flow_data, allow_custom_components=False, type_to_current_hash=hash_dict)\\n\\n    def test_fail_closed_when_hash_dict_is_none(self):\\n        \\\"\\\"\\\"When type_to_current_hash is None (cache not loaded), all flows are blocked.\\n\\n        This is the fail-closed behavior: if we can't verify code against templates,\\n        we block execution rather than falling back to the client-controlled edited flag.\\n        \\\"\\\"\\\"\\n        flow_data = {\\\"nodes\\\": [_make_node(edited=False)]}\\n        with pytest.raises(CustomComponentValidationError, match=\\\"component templates are still initializing\\\"):\\n            check_flow_and_raise(flow_data, allow_custom_components=False)\\n\\n    def test_fail_closed_blocks_edited_true_without_cache(self):\\n        \\\"\\\"\\\"Fail-closed blocks even edited=True nodes when cache is unavailable.\\\"\\\"\\\"\\n        flow_data = {\\\"nodes\\\": [_make_node(edited=True, display_name=\\\"Edited\\\")]}\\n        with pytest.raises(CustomComponentValidationError, match=\\\"component templates are still initializing\\\"):\\n            check_flow_and_raise(flow_data, allow_custom_components=False)\\n\\n    def test_security_edited_false_custom_code_blocked(self):\\n        \\\"\\\"\\\"Security test: a node with edited=False but modified code MUST be caught.\\n\\n        This is the core security property \u2014 the edited flag is client-controlled\\n        and must not be trusted when type_to_current_hash is available.\\n        \\\"\\\"\\\"\\n        hash_dict = _make_type_hash_dict({\\\"ChatInput\\\": \\\"legitimate_code\\\"})\\n        flow_data = {\\n            \\\"nodes\\";
